W_EXTRA.push({"id":"JSJ","title":"정수정전","unit":"권","persons":{"정수정":{"name":"정수정","alias":["수정","정 원수","청주후","정후","각로","평남후","평북후"],"sex":"F","note":"벽역화의 환생. 남장하고 정국공의 아들로 과거 급제, 평북·정북대원수, 청주후, 좌각로. 장연의 둘째 부인."},"정흠":{"name":"정흠","alias":["정국공","국공","정공","정 상서"],"sex":"M","note":"수정의 아버지. 병부상서 겸 표기장군. 진량의 참소로 절강에 귀양 가 죽음."},"양씨 부인":{"name":"양씨 부인","alias":["국공 부인","양부인","태부인","정렬부인"],"sex":"F","note":"수정의 어머니, 호부상서 양혼의 딸. 수적과 남만에 두 번 붙잡혔다가 구출됨. 88세에 죽음."},"장훈":{"name":"장훈","alias":["장공","장 상서"],"sex":"M","note":"장연의 아버지, 이부상서. 정흠과 자녀의 혼인을 약속하고 백옥홀을 신물로 줌. 일찍 죽음."},"왕부인":{"name":"왕부인","alias":["태부인","왕태부인"],"sex":"F","note":"장연의 어머니. 수정의 시어머니로 영춘 처벌 문제로 수정과 갈등. 90세에 죽음."},"장연":{"name":"장연","alias":["장 한림","장 상서","중군","기주후","장후"],"sex":"M","note":"수정의 정혼자. 장원 급제, 이부상서. 수정의 중군·운량관으로 거듭 곤욕을 치름. 위씨·수정·공주 세 부인을 둠."},"진량":{"name":"진량","alias":["예부상서 진량"],"sex":"M","note":"간신. 정흠을 참소해 죽게 하고, 귀양지에서 남만에 투항해 양씨 납치를 꾀함. 효수됨."},"이춘보":{"name":"이춘보","alias":["춘보","영좌"],"sex":"M","note":"정씨 집 늙은 하인. 정흠의 귀양에 따라가 장례를 치르고, 수적 두목인 척하여 양씨를 구함. 뒤에 군중 교위."},"나호철":{"name":"나호철","alias":["호철"],"sex":"M","note":"절강 출신 수적. 정흠 덕에 사형을 면한 은혜를 갚아 양씨 구출을 도움. 뒤에 절강 총독부 장교."},"황돌쇠":{"name":"황돌쇠","alias":["황가"],"sex":"M","note":"양씨를 아내로 삼으려 끌고 간 수적. 춘보·호철에게 물에 던져짐."},"유모":{"name":"유모","alias":[],"sex":"F","note":"수정과 함께 조난하고 칠보암에서 함께 지내며 함께 남복을 함."},"정현":{"name":"정현","alias":["여승"],"sex":"F","note":"군산 칠보암 여승. 관음보살의 현몽을 받고 수정을 거두며, 때가 되자 과거에 나가라고 권함."},"위 각로":{"name":"위 각로","alias":["위 승상","위 상국"],"sex":"M","note":"장연의 첫 장인."},"위씨":{"name":"위씨","alias":["위부인","원부인"],"sex":"F","note":"위 각로의 딸. 장연의 첫째 부인(원부인)."},"공주":{"name":"공주","alias":["옥주"],"sex":"F","note":"천자가 장연에게 준 배필. 처음엔 천자의 '누이'로, 뒤에는 공주로 나옴. 장연의 셋째 부인."},"영춘":{"name":"영춘","alias":[],"sex":"F","note":"장연의 총첩이자 왕부인이 신임하는 계집종. 수정을 업신여기다 두 번째에 수정에게 참수됨."},"천자":{"name":"천자","alias":["황상","태종","태황제"],"sex":"M","note":"송 태종으로 설정. 수정을 등용하고 정체 탄로 뒤에도 벼슬을 유지시킴. 남만 친정 중 금산성에서 포위됨."},"맹동현":{"name":"맹동현","alias":["맹공"],"sex":"M","note":"예부상서, 뒤에 병부상서·어매 공주의 부마. 천자의 친정을 보좌."},"한복":{"name":"한복","alias":["강서 도독","위수대장"],"sex":"M","note":"수정의 부장. 오랑캐 도성을 기습하고, 위조 편지를 간파해 수정을 말림. 어림장군, 유주목."},"관영":{"name":"관영","alias":["관령"],"sex":"M","note":"진국장군, 1차 출정 선봉. 2차 출정 때 청주성을 지킴."},"진시회":{"name":"진시회","alias":["진시희"],"sex":"M","note":"양주 자사, 후군. 청주에서 수정을 따르며 영춘을 잡아 옴. 청주 별부사마."},"용봉":{"name":"용봉","alias":[],"sex":"M","note":"호위장군. 호산대 어귀에 매복해 철통골을 사로잡음."},"손경":{"name":"손경","alias":[],"sex":"M","note":"기주 자사. 1차 출정 화공에 참여."},"마웅":{"name":"마웅","alias":[],"sex":"M","note":"1차 북방 오랑캐 장수. 수정에게 베임."},"맹돌통":{"name":"맹돌통","alias":[],"sex":"M","note":"마웅의 장수. 수정과 한 합에 베임."},"오평":{"name":"오평","alias":[],"sex":"M","note":"마웅의 장수. 사로잡혀 항복하지 않아 베임."},"철통골":{"name":"철통골","alias":[],"sex":"M","note":"오랑캐 장수. 2차 침입의 선봉, 용봉에게 사로잡혔다가 왕과 함께 용서받음. 1차 전쟁 대목에는 나오지 않다가 '겨우 목숨을 보전'한 자로 처음 등장."},"오랑캐 왕":{"name":"오랑캐 왕","alias":["호왕"],"sex":"M","note":"북방 오랑캐의 왕. 두 번 침입하고 가달국에 원병을 청함. 항복 뒤 용서받음."},"마원":{"name":"마원","alias":[],"sex":"M","note":"마웅의 아우, 2차 침입 대원수. 자신이 보낸 자객 엄백수에게 죽음."},"엄백수":{"name":"엄백수","alias":["백수"],"sex":"M","note":"마원이 보낸 자객. 수정의 위풍에 굴복해 귀순하고 마원의 머리를 바침."},"호철(아문장)":{"name":"호철(아문장)","alias":["호철"],"sex":"M","note":"오랑캐 왕의 사신으로 가달국에 국서를 전함. 나호철과 다른 인물."},"가달왕":{"name":"가달왕","alias":["남만 왕","만왕"],"sex":"M","note":"남만 가달국 왕. 남경을 침공해 천자를 금산성에 포위하고 양씨를 납치함. 항복 뒤 용서받음."},"왕골대":{"name":"왕골대","alias":[],"sex":"M","note":"남만 대장. 주성태·조충국·황흠을 베고 양성초를 사로잡음. 수정에게 베임."},"왕필":{"name":"왕필","alias":[],"sex":"M","note":"왕골대의 아들. 수정에게 사로잡혔다가 포로 교환 때 수정의 화살에 맞음."},"양성초":{"name":"양성초","alias":["양형"],"sex":"M","note":"거기장군, 수정의 외종형으로 소개되나 뒤에서는 수정을 '누님'이라 부름. 왕골대에게 사로잡혔다가 교환됨."},"조충국":{"name":"조충국","alias":[],"sex":"M","note":"하남 절도사. 왕골대에게 베임."},"황흠":{"name":"황흠","alias":[],"sex":"M","note":"아문장. 투항한 진량을 꾸짖다 왕골대에게 베임."},"범수홍":{"name":"범수홍","alias":[],"sex":"M","note":"양성 태수. 2차 침입을 알리고 수정과 군사를 합침."}},"places":{},"paras":[{"c":1,"sub":"","t":"송나라 태종 황제 즉위 십삼 년에 한 재상이 있었으니, 성은 정이요 이름은 흠(欽)이었다. 문장과 무용(武勇)을 겸비하여 일찍 과거에 급제하였고, 벼슬이 일품에 이르러 병부상서 겸 표기장군 정국공에 올랐다. 국공은 사람됨이 순후하고 강직하여 조정과 민간이 모두 그 명망을 칭송하였고, 부귀는 세상에 부러울 것이 없었다. 다만 슬하에 피붙이 하나가 없으니 어찌 가련하지 않겠는가. 그래서 늘 서러워하며 때 없는 한숨과 하염없는 눈물이 이따금 옷깃을 적셨다.","sp":[[4,6,"P","천자"],[106,109,"P","정흠"],[116,118,"P","정흠"]]},{"c":1,"sub":"","t":"하루는 조회를 마치고 집에 돌아오니 때는 마침 늦봄 삼월이었다. 공은 본디 글을 하는 풍류로 가는 봄을 아까워하는 성벽(性癖)이 있었다. 이날은 마침 퇴청한 뒤 한가하였으므로 동자를 불러 술을 가져오게 하여 두세 잔 마신 뒤, 대지팡이를 짚고 후원 꽃밭에 올라 봄 경치를 구경하였다. 엊그제 흐드러지게 피었던 홍도화는 어느덧 시들고, 뾰족뾰족 맺힌 열매가 가지마다 달려 있었다. 뜰의 나무에 깃든 봄새는 새끼를 거느리고 들락날락하였다.","sp":[]},{"c":1,"sub":"","t":"공이 지팡이에 기대어 이 경치 저 경치를 유심히 구경하다가 문득 탄식하여 말하였다. \"저런 초목과 미물도 때를 놓치지 않고 열매를 맺으며 새끼를 품어 낳기까지 이치에 맞게 하거늘, 나 같은 몸은 전생에 무슨 죄로 이생에 태어나 자식 하나가 없는가. 이다음에 죽으면 청산에 버린 백골을 누가 거두어 주며, 선영의 제사는 누구에게 전하겠는가. 슬프다, 이 모양으로 저승에 돌아간들 부모님 얼굴을 어찌 뵈리오. 불효의 죄 삼천 가지 가운데 자식 없는 것이 제일이라 하였으니, 내가 조상께 이런 막대한 죄를 짓고 살아서 무엇 하겠는가.","sp":[]},{"c":1,"sub":"","t":"차라리 어서 죽어 다음 생에 다시 태어나 아들이나 많이 두어 볼까.\" 이렇게 스스로 탄식하며 슬픈 눈물이 옷깃을 적셨다. 부인 양씨는 호부상서 양혼의 딸이었다. 이때 국공의 뒤를 따라 역시 봄 경치를 구경하다가 공이 슬퍼하는 것을 보고 마음이 좋지 못하여 눈물을 머금고 공을 위로하였다. \"상공께서 후사가 없으신 것은 다 첩의 죄입니다. 옛말에 오형(五刑) 가운데 후사 없는 죄가 크다 하였으니, 첩의 죄를 따지자면 벌써 내치셨어야 마땅하나 상공의 너그러우신 덕택으로 오늘날까지 받아들여 주셨으니 그 은혜는 태산도 가벼울 정도입니다.","sp":[[93,95,"P","정흠"]]},{"c":1,"sub":"","t":"더 드릴 말씀은 없거니와, 바라건대 상공께서는 벼슬이 공후에 계시니 두 부인을 두실 만합니다. 다행히 아들을 낳으면 후사를 이을 것이요, 그렇게 되면 첩에게도 이만한 다행이 없겠사오니, 상공께서는 헤아려 주소서.\" 말을 마치며 고운 얼굴에 두 줄기 눈물이 흘러내렸다. 공은 부인이 스스로 허물하는 말과 슬퍼하는 모습을 보니 측은하고 애석한 마음이 전보다 한층 더 일어, 다시금 눈물을 거두고 애틋한 말로 부인을 위로하였다. \"부인은 그런 말씀 마시오. 집안에 자식이 있고 없고는 다 나의 팔자이지 어찌 부인의 허물이라 하겠소.","sp":[]},{"c":1,"sub":"","t":"또한 자식 없는 것이 내 팔자라면 다시 장가든들 꼭 아들을 낳으리라 할 수도 없고, 도리어 집안에 누만 되어 마음만 더욱 불편해질 판이니, 부인의 이 말씀은 결코 따르지 못하겠소.\" 부인은 공의 너그럽고 정대한 말씀을 들으니 더욱 감사하고 부끄러워 몸 둘 곳을 모르다가, 다시 서글픈 빛을 띠고 국공께 여쭈었다. \"옛사람도 자식이 없다가 명산대천에 빌어 귀한 자식을 얻은 일이 종종 있사오니 우리도 한번 시험해 보십시다. 남악 형산은 오악 가운데 제일 크고 천하의 명산이라 하니, 한번 가서 정성이나 드려 보십시다.\"","sp":[[165,167,"P","정흠"]]},{"c":1,"sub":"","t":"공이 탄식하며 말하였다. \"사람의 화복과 팔자는 하늘이 정하신 것이오. 하늘이 주지 않으신 자식을 산에 빈들 무엇 하며, 자식을 빌어서 낳을 수 있다면 세상에 자식 없는 사람이 누가 있겠소.\" 부인이 다시 여쭈었다. \"상공의 말씀이 이치로는 마땅하오나, 옛사람의 일로 보더라도 노나라 숙량흘은 이구산(尼丘山)에 빌어 공부자(孔夫子)를 낳았고, 그뿐 아니라 고금의 충신열사들이 명산대천에 빌어 태어난 이가 많으니, 이로 보면 다 헛일은 아닌 듯합니다. 우리 부부도 한번 정성을 다하여 발원이나 해 보았으면 죽어도 여한이 없겠습니다.\"","sp":[]},{"c":1,"sub":"","t":"공은 부인의 지극한 권유를 물리치지 못하여, 그날부터 부인과 함께 목욕재계하고 떠나 형산에 이르렀다. 산세가 웅장하고 봉우리가 수려하며, 기이한 꽃과 풀, 나는 새와 달리는 짐승이 사철 봄빛을 자랑하니 이른바 별천지였다. 수많은 골짜기와 봉우리 높은 곳에 오색구름이 둘러 있는데, '고깃배가 물을 따라가며 봄 산을 사랑한다(漁舟逐水愛山春)'는 시구처럼 앞길을 점점 나아가 지세를 살핀 뒤, 한 층 제단을 정갈하게 쌓고 노구메를 정성껏 지어 발원하였다. 양씨 부인은 단 아래에서 두 번 절하고, 상서는 단 위에 꿇어앉아 축문을 지어 애절하게 읽었으니 그 글은 이러하였다.","sp":[[253,258,"P","양씨 부인"]]},{"c":1,"sub":"","t":"\"유세차 모년 모월 모일 갑자에, 대송국 남경 동화문 안에 사는 정흠은 산천 신령 앞에 비나이다. 슬프다, 정흠은 대송 태조의 창업공신 정운의 십칠 대손으로 대대로 나라의 녹을 넉넉히 받고 자손이 번성하였는데, 흠에 이르러서는 나이가 기울도록 슬하에 피붙이 하나가 없사오니, 죽은 뒤 백골을 누가 거두어 주며 선영의 제사를 누구에게 전하오리까. 그러므로 조상께 죄인됨을 면치 못하오니 어찌 슬프지 않겠습니까. 엎드려 바라건대 산천 신령께서는 굽어살피시어 피붙이 하나를 점지하시어, 조상께 죄짓는 것을 면하게 해 주시기를 천만 번 바라옵니다.\" 하였다.","sp":[[36,38,"P","정흠"],[60,62,"P","정흠"]]},{"c":1,"sub":"","t":"빌기를 마친 뒤 집으로 돌아와 산신의 영험이 있을까 날마다 바랐다. 하루는 양씨 부인이 마음이 어지러워 잠을 이루지 못하였는데, 때는 마침 사월 보름께였다. 시녀를 데리고 추양각에 올라 휘영청 밝은 달빛을 구경하다가 봄날의 노곤함을 이기지 못하여 난간에 기대어 잠깐 졸았다. 문득 하늘에서 선녀 한 쌍이 오색구름을 타고 공중으로 내려와 부인 앞에 와서 예를 올리고 벽역화 한 가지를 바치며 말하였다. \"부인께서는 우리를 아십니까. 우리는 하늘의 선녀인데, 상제께서 우리를 보내시어 이것을 부인께 드리라 하시기에 이 벽역화를 드리니 부인은 잘 간수하소서.\" 하고 홀연 간데없었다. 부인이 놀라 깨니 남가일몽이었다.","sp":[[42,47,"P","양씨 부인"]]},{"c":1,"sub":"","t":"마음에 이상히 여겨 공중을 향해 무수히 절하여 사례한 뒤 옆을 돌아보니, 인간 세상에서 보지 못하던 꽃 한 가지가 있었다. 괴이히 여겨 구경하려고 한 손으로 집으려 하니 문득 사나운 바람이 일며 그 꽃잎이 낱낱이 떨어졌다. 부인이 이상히 여겨 침실로 돌아와 상공에게 이 일을 낱낱이 전하자, 국공이 다 듣고 그 꿈을 풀어 말하였다. \"꽃이 떨어지면 열매를 맺는 법이니 이는 반드시 자식을 낳을 꿈이로다.\" 그러고는 기쁜 마음을 이기지 못하여 부인과 더불어 정을 나누며 즐겼다. 과연 그달부터 태기가 있어 열 달이 차자, 하루는 공중에 상서로운 구름이 일어나고 서기가 집으로 뻗치며 방 안에 향기가 진동하더니, 이윽고 옥 같은 딸을 낳았다. 난데없이 선녀 한 쌍이 오색구름을 타고 공중에서 내려와 부인 앞에 앉으며 말하였다. \"소녀들은 월궁 항아의 시녀입니다. 항아께서 옥황의 분부를 받고 소녀들을 보내시며 이르시기를, 벽역화는 용궁의 큰 보배요 귀한 화초인데,","sp":[[163,165,"P","정흠"]]},{"c":1,"sub":"","t":"용녀가 옥황께 진상하였더니 바람에 한 가지가 상하여 꺾어졌습니다. 상제께서 몹시 애석히 여기시어 남악 형산 신령을 불러 주시며, 이 꽃은 인간에 없는 꽃이니 네가 가져다가 인간의 어리석은 사람에게 구경시키라 하시므로, 형산 신령이 부인께 보낸 것입니다. 이번에 상제께서 분부하시기를, 벽역화 한 가지가 남경 정흠의 집에 다시 태어났으니 바삐 가서 보호하라 하시기에 왔습니다.\" 하고는 옥병의 향수를 기울여 아기를 씻겨 누이고 일렀다. \"이 아이 이름은 수정이니 잘 보호하여 기르시고, 배필은 황성에 있으니 부디 때를 놓치지 마소서.\" 하고 나가더니 문득 간 곳을 알 수 없었다. 이때 국공이 밖에 있다가 아이 소리를 듣고 바삐 들어와 보니, 부인은 아들을 낳지 못한 것을 한탄하여 정신을 잃고 누웠고, 곁에는 옥 같은 딸이 누워 있었다.","sp":[[172,174,"P","정흠"],[253,255,"P","정수정"],[327,329,"P","정흠"]]},{"c":1,"sub":"","t":"국공은 약물을 가져다 부인을 구한 뒤 아이를 보니, 옥 같은 골격과 고운 자색이 정말 월궁의 소아(素娥)였다. 국공이 한편 기쁘고 한편 서운하여 부인에게 말하였다. \"우리가 늦게야 처음이자 마지막으로 피붙이를 얻었으니 다행일 뿐, 어찌 아들이 아님을 한하겠소. 옛날 목란 같은 이는 여자라도 남자보다 나았으니, 이로 보면 다 제 타고나기에 달렸지 남녀가 무슨 상관이 있겠소.\" 하며 아이 이름을 수정이라 하고 금지옥엽으로 아끼고 귀하게 길렀다. 흐르는 물 같은 세월이 훌쩍 지나 수정의 나이 어느새 다섯 살이 되니, 꽃 같은 얼굴과 달 같은 자태는 견줄 데 없고 점점 숙성하게 자랐다.","sp":[[0,2,"P","정흠"],[62,64,"P","정흠"],[221,223,"P","정수정"],[268,270,"P","정수정"]]},{"c":1,"sub":"","t":"국공 부부는 기뻐하면서도 그와 같은 짝이 없을까 하여 늘 근심하였다. 하루는 국공이 조회를 마치고 돌아오다가 길에서 이부상서 장공의 이끎을 받아 함께 장공의 집으로 갔다. 인사를 마친 뒤 봄 경치를 구경하려고 경풍각에 올라 시문을 이야기하며 술과 안주를 내어 잔을 나누었다. 술이 반쯤 취하자 국공이 슬픔을 머금고 장공에게 물었다. \"형은 아드님을 몇 형제나 두었소?\" 장공이 말하였다. \"늦게야 자식 하나를 두었을 뿐이오.\" 정공이 물었다. \"지금 몇 살이나 되었소?\" 장공이 말하였다. \"대여섯 살을 넘지 못하였소.\"","sp":[[0,2,"P","정흠"],[43,45,"P","정흠"],[70,72,"P","장훈"],[84,86,"P","장훈"],[164,166,"P","정흠"],[176,178,"P","장훈"],[207,209,"P","장훈"],[239,241,"P","정흠"],[264,266,"P","장훈"]]},{"c":1,"sub":"","t":"정공이 말하였다. \"한번 보기를 청하오.\" 장 상서가 곧 아들을 부르니, 공자가 백화헌에서 글을 읽다가 아버지의 명을 받들어 곧 왔다. 정공이 바라보니 나이는 비록 어리나 골격이 준수하고 총명이 남다른 용모가 참으로 한 시대의 기남자였다. 속으로 탄복하여 다시 장공에게 말하였다. \"소제가 일찍 딸 하나를 두었는데, 나이는 비록 어리나 총명한 재주와 용모가 반드시 영랑의 배필이 될 만하오. 우리 두 사람이 이렇게 친밀한 터에 한번 진진(秦晉)의 의를 맺어 슬하의 재미를 보는 것이 어떻겠소?\" 장공도 마땅하게 여겨 흔쾌히 허락하고, 곧 백옥홀을 내어다가 국공에게 주며 말하였다. \"이것이 대단한 것은 아니나 우리 집에 대대로 내려오며 혼인의 신물로 삼는 물건이오.","sp":[[0,2,"P","정흠"],[24,28,"P","장훈"],[76,78,"P","정흠"],[146,148,"P","장훈"],[277,279,"P","장훈"],[311,313,"P","정흠"]]},{"c":1,"sub":"","t":"이것으로 언약을 청하오.\" 국공은 기쁘게 받은 뒤 또한 쥐고 있던 청파를 주며 말하였다. \"이것도 제 집에 전해 오는 보배이니 이것으로 정을 표하오.\" 그러고는 서로 작별하고 집으로 돌아와, 부인에게 딸의 혼인을 장 상서의 아들과 정한 일을 알리고, 수정을 불러 장 상서가 준 백옥홀을 주며 일렀다. \"이것은 너에게 중대한 신물이니 잘 간수하여라.\"","sp":[[15,17,"P","정흠"],[119,123,"P","장훈"],[140,142,"P","정수정"],[147,151,"P","장훈"]]},{"c":1,"sub":"","t":"이때 예부상서 진량(陳亮)은 사람됨이 간사하고 아첨을 잘하여 임금의 총애를 얻었으므로, 황상이 몹시 아끼셨다. 그래서 진량은 득의양양하여 교만하고 방자해져 어진 이를 해치고 간악한 사람을 끌어들였다. 정국공은 진량이 소인인 줄 알고 나랏일을 그르칠까 늘 근심하여 황상께 간곡히 간하였으나 황상은 끝내 듣지 않으셨다. 진량이 이 일을 알고 정국공을 해치려 하던 차에 마침 황제의 탄신일이 되었다. 조정의 모든 관원이 하나도 빠짐없이 조회에 참례하였는데, 그중 국공만 마침 병이 있어 상소를 올리고 조회에 나오지 못하였다. 황상께서 정국공의 병이 중한 것을 근심하시어 사관을 보내 문병하려 하시자, 진량이 이 틈을 타서 반열에서 나와 아뢰었다. \"정국공은 본디 간악한 위인입니다.","sp":[[3,10,"P","진량"],[49,51,"P","천자"],[66,68,"P","진량"],[112,115,"P","정흠"],[117,119,"P","진량"],[147,149,"P","천자"],[161,163,"P","천자"],[177,179,"P","진량"],[189,192,"P","정흠"],[256,258,"P","정흠"],[291,293,"P","천자"],[296,299,"P","정흠"],[333,335,"P","진량"],[360,363,"P","정흠"]]},{"c":1,"sub":"","t":"그 병은 신이 자세히 압니다. 국공이 요사이 폐하의 정치를 제멋대로 비방하며 어전에 나와 뵙는 것도 전과 다르옵고, 신이 또 국공의 집에 가 보면 국공의 말이 늘 상서롭지 못하였습니다. 오늘 조회에 불참하는 것을 보니 반드시 무슨 곡절이 있는 것이 분명합니다.\" 황상이 그 말을 듣고 크게 놀라 따로 처치하려 하시자, 여러 관원이 아뢰었다. \"정국공의 죄명이 명백하지 않으니 극형으로 다스리기에 이르겠습니까.\" 황상이 의아하여 이르셨다. \"그러면 우선 절강으로 귀양 보내라.\" 사관이 황명을 받들어 국공의 집으로 가서 전하니, 국공은 황명을 받고 황공하기 그지없는 가운데 탄식하여 말하였다. \"내 일찍 나라의 은혜를 만분의 일이라도 갚을까 하였더니, 소인의 참소를 입어 몸이 먼저 먼 곳으로 귀양 가게 되니 어찌 애달프지 않으리오.\" 하며 칼을 빼어 책상을 치며 말하였다. \"내가 소인의 무리를 쓸어 없애지 못하고","sp":[[17,19,"P","정흠"],[70,72,"P","정흠"],[82,84,"P","정흠"],[147,149,"P","천자"],[192,195,"P","정흠"],[230,232,"P","천자"],[279,281,"P","정흠"],[295,297,"P","정흠"]]},{"c":1,"sub":"","t":"도리어 해를 입으니 누구를 원망하리오.\" 하며 흐느껴 울기를 그치지 않으니, 부인과 소저가 애통해하는 것은 물론 일가친척과 노복들까지도 모두 서러워하였다. 이때 사관이 발을 구르며 재촉하였다. \"황명이 급하니 어서 행장을 차리소서.\" 공이 길을 떠나며 부인 양씨에게 일렀다. \"나는 천만뜻밖에 만 리 밖의 귀양객이 되어 가거니와, 부인은 딸아이를 데리고 선영 제사를 받들며 무량히 지내시고, 수정이 나이가 차거든 아무쪼록 장랑과 혼례를 시켜 재미를 보소서.\" 말끝을 다 맺지 못하고 사관의 재촉을 견디지 못하여 곧 떠나니, 양씨 부인이 애절해하는 모습과 수정이 망극해하는 모습은 나무나 돌이라도 서러워할 만하였다.","sp":[[219,221,"P","정수정"],[293,298,"P","양씨 부인"],[310,312,"P","정수정"]]},{"c":1,"sub":"","t":"정공이 여러 날 만에 귀양지에 이르니, 절강 만호가 관사를 깨끗이 치우고 국공을 머물게 하였다. 국공은 몸은 비록 편하게 지냈으나, 봄바람 부는 삼월에 꽃이 필 때나 나뭇잎 지는 추운 가을밤 달을 만날 때마다 집과 나라를 근심하는 회포를 억누르지 못하여 한숨과 긴 탄식으로 세월을 보냈다. 그러다 자연히 병이 들어 여러 달을 앓다가 끝내 일어나지 못하고 세상을 떠났다. 절강 만호가 슬프게 여겨, 모시고 있던 하인을 시켜 시신을 거두어 빈소를 차린 뒤 이 사유를 나라에 장계로 올리고 본가에도 기별하였다.","sp":[[0,2,"P","정흠"],[41,43,"P","정흠"],[54,56,"P","정흠"]]},{"c":1,"sub":"","t":"이에 앞서 부인과 소저는 국공을 만 리 귀양지로 이별하고 밤낮 눈물로 세월을 보냈다. 하루는 시비가 급히 들어와 \"절강에서 사람이 왔습니다.\" 하고 아뢰었다. 부인은 한편으로 반갑기도 하고 한편으로 궁금하여 온 사람을 급히 불러 물으니, 그 사람이 말하였다. \"국공 노야께서 우연히 병환을 얻어 지난달 보름께 세상을 떠나셨습니다.\" 부인과 소저는 그 말을 듣자 외마디 소리에 그만 혼절하여 정신을 잃었다. 시비들이 당황하여 어쩔 줄 모르는데, 한참 만에 한숨을 한 번 내쉬더니 걷잡을 수 없는 눈물이 비 오듯 하였다. 하늘을 부르며 가슴을 치고 발을 구르는 모습에 일가친척과 위아래 노복이 한데 어우러져 곡하는 소리가 천지를 움직였다.","sp":[[14,16,"P","정흠"],[146,148,"P","정흠"]]},{"c":1,"sub":"","t":"이때 황상께서 정국공이 죽었다는 소식을 들으시고 측은히 여기시어 곧 예부에 하교를 내리셨다. \"정국공은 국가에 공이 있는 대신이니 왕후의 예로 장사하라.\" 또 절강 만호에게 공문을 보내 정국공의 영구를 지체 없이 올려 보내라 하셨다. 이때 예부상서 진량이 반열에서 나와 아뢰었다. \"정흠은 폐하의 명을 거역한 신하이니, 만일 그런 소인을 왕후의 예로 장사하면 왕법이 해이해지고 국가에 역신이 끊일 날이 없을까 하옵니다. 폐하께서는 살피시어 하교를 거두소서.\" 황상이 듣고 옳게 여기시어 이르셨다. \"정흠이 비록 죽었으나 아직 죄명을 벗지 못하였으니 그곳에 장사하라.\"","sp":[[3,5,"P","천자"],[8,11,"P","정흠"],[53,56,"P","정흠"],[104,107,"P","정흠"],[134,141,"P","진량"],[158,160,"P","정흠"],[257,259,"P","천자"],[279,281,"P","정흠"]]},{"c":1,"sub":"","t":"이때 양씨 부인은 소저를 데리고 밤낮 애통해하며, 국공의 시체를 하루바삐 운구(運柩)하여 선산에 안장하는 것만을 바라 황상께서 명을 내려 주시기를 밤낮 울며 빌었다. 그런데 천만뜻밖에 진량의 참소가 끝내 황상의 총명을 가렸다는 말을 들으니, 망극한 가운데 통분한 마음에 그놈의 간을 끄집어내어 조각조각 씹고 싶었다. 그러나 아녀자의 몸으로 외손뼉이 소리 나지 않는 격(孤掌難鳴)이라, 하늘에 사무치는 원한만 뼛속에 맺힐 뿐 다른 도리가 없었다.","sp":[[3,8,"P","양씨 부인"],[28,30,"P","정흠"],[66,68,"P","천자"],[103,105,"P","진량"],[114,116,"P","천자"]]},{"c":1,"sub":"","t":"다만 열 살 딸아이와 더불어 밤낮 하늘을 부르며 망극해하기만 하다가, 무슨 생각을 하였는지 울음을 그치고 수정의 손을 잡고 일렀다. \"너의 부친께서 만 리 귀양지에서 세상을 떠나신 것도 진량의 탓이요, 돌아가신 뒤 백골조차 돌아오지 못하는 것도 다 진량의 참소가 상총(上聰)을 가린 탓이다. 이런 하늘 아래 함께 살 수 없는 원수를 어찌하면 갚아 보겠느냐. 그렇더라도 네가 사내로 태어났더라면 자라서 아무쪼록 부모의 원수를 갚아 보련만, 여자로 태어났으니 그도 할 수 없다. 자식이라고는 무밑동 같은 딸자식 너뿐이니, 이다음 원수 갚는 일은 둘째요, 당장 만 리 밖에 가서 백골을 거둘 사람이 없으니 세상에 이보다 원통한 일이 어디 있단 말이냐. 절강이 비록 멀어도 뱃길이 있으니 내가 마땅히 가서 너의 부친 백골이나 위로하여 안장하고 오겠다. 너는 비록 어리나 비복을 데리고 집을 지키며 내가 돌아오기를 기다려라.\" 수정이 그 말을 듣고 발을 구르며 소리 높여 크게 울었다. \"어머니께서 만 리 먼 곳을 어찌 혼자 다녀오시며, 소녀는 집에 편히 있어 부친의 백골을 뵙지 못하면 자식 된 몸으로 평생의 한이 되지 않겠습니까. [?]","sp":[[59,61,"P","정수정"],[104,106,"P","진량"],[139,141,"P","진량"],[458,460,"P","정수정"]]},{"c":1,"sub":"","t":"바라건대 어머니께서는 소녀의 지극한 원통함을 살피시어 어머니와 함께 가게 해 주소서.\" 양씨 부인은 철모르는 딸의 말이라도 효성이 지극하고 사리에 옳으므로 억지로 말리지 못하였다. 비복들에게 집을 지키게 하고 딸과 유모를 데리고 길을 떠나 여러 날 만에 개봉부에 이르렀다. 거기서는 물길로 가는 것이 편리할 뿐 아니라 길도 얼마쯤 가까우므로, 절강으로 가는 장삿배 한 척을 잡아타고 갔다. 순풍에 돛을 달고 강 한가운데 높이 떠서 동정호 칠백 리를 화살같이 나아가니, 악양루와 등왕각에는 옛사람이 놀던 자취가 분명하고 무산 열두 봉우리는 눈앞에 늘어서 있는데, 창오산에 저문 안개는 굽이굽이 돌아든다. 이윽고 해는 서산에 지고 달이 동쪽 고개에 떠오르니, 휘영청 밝은 달빛이 물빛과 어울려 금모래를 뿌린 듯하였다. 이 같은 경치는 시인 묵객의 흥취를 돋울 만하나, 근심 있는 사람은 슬픈 회포를 금치 못하였다.","sp":[[49,54,"P","양씨 부인"],[120,122,"P","유모"]]},{"c":1,"sub":"","t":"이처럼 넓은 물길을 가고 있노라니 별안간 포 소리가 한 번 울리며 태산이 뒤흔들리고 강물이 끓어오르는 듯하더니, 난데없는 수적(水賊) 무리가 달려들어 배에 실은 물건을 모조리 빼앗았다. 이때 배 안에 있던 양씨 부인 모녀의 혼백이 어찌 온전하겠는가. 정신을 잃고 있을 즈음, 수적 한 놈이 양씨 부인의 아리따운 자색을 달빛에 보더니 저 혼자 차지하겠다며 끌고 갔다. 이때 수정은 유모 곁에 기대어 떨며 앉아 있다가 도적이 어머니를 잡아가는 것을 보고 소리를 질러 통곡하며 달려들어 어머니의 옷자락을 붙잡으려 하였으나, 도적이 수정을 발길로 차 던졌다. [?]","sp":[[115,120,"P","양씨 부인"],[162,167,"P","양씨 부인"],[208,210,"P","정수정"],[212,214,"P","유모"],[294,296,"P","정수정"]]},{"c":1,"sub":"","t":"사내도 아닌 열 살 계집아이가 그런 일을 당하니 어찌 정신을 차리겠는가. 그놈의 발길에 채어 넘어지는 바람에 함께 앉아 있던 유모와 한데 엎어져 선창 밑으로 쓸려 들어갔다. 도적놈들은 재물과 양씨 부인을 빼앗아 저희 배에 싣고 화살같이 갔다. 이때 양씨 부인은 그런 일을 당하니 정신이 없는 중이라도 어찌 살 마음이 있겠는가. 물에라도 당장 빠져 죽고 싶었으나 그놈들이 좌우에서 붙잡고 앉아 있어 몸을 마음대로 움직이지 못하니 어찌 죽을 수나 있겠는가. 이렇게 밤을 새워 가다가 날이 밝자 그놈들은 배를 어느 곳에 대고 빼앗아 온 재물을 각기 나누었다. 그런데 그중 한 사람은 주는 재물도 갖기 싫다며 시름없이 한쪽 구석에 가 있었다. 도적들이 말하였다. \"이제는 우리와 동무가 되었으니 몫으로 가는 재물을 왜 싫다 하시오. 댁이 아무리 싫어도 지금 와서는 우리 말을 들어야지, 만일 듣지 않으면 우리 손에 목숨을 보전하지 못할 것이오. 또 댁을 보아하니 우리 무리 가운데 나이가 제일 많으니 우리의 우두머리(영좌)로 삼겠소.\"","sp":[[70,72,"P","유모"],[107,112,"P","양씨 부인"],[139,144,"P","양씨 부인"],[509,511,"P","이춘보"]]},{"c":1,"sub":"","t":"그러고는 끌어다 윗자리에 앉히고, 여러 놈이 \"영좌님, 영좌님\" 하며 술과 안주를 갖추어 바치니, 두목으로 대접하는 것이 분명하였다. 이때 영좌님이라 불린 사람은 그놈들의 위협을 이기지 못하여 감히 싫다는 말도 못 하고 있었으나, 어떻게든 몸만 빠져나갈 생각이었으니 어찌 그놈들의 술을 한 잔인들 마시고 싶었겠는가. 대저 이 사람이 누구인가 하면, 정 상서 집에서 신임하는 늙은 하인이었는데 이름은 이춘보였다. 사람됨이 본디 충직하므로 상서가 절강으로 갈 때 데리고 갔는데, 불행히 상서의 병환이 위중해졌다.","sp":[[26,28,"P","이춘보"],[31,33,"P","이춘보"],[78,80,"P","이춘보"],[195,199,"P","정흠"],[223,226,"P","이춘보"]]},{"c":1,"sub":"","t":"춘보는 밤낮으로 정성을 다하여 약시중을 들었으나 끝내 구하지 못하고 상서가 세상을 떠났다. 춘보는 홀로 애통망극하여 상서의 시신을 거두어 정한 곳에 빈소를 차리고, 서울 본댁으로 급히 올라오던 길이었다. 배를 타고 빨리 온다는 것이 그만 모르고 수적의 배에 올라 여러 도적놈에게 이런 곤경을 당하고 있던 터였다. 그야말로 절에 간 색시 꼴이 되어 말 한마디 못 하고 그놈들 하는 짓만 보고 있었다. 이윽고 도적놈 가운데 생김새가 흉악하고 사나운 놈 하나가, 선창 안에 정신을 잃고 누운 부인을 끌어내다 놓고 영좌 이춘보에게 말하였다. \"소적이 중년에 아내를 잃고 아직 장가를 들지 못하였는데, 오늘 이 계집을 보니 나이가 알맞습니다.","sp":[[0,2,"P","이춘보"],[51,53,"P","이춘보"],[284,286,"P","이춘보"],[287,290,"P","이춘보"]]},{"c":1,"sub":"","t":"소적이 아내로 삼고자 하니 영좌님이나 여러 동관은 그리 아시오.\" 하고는 다짜고짜 부인을 끌고 강가 어느 집으로 갔다. 이때 이춘보는 그놈들이 시키는 대로 영좌님인 척하고 윗자리에 앉아 있다가, 그놈이 끌고 가는 부인을 보니 틀림없는 자기 댁 국공 부인이었다. 깜짝 놀라고 반가운 마음에 그만 소리를 지르고 내달아 문안을 드리며, \"어찌된 연고로 이곳에 오셨다가 저놈들에게 이런 욕을 보십니까.\" 하고 싶었다. 한편으로 분하고 급한 마음에 그놈들의 목을 한 칼에 모조리 베고 싶었으나, 세상 풍파를 많이 겪은 춘보라 얼른 생각해 보니, 만일 부인을 아는 체하거나 그놈들을 섣불리 건드렸다가는 필경 내 목숨부터 보전하지 못할 것이요, 내가 먼저 죽고 나면 함정에 빠지신 상전을 누가 구해 내겠는가 싶어 천지가 아득하고 정신이 없었다.","sp":[[15,17,"P","이춘보"],[70,73,"P","이춘보"],[87,89,"P","이춘보"],[136,141,"P","양씨 부인"],[285,287,"P","이춘보"]]},{"c":1,"sub":"","t":"한참 앉아 있다가 생각하기를, 큰 도적을 잡으려면 나도 같이 도적이 되어 잡는 법이라 하고, 이에 여러 도적놈을 하나도 빠짐없이 다 불러 놓고 설명하였다. \"나는 본디 남경 사람으로 볼일이 있어 이곳에 왔다가 돌아가는 길이었다. 운수가 크게 트이려고 그랬는지 목숨을 보전하지 못하려고 그랬는지, 불행히 너희 배를 탔다가 이 지경이 되니 내 몸은 그야말로 진퇴양난이다. 여러 동관이 나를 영좌로 추천하니 내가 그 책임을 감당하지는 못하겠으나, 왕후장상이 어찌 씨가 따로 있겠느냐.","sp":[[216,218,"P","이춘보"]]},{"c":1,"sub":"","t":"그러나 도적이라는 이름은 띠었을망정, 그럴수록 장졸(將卒) 사이에 체통과 법령을 세워서, 장수는 아랫사람을 아끼고 아랫사람은 장수의 영을 어기지 말아야 큰일을 할 것이다. 그렇지 못하면 여러 사람의 마음이 제각각이 되어 한마음이 될 수 없을 것이니, 그리되면 우리가 몸 둘 곳이 없어 다 잡혀 죽을 것이다. 여러 동관은 내 말을 따르겠느냐. 만일 그렇지 못하면 나는 차라리 이 자리에서 그대들 손에 죽을지언정 그대들 무리에는 들지 않겠다.\" 그러자 여러 놈이 일시에 일어나 대답하며 영좌님의 영을 따르겠다 하였다. 그제야 이춘보가 여러 놈의 거주와 성명을 낱낱이 기록하고 보니, 그중 젊은 놈 하나가 키는 구 척 장승 같고 힘이 남보다 뛰어나 보였는데, 성명은 절강에 사는 나호철이었다.","sp":[[270,272,"P","이춘보"],[292,295,"P","이춘보"],[377,380,"P","나호철"]]},{"c":1,"sub":"","t":"비록 화적 무리에 들었을망정 호협한 말씨에 의리가 있어 보였다. 춘보가 호철을 조용히 불러 말하였다. \"그대가 절강에 산다 하니, 남경에서 귀양 간 정 상서를 혹 들어 아는가?\" 호철이 반가이 대답하였다. \"듣기만 했겠습니까. 소적은 본디 절강 부중에 살았는데, 몇 해 전 귀양 오신 정 상서께서 묵으시던 집이 바로 소적의 집 이웃입니다.\" 춘보가 물었다. \"그러면 그대가 그 양반을 뵌 적이 있는가?\" 호철이 말하였다. \"뵙지는 못하였어도 그 양반의 덕택으로 목숨이 오늘까지 살아 있습니다.\"","sp":[[36,38,"P","이춘보"],[40,42,"P","나호철"],[83,87,"P","정흠"],[100,102,"P","나호철"],[159,163,"P","정흠"],[191,193,"P","이춘보"],[226,228,"P","나호철"]]},{"c":1,"sub":"","t":"춘보가 물었다. \"무슨 일로 정 상공의 은혜를 그처럼 입었는가?\" 호철이 말하였다. \"소적이 스무 살 전에 방탕하게 다니다가 불행히 살인죄에 걸려 살기를 바랄 길이 없었습니다. 소적의 어머니가 아침저녁으로 정 상공께 가서 애걸하여 편지 한 장을 얻어 절강 만호에게 보냈더니, 다행히 사형은 면하고 옥에 갇혀 있다가 어느 날 밤 옥을 넘어 도망쳐 나왔습니다. 갈 곳이 없어 부득이 저 무리에 들었습니다.\" 춘보가 놀라 물었다. \"그러면 그대는 정 상서의 은혜를 갚을 마음이 없는가?\" 호철이 성을 내며 말하였다. \"사람이 세상에 나서 남의 은공을 모르면 짐승만도 못합니다.","sp":[[0,2,"P","이춘보"],[37,39,"P","나호철"],[226,228,"P","이춘보"],[247,251,"P","정흠"],[270,272,"P","나호철"]]},{"c":1,"sub":"","t":"소적은 정 상공께서 목숨을 살려 주신 은혜를 어찌하면 만분의 일이라도 갚을까 하여 밤낮 근심하는 터입니다.\" 춘보가 그 말을 듣더니 호철의 귀에 대고 가만가만 일렀다. \"지금 저놈들에게 잡혀 와 욕을 보시는 부인이 정 상서 부인이신데, 필경 배로 상공의 귀양지에 가시다가 저런 환란을 당하신 듯하니, 우리가 몰랐으면 모르되 알고서야 어찌 구하지 않겠는가.\" 호철이 물었다. \"당신은 누구시기에 그분이 그 부인이신 줄 아십니까?\" 춘보가 말하였다. \"나는 그 댁 하인으로, 상공께서 귀양 가실 때 모시고 가 있었는데 불행히 상공께서 병환으로 세상을 떠나셨네.","sp":[[61,63,"P","이춘보"],[74,76,"P","나호철"],[120,124,"P","정흠"],[200,202,"P","나호철"],[240,242,"P","이춘보"]]},{"c":1,"sub":"","t":"내가 홀로 장례 일을 치러 우선 빈소에 모시고 본댁으로 들어가던 길에, 모르고 저놈들 배를 탔다가 이 꼴을 당하였네. 상공 부인께서는 필경 상공의 부음을 들으시고 급히 배로 가시다가 저런 환란을 당하신 모양이니 어찌 망극하지 않겠는가. 부인께서는 정신을 잃으셔서 나를 미처 못 보셨으나 나야 어찌 몰라뵙겠는가. 그러나 내가 그 자리에서 아는 체를 했다가는 내 목숨부터 죽음을 면하지 못할 것이니, 내가 죽고 나면 부인을 누가 구해 내겠는가.","sp":[]},{"c":1,"sub":"","t":"그래서 우선 분함을 참고 있으나 어찌하면 좋을지 계책이 막막하였는데, 하늘이 도와 그대를 만났으니 오늘은 그대가 정 상공의 은혜를 갚는 날일세. 그대 생각은 어떠한가?\" 하며 목이 메어 눈물을 뚝뚝 떨어뜨렸다. 호철이 그 말을 듣더니 그만 분한 마음이 가슴에 가득 차 곧 칼을 빼어 들고 가서 그놈들을 모조리 죽이려 하였다. 춘보가 급히 호철의 손을 잡고 말하였다. \"그대가 잠시 혈기의 분으로 그놈들을 처치하려 하나, 그놈들은 여럿이요 우리는 홀몸이라.","sp":[[118,120,"P","나호철"],[182,184,"P","이춘보"],[189,191,"P","나호철"]]},{"c":1,"sub":"","t":"만일 일이 뜻대로 되지 않으면 도리어 우리 두 목숨만 상할 것이네. 우리 죽는 것은 원통하지 않으나 함정 속에 계신 부인께서 어찌 욕을 면하고 벗어나시겠는가. 내가 한 계책을 생각하였으니 그대는 해낼 수 있겠는가?\" 하더니 호철의 귀에 대고 이러이러하는 것이 만전의 계책이라 하였다. 호철이 한참 듣다가 고개를 연이어 끄덕끄덕하고 물러갔다. 원래 양씨 부인을 아내 삼겠다고 끌고 간 놈은 이름이 황돌쇠라는 놈이었다. 본디 사람됨이 우악하고 불량하여 한평생 도적질로 생애를 삼는 놈이었다. 그러다 보니 자연히 끼리끼리 어울려 여러 놈이 모여 다니며, 혹은 마을에 들어가 남의 집에 뛰어들어 부녀를 겁탈하고, 혹은 강과 호수를 다니며 장사꾼의 재물을 노략하는 무리였다. 이날도 강호를 다니다가 큰 장사꾼의 배를 만나 재물을 모조리 빼앗고, 그 배를 타고 오던 정국공 부인까지 잡아다 놓고 득의양양하여, 어서 밤이 오면 그 부인과 동침할 속셈으로 강가에 집 하나를 치우고 부인을 끌고 가서 온갖 수로 위협하던 판이었다.","sp":[[125,127,"P","나호철"],[159,161,"P","나호철"],[194,199,"P","양씨 부인"],[221,224,"P","황돌쇠"],[424,429,"P","양씨 부인"]]},{"c":1,"sub":"","t":"그때 호철이 와서 황돌쇠를 청하며 말하였다. \"영좌께서 여러 동무를 다 청하십니다.\" 황가가 물었다. \"무슨 일로 청하시더냐?\" 호철이 말하였다. \"영좌께서 오늘 여러 사람의 두목이 되셨는데 그저 있기가 섭섭하다고 술과 안주를 준비해 놓고, 여러 동무와 한번 정을 나누자고 청하시니 어서들 갑시다.\" 이놈들은 본디 귀신 것들처럼 먹을 것이라면 물불이라도 뛰어드는 놈들이라, 술과 안주를 놓고 부른다는 말을 듣더니 행여 빠질세라 일제히 배 안으로 갔다. 황돌쇠란 놈은 양씨 부인을 주막 주인에게 단단히 맡기고 갔다.","sp":[[3,5,"P","나호철"],[10,13,"P","황돌쇠"],[26,28,"P","이춘보"],[48,50,"P","황돌쇠"],[72,74,"P","나호철"],[83,85,"P","이춘보"],[253,256,"P","황돌쇠"],[261,266,"P","양씨 부인"]]},{"c":1,"sub":"","t":"여러 놈이 하나도 빠짐없이 다 모여 술을 마시는데, 저희끼리 권커니 잣거니 양껏 어찌나 퍼마셨던지 얼마 되지 않아 여러 놈이 저마다 크게 취하여 정신을 잃고 늘어졌다. 이때 춘보와 호철이 나서서 그 여러 놈을 차례로 묶어 물속에 조약돌 던지듯 풍덩풍덩 집어넣고, 배에서 내려 곧바로 강가 술막집으로 들어갔다. 양씨 부인은 정신을 잃고 인사불성이었다. 환약을 개어 흘려 넣고 주막 계집을 시켜 팔다리를 주무르게 하였더니, 얼마 만에 정신을 차렸다.","sp":[[97,99,"P","이춘보"],[101,103,"P","나호철"],[173,178,"P","양씨 부인"]]},{"c":1,"sub":"","t":"그제야 이춘보가 앞으로 나가 문안을 드리며 말하였다. \"마님께서는 소인을 몰라보십니까? 이춘보가 여기 왔습니다.\" 이때 양씨 부인은 그놈들에게 끌려와 정신을 잃고 누웠다가 이춘보란 말에 벌떡 일어나 보니, 과연 틀림없는 자기 집 하인 이춘보였다. 사람이 너무 반가운 일을 만나면 눈물부터 앞서는 법이다. 양씨 부인은 천만뜻밖에 이춘보를 보더니 말 한마디 못 하고 대줄기 같은 눈물만 줄줄 흘리며 목이 메어 소리를 이루지 못하였다. 이는 오늘 죽을 고비에 들었다가 자기 집 하인을 만나니 반갑기도 하려니와, 더구나 남편이 살아서 데리고 간 하인인데 남편은 만 리 먼 곳에서 죽어 원혼이 되고 하인만 혼자 돌아온 것을 보니, 나무나 돌이 아닌 다음에야 그 마음이 어찌 온전하여 말이 순순히 나오겠는가. 예로부터 도적에게 욕을 당해 고생한 이도 많고 남편이 귀양 가서 죽은 이도 많지만, 양씨 부인같이 여러 가지로 속이 녹는 듯한 일이 어디","sp":[[4,7,"P","이춘보"],[49,52,"P","이춘보"],[67,72,"P","양씨 부인"],[96,99,"P","이춘보"],[131,134,"P","이춘보"],[170,175,"P","양씨 부인"],[183,186,"P","이춘보"],[438,443,"P","양씨 부인"]]},{"c":1,"sub":"","t":"또 있겠는가. 첫째는 남편이 만 리 밖에서 병이 들어 돌아갔는데도 제 손으로 약 한 번 달여 드리지 못하였고, 끝내 세상을 떠난 뒤에도 백골조차 마음대로 고향에 돌아오지(還鄕) 못하는 일이요, 둘째는 딸자식일망정 무남독녀로 금지옥엽같이 기르다가 물속의 외로운 넋을 만든 일이요, 셋째는 자기 혼자 몸이 온갖 풍상을 겪다 못해 도적의 손에 끌려다니다가, 모진 목숨이 진작 죽지 못하고 살아나서 이 신세를 어찌할까 하는 마음이었다.","sp":[]},{"c":1,"sub":"","t":"그 여러 가지 남에게 없는 일을 혼자 당하고 앉았으니 무슨 말이 입 밖으로 나오겠는가. 이날 이춘보를 대하니 너무 반가운 마음에 반가운지 어떤지도 모르고 하도 기가 막혀 멍하니 바라보고 앉아 눈물만 흘리다가, 겨우 정신을 차려 물었다. \"내가 도적에게 끌려 이곳에 온 줄은 알았는데, 그 도적은 다 어디로 가고 네가 여기 와 있으니 어찌 된 일이냐?\" 춘보가 여쭈었다. \"여러 도적놈은 소인이 다 처치하였으니 마음을 놓으소서.\" 부인이 그 말을 들으니 마음이 좀 놓였다.","sp":[[52,55,"P","이춘보"],[197,199,"P","이춘보"]]},{"c":1,"sub":"","t":"정신을 다시 차려, 자기가 딸을 데리고 절강으로 가다가 배에서 도적을 만나 딸과 유모는 물에 빠져 죽고 자기는 그놈들에게 잡혀 고생한 이야기를 한바탕 한 뒤 다시 물었다. \"춘보야, 너는 상공의 시신을 어떻게 수습하였으며, 무슨 일로 이곳에 왔다가 나를 구하였느냐?\" 춘보가 여쭈었다. \"상공께서 돌아가신 뒤 시신은 정한 곳에 빈소를 차려 모시고, 소인이 댁으로 올라가서 마님께 여쭈어 속히 운구를 모셔 오시게 하려고 급히 오던 길에 모르고 수적의 배를 탔습니다.\" 하고 고생한 이야기를 하였다. \"배 안에서 마님을 뵈니 놀랍고 반가운 마음에 곧 문안을 드리고 싶었으나, 그러지 못할 사정이 많아 못 뵌 척하고 있었습니다. 그러다가 도적 가운데도 의적이 있다더니 그중에도 의리 있는 사람을 만나, 그 사람과 함께 여러 도적을 다 죽이고 마님을 구하였습니다.\" 하며 호철을 가까이 불러 문안을 드리게 하고 말하였다. \"이 사람은 본디","sp":[[45,47,"P","유모"],[97,99,"P","이춘보"],[150,152,"P","이춘보"],[428,430,"P","나호철"]]},{"c":1,"sub":"","t":"절강에 사는 호철이라 하는 사람인데, 지난날 무슨 죄에 걸려 죽게 된 목숨을 상공의 덕택으로 살아난 은혜가 있었습니다. 이번에 마님께서 큰 욕을 면하신 것은 다 저 사람의 힘입니다.\" 부인도 호철을 친히 보고 무수히 칭찬하며 사례하였다.","sp":[[7,9,"P","나호철"],[107,109,"P","나호철"]]},{"c":1,"sub":"","t":"양씨 부인은 자기 몸은 환란을 면하였으나 수정과 유모가 물속의 외로운 넋이 된 일이 더욱 불쌍하여 차마 발길이 돌아서지 않는 것을 억지로 참고, 이춘보를 데리고 다시 절강으로 향하였다. 나호철은 절강 땅에 갈 수 없는 형편이 있어 함께 가지 못하였다. 부인은 춘보만 데리고 절강으로 가서 남편의 무덤 옆에 집을 짓고 지내며 나라에서 사면의 명이 내리기만 기다렸다.","sp":[[0,5,"P","양씨 부인"],[23,25,"P","정수정"],[27,29,"P","유모"],[81,84,"P","이춘보"],[104,107,"P","나호철"],[145,147,"P","이춘보"]]},{"c":1,"sub":"","t":"한편 장 상서는 정국공이 귀양지에서 죽었다는 부음을 듣고 놀라며 비창한 마음을 억누르지 못하여, 사람을 국공의 집으로 보내 소저의 애통함을 위로하려 하였다. 갔던 사람이 돌아와 아뢰기를, 국공 부인이 국공의 부음을 듣고 소저와 함께 절강으로 갔다 하니, 장 상서가 듣고 탄식하기를 마지않았다. 슬프다, 오래지 않아 장 상서 또한 우연히 병을 얻어 세상을 떠나니, 왕부인과 장연이 애통해하며 예를 갖추어 선산에 안장하였다. 그 뒤 왕부인은 때때로 장연을 다독여 학문에 힘쓰게 하였다.","sp":[[3,7,"P","장훈"],[9,12,"P","정흠"],[58,60,"P","정흠"],[105,110,"P","양씨 부인"],[112,114,"P","정흠"],[142,146,"P","장훈"],[176,180,"P","장훈"],[203,206,"P","왕부인"],[208,210,"P","장연"],[240,243,"P","왕부인"],[249,251,"P","장연"]]},{"c":1,"sub":"","t":"이때 수정 소저는 어머니를 따라 절강으로 가다가, 도중에 난데없는 도적 떼가 달려들어 어머니를 잡아가는 것을 보고 크게 놀라 통곡하며 달려들어 어머니의 옷을 붙잡으려 하였다. 그러다 도적의 발길에 채여 선창 밑에 엎어졌는데, 얼마 만에야 정신을 차려 보니 어머니와 도적은 다 간데없고 뱃사람들만 남아 있었다. 소저가 하늘을 부르짖어 울며 어머니가 간 곳을 물으니, 뱃사람들도 그 모습을 불쌍히 여겼으나 어찌 부인이 간 곳을 알겠는가. 하는 수 없이 소저와 유모를 물가에 내려놓으며 말하였다. \"우리도 물건을 다 잃어 어쩔 수 없이 배를 돌려 돌아가야겠습니다.","sp":[[3,5,"P","정수정"],[255,257,"P","유모"]]},{"c":1,"sub":"","t":"소저는 유모와 함께 이곳에서 아무쪼록 부인의 행방을 찾아보소서.\" 하고 배를 띄워 오던 길로 돌아갔다. 소저는 뭍에 내려 갈 곳을 몰라 방황하다가 유모를 데리고 정처 없이 걸었다. 한 곳에 이르러서는 굶주림과 목마름이 심하여 한 걸음도 나아가지 못하고 잔디밭에 앉아 유모와 서로 붙잡고 흐느껴 울었다. 마침 여승 하나가 머리에 송낙을 쓰고 몸에는 검은 장삼을 입고 손에는 육환장을 짚고 오더니, 소저를 보고 합장하여 절하며 말하였다. \"소승은 군산 칠보암에 있는 중으로 법명은 정현입니다. 어젯밤 관음보살께서 꿈에 나타나 이르시기를, 용궁의 벽역화 한 가지가 인간에 다시 태어났다가 동호정 물가에서 환란을 당하여 갈 곳을 모르니 내일 오시(午時)에 급히 가서 길을 인도하라 하시기에 왔습니다. 소저는 의심하지 마시고 소승의 절로 가십시다.\" 하며 정성껏 길을 인도하여 데리고 절로 와서, 깨끗한 방을 치우고 지내게 하였다.","sp":[[4,6,"P","유모"],[82,84,"P","유모"],[149,151,"P","유모"],[172,174,"P","정현"],[267,269,"P","정현"]]},{"c":1,"sub":"","t":"이때 수정 소저는 길에서 갈 곳을 모르고 방황하다가 천만뜻밖에 그 여승의 구함을 입어 그 절에 와서 몸은 편히 지냈다. 그러나 오직 부모 생각에 밤낮 애절해하며 생각하였다. '어찌하면 부모의 원수를 갚아 볼까. 아버지께서 만 리 귀양지에서 세상을 떠나신 것도 진량의 죄요, 어머니께서 아버지 귀양지로 가시다가 도적에게 잡혀가셨으니 필경 살아 계시지는 못하였을 것이니 그것도 다 진량의 탓이다. 이런 하늘 아래 함께 살 수 없는 원수를 어찌하면 갚아 볼까. 다른 자손이 있다면 이다음에라도 갚아 본다 할 수 있겠지만, 우리 부모의 혈육이라고는 쓸모없는 내 몸 하나뿐이니, 아무리 원통한 마음이 있은들 여자의 몸이라","sp":[[3,5,"P","정수정"],[37,39,"P","정현"],[145,147,"P","진량"],[211,213,"P","진량"]]},{"c":1,"sub":"","t":"어찌하겠는가. 더구나 나이가 차면 출가외인이 되어 친정과 남이 될 것이니, 슬프다, 우리 부모의 원수는 누가 갚아 주며 선영의 제사는 속절없이 끊어질 것이니 어찌 원통하지 않은가.' 이런 생각 저런 생각에 곧 칼이라도 물고 엎어지고 싶었으나 그도 시원하게 하지 못하는 것이, 딸일망정 나까지 죽고 나면 우리 부모의 백골은 속절없이 까막까치의 밥이 될 것이었다. 그런 생각에는 죽기도 어렵고 살기도 어려웠다. 이처럼 밤낮으로 애를 태우다가, 옛날 목란 같은 이는 여자로 태어났건만 부모를 위하여 전장에 나갔으니 이로 보면 자식 되어 부모 위하는 데는 남녀가 따로 없다는 것을 생각하였다. 그 길로 유모를 불러 마음속 생각을 의논한 뒤 그날부터 남복을 지어 입고 밤낮을 가리지 않고 공부하며 틈틈이 병서도 두루 읽었다.","sp":[[333,335,"P","유모"]]},{"c":1,"sub":"","t":"원래 수정은 하늘이 내신 사람이라 하나를 보면 열 가지를 깨치는 재주로 밤낮을 가리지 않고 어찌나 독실하게 공부하였던지, 불과 몇 해 만에 문장은 이백과 두보(李杜)를 압도하고 병법은 손무와 오기(孫吳)에 견줄 만하였다. 이후로는 또 말 달리기와 창 쓰기를 익히니, 견줄 데 없는 용맹과 지략이 세상에 짝이 없을 듯하였다.","sp":[[3,5,"P","정수정"]]},{"c":1,"sub":"","t":"한편 장연은 삼년상을 마치고 어머니의 가르침을 받아 밤낮으로 과거 공부에 힘썼다. 이때 나라에서 인재를 뽑으려고 예부에 명하여 날을 가려 과거를 열게 하였다. 과거 날이 되자 장연이 과장에 들어가 글제를 살펴보니 '강구에서 동요를 듣다(康衢聞童謠)'라 뚜렷이 걸려 있었다. 한 번 본 뒤 시지를 펼쳐 놓고 단숨에 써서 맨 먼저 바치고 나와 방이 나기를 기다렸다. 이때 황상이 글장 하나를 뽑아 앞에 놓고 보시니, 글씨는 용과 뱀이 날아오르는 듯하고 글은 글자마다 구슬을 꿴 듯하였다. 봉한 이름을 떼어 보니 '전 이부상서 장훈의 아들 연, 나이 십칠 세'","sp":[[3,5,"P","장연"],[98,100,"P","장연"],[206,208,"P","천자"],[292,294,"P","장훈"]]},{"c":1,"sub":"","t":"라고 적혀 있었다. 전두관이 나와 이름을 부르니, 장연이 의관을 바르게 하고 옥계 앞에 나아가 엎드려 절하였다. 황상이 불러 보시고 크게 기뻐하며 이르셨다. \"네 아비가 충성을 다하여 짐을 섬기더니 일찍 세상을 떠나 짐이 늘 생각하였는데, 네가 이제 방목에 오르니 네 아비를 보는 듯하구나. 국가에 이만한 다행이 없도다.\" 그러고는 한림학사를 제수하시니, 한림이 은혜에 사례하고 집으로 돌아와 삼일유가를 마친 뒤 선영에 성묘하고, 직무를 극진히 하여 임금을 섬겼다.","sp":[[28,30,"P","장연"],[63,65,"P","천자"]]},{"c":1,"sub":"","t":"이때 왕부인이 아들의 혼사를 치르고자 정국공 집을 알아보니, 국공이 귀양지에서 죽은 뒤 국공 부인이 소저를 데리고 국공의 귀양지로 가다가 도중에 도적 떼를 만나 생사존망을 모른 지가 지금까지 삼 년이라 하였다. 왕부인이 이 소식을 듣고 크게 놀라 아들의 혼사가 늦어지는 것을 크게 근심하였다.","sp":[[3,6,"P","왕부인"],[21,24,"P","정흠"],[34,36,"P","정흠"],[49,54,"P","양씨 부인"],[64,66,"P","정흠"],[118,121,"P","왕부인"]]},{"c":1,"sub":"","t":"장 한림이 벼슬에 나간 지 어느덧 몇 해가 되니, 나라는 태평하고 백성은 편안하며 때마다 화평하고 해마다 풍년이 들어 사방에 아무 일이 없었다. 한림이 표를 올려 별시를 청하자 황상이 윤허하시어 날을 가려 과거를 열라 하셨다. 이때 수정 소저는 군산 칠보암에 있으며 학업에 힘쓰고 있었다. 하루는 정현이 소저에게 아뢰었다. \"소저의 액운이 거의 다하였고, 또 소저의 뜻을 소승이 짐작합니다. 듣자니 나라에서 과거를 열어 인재를 뽑는다 하니, 때를 놓치지 마시고 한번 나가 집안과 나라에 이름을 빛내신 뒤 좋은 인연(佳緣)을 이루시고 부귀를 누리소서.\" 소저도 속으로 정한 마음이 있었던 데다 정현의 권유를 듣고, 곧 정현과 아쉬운 작별을 하고 유모와 함께 남복을 하고 떠나 여러 날 만에 황성에 이르니 과거 날이 닥쳐 있었다.","sp":[[0,4,"P","장연"],[99,101,"P","천자"],[130,132,"P","정수정"],[166,168,"P","정현"],[331,333,"P","정현"],[345,347,"P","정현"],[360,362,"P","유모"]]},{"c":1,"sub":"","t":"곧 과거 도구를 갖추어 과장에 들어가 글제를 살펴본 뒤 시지를 펼쳐 놓고 단숨에 써서 맨 먼저 바치고 나와 쉬었다. 이때 황상이 그 글장을 뽑으시니 문필이 탁월함을 크게 칭찬하시고, 봉한 이름을 떼어 보니 정국공의 아들 정수정이었다. 곧 새로 급제한 사람을 불러 나아가고 물러나게 하신 뒤 하교하셨다. \"정흠이 아들이 없다 하더니 이 같은 기남자를 둔 것을 몰랐도다.\" 하시고 한편으로 의아해하셨다. 이때 진량이 곁에 모시고 있다가 아뢰었다. \"정흠이 본디 아들이 없음을 신이 잘 아는데, 이제 정수정이 나라를 속이고 정흠의 아들이라","sp":[[68,70,"P","천자"],[115,118,"P","정흠"],[123,126,"P","정수정"],[170,172,"P","정흠"],[227,229,"P","진량"],[249,251,"P","정흠"],[277,280,"P","정수정"],[290,292,"P","정흠"]]},{"c":1,"sub":"","t":"하니 폐하께서는 살피소서.\" 이때 수정은 부친을 해치던 진량인 줄 알고 분노를 이기지 못하여 말하였다. \"네가 황상을 속이고 대신을 모해하던 진량이 아니냐. 네가 무슨 혐의로 우리 부친을 해쳐 만 리 먼 땅의 외로운 넋이 되게 하고, 이제 나를 또 해치려고 거짓 아들이라 말하느냐. 천륜이 얼마나 중한데 인륜을 저버리고 도리를 어그러뜨리는 말을 임금 앞에서 감히 하느냐. 이제 네 간을 씹고야 말겠다.\" 하며 눈물이 비 오듯 하였다. 황상이 수정의 말을 들으시고 그제야 진량의 간악함을 깨달으시어 말씀하셨다. \"너 같은 놈이 충량한 신하를 억울하게 죽게 하였으니 짐의 밝지 못함을 뉘우치노라.\" 그러고는 진량의 벼슬을 빼앗아 내쫓은 뒤 법관에게 명하여 강서 지방으로 귀양 보내시고, 정국공의 죄명을 풀어 관작을 회복하여 왕후의 예로 장사하라 하셨다. 또 정수정에게 한림학사 겸 간의대부를 제수하시니, 수정이 은혜에 사례하고 나왔다. 이때 장연이 한림원에서 정수정을 보고 서로 인사를 마친 뒤 장연이 말하였다.","sp":[[19,21,"P","정수정"],[31,33,"P","진량"],[62,64,"P","천자"],[79,81,"P","진량"],[243,245,"P","천자"],[247,249,"P","정수정"],[263,265,"P","진량"],[338,340,"P","진량"],[382,385,"P","정흠"],[422,425,"P","정수정"],[448,450,"P","정수정"],[469,471,"P","장연"],[479,482,"P","정수정"],[499,501,"P","장연"]]},{"c":1,"sub":"","t":"\"지난날 우리 부친과 영대인께서 서로 언약하시어 소생과 영매(令妹)를 혼인시키기로 정하셨는데, 피차 불행하여 삼 년 동안 상중에 있었을 뿐 아니라, 듣자니 영매께서 절강으로 분상(奔喪)하여 몇 해째 집에 돌아오지 않았다 하시기에 혼사를 지금껏 의논하지 못하였소. 이제 우리 두 사람이 새로 만났으니 곧 날을 가려 혼례를 치르고자 하오. 부디 형은 미루지 마시오.\" 수정이 고운 얼굴에 잠깐 부끄러운 빛을 띠고 말하였다. \"소제가 운이 불행하여 부친이 만 리 먼 땅에서 세상을 떠나시매, 그때 모친께서 소제 남매를 데리고 절강으로 분상하러 가시다가 도중에 도적의 변을 만나, 모친과 누이동생은 끝내 물속의 원혼을 면하지 못하고 소제만 겨우 목숨을 부지하였습니다. 하늘이 무너지는 슬픔과 몸이 반으로 갈라지는 아픔이 날로 더하더니, 오늘 형의 말을 들으니 새로이 슬픕니다.\"","sp":[[204,206,"P","정수정"]]},{"c":1,"sub":"","t":"장연이 다 듣고 놀라 탄식하며 말하였다. \"그렇다면 어찌하여 진작 부고를 알리지 않았소?\" 수정이 말하였다. \"그때를 당하여 경황이 없는 중이라 미처 생각하지 못하였으니, 오늘 형에게 부고를 알리지 못한 허물은 면하지 못하겠습니다.\" 하루는 황상이 경풍루에 나와 앉으시어 정·장 두 사람을 불러 이르셨다. \"경들은 오늘 봄 경치를 두고 각기 시를 지어 짐의 적적함을 풀게 하라.\" 두 사람이 명을 받고 곧 지필을 가져다 단숨에 써서 일시에 바치니, 황상이 보시매 시의 말이 민첩하고 경물이 두루 갖추어져 더할 나위 없이 훌륭하였다.","sp":[[0,2,"P","장연"],[51,53,"P","정수정"],[135,137,"P","천자"],[251,253,"P","천자"]]},{"c":1,"sub":"","t":"황상이 칭찬해 마지않으시고, 특별히 장연을 대사도로 삼고 정수정을 자정전 학사로 삼으셨다. 이때 간관들이 연명하여 간하였다. \"정·장 두 사람의 재주가 비록 비상하오나 나이가 아직 어리니 그 직분이 과할까 하옵니다.\" 황상이 진노하시어 말씀하셨다. \"나이가 많고 적음으로 벼슬을 줄 것이라면 재주의 높고 낮음은 따지지 않는 것이 옳으냐.\" 하시고 다시 정수정을 병부상서 겸 표기장군 병마도총독으로 삼으시고, 장연을 이부상서 겸 대사도로 삼으셨다. 두 사람이 감당하지 못하겠다며 굳이 사양하였으나 황상이 끝내 허락하지 않으시니, 두 사람은 할 수 없이 은혜에 사례하고 각각 집으로 돌아왔다. 장 상서의 모친이 상서의 손을 잡고 옛일을 생각하며 슬퍼하므로, 상서는 모친을 위로하며 정수정이 그간 환란을 당한 일과 그 누이의 사연을 아뢰었다. 왕부인이 처연하게 말하였다. \"그 아이가 이미 죽었으면 마땅히 다른 곳의 숙녀를 구하여 너의 아내 자리를 비워 두지 말아야겠다.\" 상서도 비창하게 여겨 듣고만 있을 따름이었다.","sp":[[0,2,"P","천자"],[20,22,"P","장연"],[32,35,"P","정수정"],[122,124,"P","천자"],[197,200,"P","정수정"],[228,230,"P","장연"],[277,279,"P","천자"],[330,334,"P","장훈"],[379,382,"P","정수정"],[413,416,"P","왕부인"]]},{"c":1,"sub":"","t":"이때 각로 위 승상은 대대로 공후의 후손이요 오래된 명문가로, 부귀는 한 세상에 으뜸이었으나 슬하에 피붙이가 없어 늘 서러워하다가 늦게야 딸 하나를 두었는데, 용모와 재질이 세상에 짝이 없었다. 이때 소저의 나이가 열여섯에 이르렀다. 부인 강씨가 각로에게 말하였다. \"바삐 딸아이의 배필을 구하여 원앙이 짝지어 노는 것을 보고, 우리 뒷일을 맡겨 노년의 재미를 보는 것이 어찌 아름답지 않겠습니까.\" 각로가 말하였다. \"부인이 말씀하지 않아도 세상에 좋은 신랑감을 알아보니, 지금 이부상서 장연은 인물과 풍도며 공명과 학문으로 명망이 한 세상의 추앙을 받고 있소. 또 듣자니 아직 혼인한 곳이 없다 하니 그곳에 청혼해 보리다.\" 하고 곧 매파를 장씨 집에 보내 혼사를 통하니, 장 상서 부인도 잘 아는 집이라 곧 허락하여 보냈다. 날을 가려 납폐한 뒤 혼례를 치르는데, 장 상서가 위의를 갖추어 위씨 집에 나가 기러기를 전하고 교배청으로 들어가니, 각로 부부의 즐거움은 말할 것도 없고 가득한 손님들의 칭송하는 소리가 안팎에 진동하였다.","sp":[[3,5,"P","정수정"],[6,10,"P","위 각로"],[138,140,"P","정수정"],[224,226,"P","정수정"],[274,276,"P","장연"],[379,383,"P","장훈"],[431,435,"P","장훈"],[445,447,"P","위씨"],[475,477,"P","정수정"]]},{"c":1,"sub":"","t":"이윽고 수십 명의 시녀가 신부를 옹위하여 나왔다. 상서가 눈을 들어 잠깐 보니, 꽃 같은 얼굴과 달 같은 자태에 정숙하고 아름다운 자색이 참으로 세상에 드문 규수였다. 두 사람이 맞절을 마친 뒤 어느덧 날이 저물어 저녁상을 물리자, 시녀들이 신랑 신부를 인도하여 침실로 나아가 서로 자리를 정하였다. 신부의 고운 자태와 신랑의 뛰어난 기상이 참으로 군자의 좋은 짝이요 요조숙녀였다. 이윽고 촛불을 물리고 두 사람이 비단 이불 속에 드니 그 다정한 정이야 비할 데가 없었다. 이튿날 아침 상서가 본가로 돌아와 사당에 배알하고 모친께 뵈니, 왕부인의 기뻐함은 이루 형언할 수 없었다.","sp":[[301,304,"P","왕부인"]]},{"c":1,"sub":"","t":"이때 강서 도독 한복이 장계를 올렸는데, 북방 오랑캐가 강성하여 군사 십만을 일으켜 관북 칠십여 성의 항복을 받고 여남 태수 장모를 베어 병세가 매우 크다 하였다. 황상이 크게 놀라 문무 신하를 모아 의논하시니, 여러 신하가 아뢰었다. \"정수정이 문무를 겸비하였고 벼슬이 또한 표기장군이니 적병을 막을 수 있을까 합니다.\" 황상이 크게 기뻐하시어 곧 정수정을 부르시니, 수정이 황명을 받고 곧 입궐하여 뵈었다. 황상이 말씀하셨다. \"이제 북쪽 도적이 국경을 침범하여 형세가 급하다.","sp":[[3,8,"P","한복"],[9,11,"P","한복"],[92,94,"P","천자"],[133,136,"P","정수정"],[181,183,"P","천자"],[196,199,"P","정수정"],[207,209,"P","정수정"],[230,232,"P","천자"]]},{"c":1,"sub":"","t":"짐이 몹시 근심하던 차에 조정의 여러 신하가 다 경을 내보내면 짐의 근심을 덜 것이라 하니, 경은 한 몸의 수고를 아끼지 말고 만백성을 도탄에서 건지라.\" 수정이 엎드려 아뢰었다. \"신이 비록 재주가 없으나 신하 된 몸으로 이런 때를 당하여 어찌 수고를 아끼겠습니까. 간과 뇌를 땅에 쏟는 한이 있어도 도적을 깨뜨려 폐하의 근심을 덜겠습니다.\" 황상이 크게 기뻐하시어 곧 정수정을 평북대원수 겸 제도병마도총 대도독으로 삼으시고 인검을 주시며 이르셨다. \"제후라도 만일 영을 어기는 자가 있거든 먼저 베고 뒤에 아뢰라.\" 원수가 은혜에 사례하고 명을 받은 뒤 다시 아뢰었다. \"군중에는 중군이 있어야 군정을 살필 수 있으니 어찌하면 좋겠습니까.\"","sp":[[87,89,"P","정수정"],[193,195,"P","천자"],[208,211,"P","정수정"],[327,329,"P","장연"]]},{"c":1,"sub":"","t":"황상이 말씀하셨다. \"그러면 경이 골라 천거하라.\" 수정이 아뢰었다. \"이부상서 장연이 그 소임을 감당할까 합니다.\" 황상이 크게 기뻐하시어 곧 장연을 중군으로 삼으셨다. 원수는 물러나와 진국장군 관영에게 군사 십만을 조련하라 하고, 궐 아래에 나가 천자께 하직한 뒤 교장으로 나가 장대에 높이 앉았다. 중군 장연에게 영을 내려 빨리 진 위로 대령하라 하고, 여러 장수에게 군례를 받은 뒤 관영을 선봉으로 삼고, 양주 자사 진시희를 후군으로 삼고, 대장군 서래를 군량총독관으로 삼았다.","sp":[[0,2,"P","천자"],[29,31,"P","정수정"],[45,47,"P","장연"],[66,68,"P","천자"],[81,83,"P","장연"],[85,87,"P","장연"],[110,112,"P","관영"],[140,142,"P","천자"],[170,172,"P","장연"],[173,175,"P","장연"],[218,220,"P","관영"],[237,240,"P","진시회"]]},{"c":1,"sub":"","t":"이때 중군에 임명한다는 영이 장 상서 집에 이르니, 장연이 크게 놀라 수정의 아래가 된 것이 마음에 몹시 언짢았다. 그러나 이미 국가의 큰일이요 군중의 호령이라 장수의 영을 거역하지 못하여, 모친께 하직한 뒤 갑주를 갖추고 말에 올라 교장으로 나갔다. 이때 원수가 중군의 군례를 받는데, 갑주를 갖추고 장대에 높이 앉아 좌우에 여러 장수와 군졸을 벌여 세워 위의를 엄숙히 하고 중군을 불러들였다. 걸음을 빨리 걸으라는 호령이 서릿발 같으니, 장연은 더욱 마음이 불쾌하였으나 군령이라 어찌할 수 없어 법례대로 몸을 굽히며 들어와 장대 아래 꿇어앉아 군례로 뵈었다.","sp":[[3,5,"P","장연"],[16,20,"P","장훈"],[29,31,"P","장연"],[39,41,"P","정수정"],[148,150,"P","장연"],[211,213,"P","장연"],[247,249,"P","장연"]]},{"c":1,"sub":"","t":"원수는 속으로 웃음이 나왔으나 겉모습을 더욱 엄정히 하고 분부하였다. \"이제 적세가 급하니 내일 행군하여 기주로 갈 것이다. 그대는 날이 밝을 무렵 군사를 거느리고 대령하라. 군중에는 사정이 없으니 유념하라.\" 중군이 명을 받고 물러났다. 이때 원수가 행군하여 기주 경계에 이르니, 적세가 매우 커서 삼백 리 들에 가득하였다. 원수는 진을 치고 적진에 격서를 보내 싸움을 돋우니, 오랑캐 장수 마웅도 진문을 열고 창을 바로 들고 말을 타고 나왔다. 원수가 채찍을 들어 크게 꾸짖었다. \"무지한 오랑캐가 하늘의 때를 모르고 까닭 없이 군사를 일으켜 국경을 범하니, 황상께서 나에게 너희를 소멸하라 하시어 여기 이르렀다. 너는 빨리 나와 내 칼을 받으라.\" 마웅이 크게 노하여 맹돌통에게 대적하라 하니, 맹돌통이 팔십 근 도끼를 휘두르며 말을 내몰아 꾸짖었다. \"너 같은 입에서 젖내 나는 아이가 어찌 나를 당하겠느냐.\" 하고","sp":[[118,120,"P","장연"],[220,222,"P","마웅"],[315,317,"P","천자"],[366,368,"P","마웅"],[377,380,"P","맹돌통"],[392,395,"P","맹돌통"]]},{"c":1,"sub":"","t":"진을 들이치려 할 즈음, 송나라 진영의 선봉 관영이 내달아 십여 합을 싸웠다. 맹돌통이 크게 고함치며 도끼를 들어 관영의 말을 쳐 엎어뜨리니 관영이 말 아래로 떨어졌다. 이때 원수가 장대에서 두 진의 승패를 보다가 관영이 위급한 것을 보고 급히 말에 올라 칼을 들고 크게 소리쳤다. \"적장은 나의 선봉을 해치지 마라.\" 하고 달려들어 맹돌통과 싸우는데, 한 합도 되기 전에 원수의 칼이 번뜩하며 맹돌통의 머리가 말 아래로 떨어졌다. 그 머리를 집어 말에 달고 적진을 짓쳐 들어가니, 마웅이 맹돌통의 죽음을 보고 크게 놀라 진 안으로 들어가 나오지 않았다. 원수가 적진 앞면을 헤치며 좌충우돌하여 중군에 이르렀으나 감히 나와 막는 자가 없었다. 적장 오평이 원수가 무인지경같이 좌충우돌하는 것을 보고 분을 이기지 못하여 방천화극을 휘두르며 급히 내달아 싸웠으나, 삼십여 합 만에 문득 당해 내지 못하고 달아났다.","sp":[[25,27,"P","관영"],[44,47,"P","맹돌통"],[64,66,"P","관영"],[79,81,"P","관영"],[120,122,"P","관영"],[187,190,"P","맹돌통"],[221,224,"P","맹돌통"],[270,272,"P","마웅"],[274,277,"P","맹돌통"],[333,335,"P","장연"],[363,365,"P","오평"]]},{"c":1,"sub":"","t":"이때 원수는 오평이 달아나는 것을 보고 쫓으려 하면서 중군을 불러 분부하였다. \"그대는 중군을 굳게 지켜 나오지 말고 내가 돌아오기를 기다려라. 만일 한 번이라도 진지를 떠났다가 군중에 무슨 일이 생기면 군법에는 사정이 없으니 부디 유념하라.\" 이렇게 거듭 당부하고 말머리를 돌려 적장 오평을 쫓아 남쪽으로 달려갔다. 그런데 문득 오평은 간 곳이 없고 별안간 적병이 사면으로 철통같이 에워쌌다. 원수가 크게 노하여 왼손에 장창을 들고 오른손에 보검을 비껴 들고, 남쪽으로 번뜻 북쪽 장수를 베고 동쪽으로 번쩍 서쪽 장수를 베니, 적진 장졸의 머리가 가을바람에 지는 낙엽 같았다.","sp":[[7,9,"P","오평"],[30,32,"P","장연"],[49,51,"P","장연"],[160,162,"P","오평"],[185,187,"P","오평"]]},{"c":1,"sub":"","t":"이때 장연은 중군을 지키고 있으면서 두 진의 승패를 보다가, 정수정이 맹돌통을 베고 또 오평의 진을 깨뜨려 무인지경같이 휘젓고 다니는 것을 보았다. 적진 장졸을 필경 씨도 없이 없애고 큰 공을 세울 일은 다행이었으나, 스스로 생각하니 내 벼슬이 정수정의 밑에 든 것도 분한데, 이번 출정(出征)에 수정은 적진 장졸을 풀 베듯 하여 큰 공을 세우는데 나는 적졸 하나 잡은 공도 없으면 이다음에 무슨 낯으로 황상을 뵈며, 끝끝내 정수정의 밑에 들 것을 생각하니 부끄러운 일이 한두 가지가 아니었다.","sp":[[3,5,"P","장연"],[7,9,"P","장연"],[34,37,"P","정수정"],[39,42,"P","맹돌통"],[49,51,"P","오평"],[137,140,"P","정수정"],[166,168,"P","정수정"],[226,228,"P","천자"],[238,241,"P","정수정"]]},{"c":1,"sub":"","t":"그런 생각에 어떻게든 적장 하나라도 벤 공을 세워 남의 수치를 면하리라는 마음이 가득하던 차에, 마침 적장 오평이 원수에게 패하여 도망하는 것을 보고 칼을 들고 급히 말에 올라 오평을 쫓아갔다. 이때 오랑캐 장수 마웅이, 송나라 진을 지키던 장수 장연이 진을 비우고 나가는 것을 보고 급히 군사를 몰아 송나라 진을 엄습하여 장연을 철통같이 에워쌌다. 장연이 크게 놀랐으나 오도 가도 못하고 적병에게 둘러싸였다. 아무리 용맹을 다하여 돌진한들 어찌 벗어나겠는가. 힘을 다하여 산골짜기로 달아나는데, 별안간 타고 있던 말이 적장 올돌골의 화살에 맞아 앞다리를 꿇고 엎어지며 장연이 땅에 떨어졌다.","sp":[[60,62,"P","오평"],[99,101,"P","오평"],[119,121,"P","마웅"],[138,140,"P","장연"],[181,183,"P","장연"],[196,198,"P","장연"],[319,321,"P","장연"]]},{"c":1,"sub":"","t":"올돌골이 한 번 고함치며 창을 들고 달려들어 찌르려 할 즈음, 난데없는 대장 한 사람이 화살같이 달려오며 크게 소리쳤다. \"적장은 나의 중군을 해치지 마라.\" 하며 칼이 번뜩하여 올돌골의 머리를 베어 들고 장연을 구하여 본진으로 돌아갔다. 그 장수가 누구인가 하면, 정 원수가 적장 오평의 진을 짓쳐 버리고 본진으로 돌아오다가 중군장 장연이 적진에 둘러싸였다는 말을 듣고 급히 와서 구한 것이었다. 이때 원수는 본진으로 돌아와 장대에 높이 앉아 장연을 잡아들여 꿇리고 죄를 따졌다. \"내가 출전할 때 너에게 무엇이라 당부하였기에, 네가 함부로 장수의 영을 어기고 진중을 비워 적국의 웃음을 사고 죄 없는 장졸을 죽였느냐. 그 죄는 군법에 용서하지 못할 것이다.\" 하고 곧 도부수에게 명하였다. \"중군 장연은 장수의 영을 어긴 죄로 군문 밖에 내어 베어라.\"","sp":[[76,78,"P","장연"],[115,117,"P","장연"],[149,153,"P","정수정"],[158,160,"P","오평"],[183,185,"P","장연"],[187,189,"P","장연"],[249,251,"P","장연"],[389,391,"P","장연"],[392,394,"P","장연"]]},{"c":1,"sub":"","t":"호령이 서릿발 같았다. 이때 좌우의 여러 장수가 일시에 꿇어앉아 아뢰었다. \"중군의 죄는 죽어 마땅하오나, 적국을 아직 깨뜨리지 못한 터에 대장을 베는 것은 군중에 이롭지 못할까 하오니, 우선 용서하시기를 바랍니다.\" 원수가 마지못하여 말하였다. \"여러 장수의 낯을 보아 우선 용서는 하거니와 이다음에는 십분 유념하여 행하라.\" 하고 군문 밖으로 끌어내치니, 이때 장연은 속으로 불만이 가득하였다.","sp":[[43,45,"P","장연"],[204,206,"P","장연"]]},{"c":1,"sub":"","t":"한편 마웅은 송나라 원수가 올돌골을 베고 장연을 구해 가는 것을 보고 탄식하였다. \"조그마한 아이를 에워싸고도 잡지 못하고 도리어 애꿎은 장졸만 죽였으니, 이는 하늘이 나를 망하게 하는 것이로다.\" 하고 다시 송나라 진을 깨뜨릴 의논을 하였다. 이때 강서 도독 한복은 당대의 영웅이었다. 뜻밖에 오랑캐 군사가 중군을 에워싼 것을 보고 크게 놀라 철기 오천을 거느리고 포위를 헤치고 들어가 구원하다가, 원수를 만나 힘을 합쳐 적병을 물리치고 승전고를 울리며 본진으로 돌아왔다. 장졸을 먹이고 위로한 뒤 한복과 관영이 원수께 사례하였다. \"원수의 용맹은 초패왕이라도 미치지 못하겠습니다.\"","sp":[[3,5,"P","마웅"],[23,25,"P","장연"],[140,145,"P","한복"],[146,148,"P","한복"],[173,175,"P","장연"],[280,282,"P","한복"],[284,286,"P","관영"]]},{"c":1,"sub":"","t":"마웅은 패잔군을 수습하여 호수를 건너 진을 치고 오평을 선봉으로 삼았다. 이때 원수가 여러 장수를 불러 말하였다. \"이제 마웅이 물을 건너 진을 친 것은 구원병을 청하려는 것이니, 마땅히 이때를 타서 쳐야 한다.\" 하고 한복을 불러 말하였다. \"그대는 철기 오천을 거느리고 흥양에 매복하였다가 적병이 패하면 그곳으로 갈 것이니 급히 내달아 치라.\" 기주 자사 손경을 불러 말하였다. \"그대는 정병 삼만을 거느리고 불로 치되 이러이러하라.\" 선봉 관영을 불러 말하였다. \"너는 삼천 병을 거느리고 이러이러하라.\" 여러 장수가 명을 받고 각각 군마를 거느리고 갔다. [?]","sp":[[0,2,"P","마웅"],[27,29,"P","오평"],[68,70,"P","마웅"],[123,125,"P","한복"],[201,203,"P","손경"],[249,251,"P","관영"]]},{"c":1,"sub":"","t":"원수는 이날 황혼에 군사를 먹이고 이경에 철기를 거느리고 가만히 물을 건너 적진으로 향하였다. 때는 바로 삼경이라 적진의 등불이 다 꺼지고 아무 준비가 없었다. 사면을 살펴보니 산천이 험악하고 길이 좁았다. 원수가 속으로 크게 기뻐하여 군사들에게 포를 한 번 쏘게 하니, 사면에서 불이 일어나 불빛이 하늘에 닿고 징과 북이 일제히 울리며 함성이 천지를 움직였다. 적병이 뜻밖의 변을 당하여 정신을 잃고 서로 짓밟으며 달아나는데, 불빛 가운데 소년 대장 한 사람이 칼을 휘두르며 길을 막고 말하였다. \"적장은 달아나지 말고 내 칼을 받으라.\" 그 소리에 산천이 울렸다.","sp":[]},{"c":1,"sub":"","t":"마웅이 겁에 질려 샛길로 불꽃을 무릅쓰고 달아나는데, 홀연 등 뒤에서 함성이 일며 손경이 칼을 휘두르며 쫓아오고 앞에서는 원수가 길을 막았다. 마웅이 비록 용맹하나 어찌 벗어나겠는가. 갈 바를 모르다가 형세가 급한 것을 보고 힘을 다하여 왼편으로 달아나는데, 중군장 장연이 또 내달아 길을 막으며 활을 쏘았다. 마웅이 몸을 기울여 화살을 피하며 분연히 장연과 다시 싸웠는데, 십여 합 만에 마웅이 장연의 말을 찔러 엎어뜨리고 장연을 베려 할 즈음, 문득 원수가 창을 휘두르며 뒤에서 달려들어 크게 한 번 소리치며 마웅을 베었다. 오평은 마웅이 죽는 것을 보고 혼이 빠지고 간담이 떨어져 겨우 목숨을 건져 도망하여 한 산을 넘어 흥양을 바라고 달아났다. 그런데 앞에서 또 함성이 일며 한 떼의 군사가 내달아 오평을 사로잡으니, 이는 위수대장 한복이었다. 이때 원수가 군사를 몰아 엄습하자 적진의 장졸이 일시에 항복하였다. 손경에게 일일이 끌고 오게 하여 본진으로 돌아오니 한복도 오평을 잡아 왔다. 원수가 장대에 높이 앉아 오평을 잡아들여 계단 아래 꿇리니, 오평이 눈을 부릅뜨고 항복하지 않았다. 원수가 크게 노하여 무사에게 명하여 오평을 베었다.","sp":[[0,2,"P","마웅"],[46,48,"P","손경"],[80,82,"P","마웅"],[145,147,"P","장연"],[149,151,"P","장연"],[174,176,"P","마웅"],[197,199,"P","장연"],[218,220,"P","마웅"],[222,224,"P","장연"],[238,240,"P","장연"],[287,289,"P","마웅"],[296,298,"P","오평"],[300,302,"P","마웅"],[395,397,"P","오평"],[409,413,"P","한복"],[414,416,"P","한복"],[459,461,"P","손경"],[487,489,"P","한복"],[491,493,"P","오평"],[516,518,"P","오평"],[536,538,"P","오평"],[578,580,"P","오평"]]},{"c":1,"sub":"","t":"원수는 오랑캐 군사를 소멸하고 승전 보고서를 조정에 올린 뒤, 대군을 지휘하여 황성으로 향하였다. 이에 앞서 황상은 정수정의 소식을 몰라 밤낮 근심하시다가, 승전 보고서가 온 것을 보시고 크게 기뻐하시어 속히 회군하라는 조서를 내리시고 정수정이 돌아오기를 기다리셨다. 이때 원수가 회군하여 오다가 포주 땅에 이르러, 중군 장연에게 여러 장수와 군졸을 거느리고 먼저 황성으로 가게 하였다. 자기는 곧바로 절강으로 가서 부친의 백골을 운구해 오는 김에 화적 무리를 없애 모친의 원수도 갚으려고, 절강 총독에게 영을 내려 강가와 길가의 화적 무리를 하나하나 잡아들여 가둔 뒤 보고하라 하였다. 그러고는 수하 친병 삼천만 데리고 절강으로 향하니, 지나는 고을마다 방백과 수령들이 바치는 대접과 예절이 비할 데 없었다.","sp":[[61,63,"P","천자"],[65,68,"P","정수정"],[132,135,"P","정수정"],[177,179,"P","장연"],[180,182,"P","장연"]]},{"c":1,"sub":"","t":"양씨 부인은 남편의 빈소 옆에 집을 짓고 이춘보만 데리고 지내면서, 남편이 먼 땅에서 죄명을 벗지 못하고 원통하게 죽은 일이며, 딸이 물 위에서 도적 떼를 만난 뒤 생사존망을 모르는 일을 어느 날 어느 때 잠시인들 잊겠는가. 봄바람에 복숭아꽃 오얏꽃이 필 때나 가을비에 오동잎이 질 때면, 한숨과 긴 탄식에 뜨거운 눈물로 옷깃이 마를 날 없이 세월을 보낸 지가 어느덧 서너 해였다. 하루는 봄날이 따뜻하여 남편의 무덤 앞에 올라가 슬픈 눈물을 뿌리며 하염없이 앉아 있노라니, 별안간 본부 관속들이 떼를 지어 나와 이르기를 평북대원수 행차가 오신다 하며, 국공의 무덤 앞에 장막을 치고 자리를 펴며 떠들썩하였다.","sp":[[0,5,"P","양씨 부인"],[23,26,"P","이춘보"],[310,312,"P","정흠"]]},{"c":1,"sub":"","t":"이때 양씨 부인은 속으로 깜짝 놀랐으나 무슨 곡절인지 누구에게 물어볼 새도 없이 황급히 지내던 초막으로 내려와, 혼자 짐작하기를 이제야 나라에서 사면이 내리셨나 보다 하고 은근히 기쁜 마음으로 동정만 살피고 있었다. 얼마 지나지 않아 전에 구경도 못 하던 한 떼의 군마가 물밀듯 들어오며 깃발과 창검이 별처럼 좌우로 갈라서더니, 그 뒤로 풍채 좋은 소년 하나가 흰옷에 흰 띠를 두르고 은 안장을 얹은 준마를 타고 왔다. 말에서 내리자 국공의 무덤으로 달려들어 미처 절할 겨를도 없이 엎어져 소리 높여 통곡하다가, 얼마 만에 다시 정신을 차려 제물을 갖추어 벌여 놓고 제문을 읽었는데 그 글은 이러하였다.","sp":[[3,8,"P","양씨 부인"],[243,245,"P","정흠"]]},{"c":1,"sub":"","t":"\"유세차 모년 모월 모일 갑신에, 불초자 수정은 돌아가신 아버님 전 병부상서 표기장군 국공 부군의 신위에 감히 고하나이다. 슬프다, 불초자 수정은 열 살도 못 되어 아버님 슬하를 떠나 어머님을 모시고 있다가 중간에 환란은 스스로 겪었으며, 아버님의 영구는 이제 받들어 고향으로 모시려 하오나 어머님의 영혼은 어느 곳에서 위로하오리까. 아아, 원통하도다. 불초자 수정은 하늘의 은혜가 두터워 벼슬이 일품에 이르러, 남쪽을 치고 북쪽 땅에서 나라의 도적을 토멸하여 위로 나라의 은혜에 보답하였고, 진량을 먼 땅으로 귀양 보내었으니 국가에는 다행이오나 개인의 원수는 아직 갚지 못하였사오니, 엎드려 바라건대 존령께서는 굽어살피소서.\" 하였다. [?]","sp":[[23,25,"P","정수정"],[48,50,"P","정흠"],[78,80,"P","정수정"],[202,204,"P","정수정"],[276,278,"P","진량"]]},{"c":1,"sub":"","t":"읽기를 마치고 다시 한 번 통곡하니 슬픈 눈물이 비 오듯 하여, 좌우에서 보는 사람 가운데 누가 슬퍼하지 않았겠는가. 이때 충직하기로 이름난 이춘보가 이 거동을 보고 슬픈 가운데 분한 마음이 가슴에 가득하여, 죽기를 무릅쓰고 달려들어 따져 물었다. \"상공은 뉘시며, 이 무덤이 누구의 무덤인 줄 알고 이처럼 오셔서 애통해하십니까. 이 무덤은 이 땅에 귀양 오셔서 작고하신 정국공 상공의 무덤인데, 국공께서는 본디 자손이 없어 지금껏 고향으로 운구도 못 해 가시고 백골이 지금껏 귀양지에 계신 터입니다. 상공께서 필경 잘못 알고 오셔서 이러시나 싶으니 상공은 살피소서.\" 원수는 정신없이 울다가 그 사람의 목소리를 듣고 다시 얼굴을 물끄러미 보더니 그만 반색하여 말하였다. \"네가 이춘보가 아니냐. 네가 수정이를 몰라본단 말이냐.\" 하며 춘보의 옷자락을 움켜잡고 소리 높여 통곡하였다. 춘보가 가뜩이나 의아하던 판에 수정이란 말을 듣고 얼굴을 자세히 뜯어보니 틀림없는 자기 댁 수정 소저였다.","sp":[[79,82,"P","이춘보"],[208,211,"P","정흠"],[222,224,"P","정흠"],[380,383,"P","이춘보"],[393,395,"P","정수정"],[412,414,"P","이춘보"],[439,441,"P","이춘보"],[456,458,"P","정수정"],[490,492,"P","정수정"]]},{"c":1,"sub":"","t":"원래 수정 소저는 이춘보를 얼른 알아보았지만, 춘보로서는 어린 수정 소저와 헤어진 지가 예닐곱 해가 되었으니 자라는 사람을 어찌 얼른 알아보겠는가. 게다가 여자가 남자로 변하여 천병만마를 거느린 대원수로 왔으니 어찌 생각이나 하였겠는가. 그렇지만 원래 생각이 넓고 눈치 빠른 이춘보라 얼른 짐작하고 대답하였다. \"소인이 여러 해 이곳에서 풍상에 시달리고 늙어 눈이 어두워 상공을 처음에 몰라뵈었습니다.\" 하고 다시 반가움을 이기지 못하여 눈물을 흘리며, 대부인 마님을 모시고 이곳에 와서 상공의 무덤을 모시고 세월을 보내는 사연을 대강 아뢰었다. 원수가 크게 놀라 말하였다. \"네 말이 참말이냐 거짓말이냐. 대부인 마님께서 어느 곳에 계시단 말이냐. 어서 길을 인도하여 뵙게 하여라.\" 춘보도 급한 마음에 부인께 미리 알릴 새도 없이 원수를 모시고 부인이 계신 움막 같은 초막으로 들어갔다.","sp":[[3,5,"P","정수정"],[10,13,"P","이춘보"],[26,28,"P","이춘보"],[35,37,"P","정수정"],[154,157,"P","이춘보"],[384,386,"P","이춘보"]]},{"c":1,"sub":"","t":"이때 양씨 부인은 여러 번 놀란 사람이라 국공의 묘소에 그런 야단이 난 것을 보고 또 무슨 일이 생기는가 하여 가슴이 두근두근하고, 궁금함을 이기지 못해 마음을 졸이며 앉아 있었다. 그런데 별안간 또 문 앞이 떠들썩하며 이춘보가 웬 소년 남자 하나를 데리고 들어왔다. 깜짝 놀라 몸을 피하려 하였으나 콧구멍만 한 초가집이라 몸 하나 돌아설 곳이 없어 갈팡질팡하며 이게 웬일이냐고 소리를 지르려 할 즈음, 그 남자가 다짜고짜 와락 달려들며 부인을 얼싸안고 \"어머니, 수정이를 몰라보십니까?\"","sp":[[3,8,"P","양씨 부인"],[23,25,"P","정흠"],[123,126,"P","이춘보"],[260,262,"P","정수정"]]},{"c":1,"sub":"","t":"한마디를 겨우 하고 울음이 북받쳐 혼절하였다. 이때 부인은 아무 영문도 모르고 겁결에 몸만 빼쳐 피하려다가, 어머니 부르는 소리와 수정이란 말에 정신이 번쩍 나서 자세히 보니, 차림새는 다르나 얼굴은 틀림없는 수정이었다. 그만 달려들어 얼싸안고 서로 통곡하다가 겨우 정신을 차려 물었다. \"네가 그때 배 안에서 어떻게 목숨을 건졌으며, 어디 가서 의탁하였다가 지금 저렇게 귀하게 되었으며, 또 여자 몸으로 남복을 하였으니 그게 다 무슨 곡절이냐?\" 수정이 눈물을 거두고, 그때 배 안에서 살아나 유모를 데리고 정처 없이 가다가 군산 칠보암 여승의 구함을 받아 그 절로 가서 밤낮을 가리지 않고 공부하던 일, 유모와 함께 남복을 하고 다시 황성으로 올라가 과거에 급제하여 벼슬한 일, 오랑캐 도적이 강성하여 대원수가 되어 장연과 함께 전장에 나가 공을 이룬 뒤 회군하는 길에 중군 장연에게 장졸을 거느리고 먼저 황성으로 보내고, 자기는 이곳에 와서 부친의 백골도 모셔 가고 화적 무리도 잡아 모친의 원수도 갚으려고 온 사연을 하나하나 아뢰었다.","sp":[[73,75,"P","정수정"],[117,119,"P","정수정"],[251,253,"P","정수정"],[277,279,"P","유모"],[302,304,"P","정현"],[340,342,"P","유모"],[403,405,"P","장연"],[433,435,"P","장연"],[436,438,"P","장연"]]},{"c":1,"sub":"","t":"양부인이 놀라 물었다. \"그러면 장연이 너인 줄 알았느냐?\" 수정이 말하였다. \"나라에서도 소녀를 계집인 줄 모르셨는데 장연이 어찌 알겠습니까. 장연을 관청에서 만났을 때 묻기에, 누이가 있다가 환란을 만나 죽었다고 하였습니다.\" \"그러면 그 사람이 아직 장가를 들지 않았느냐?\" 수정이 말하였다. \"그저 있을 리가 있겠습니까. 곧 위 상국의 딸과 혼인하였습니다.\" 부인이 말하였다. \"그러면 너의 백년대사는 어찌하려 하느냐?\" 수정이 고개를 숙이고 아무 대답이 없다가, 또 진량의 죄를 황상께 아뢰어 강서로 귀양 보냈으나 아직 원수를 갚지 못하여 밤낮 한스럽다는 말을 하나하나 아뢰었다. 부인이 수정의 등을 어루만지며 말하였다. \"너는 옛날 목란보다도 나은 효녀로다.\" 그러고는 또 자기가 그때 배 안에서 도적에게 잡혀 나와 하마터면 큰 욕을 면하지 못하고 죽을 뻔한 것을, 천행으로 이춘보와 도적 가운데서도 나호철의 힘으로 살아나 이곳으로 온 이야기를 하나하나 하니, 수정이 더욱 흐느꼈다.","sp":[[0,3,"P","양씨 부인"],[18,20,"P","장연"],[34,36,"P","정수정"],[67,69,"P","장연"],[81,83,"P","장연"],[157,159,"P","정수정"],[186,190,"P","위 각로"],[240,242,"P","정수정"],[266,268,"P","진량"],[273,275,"P","천자"],[334,336,"P","정수정"],[440,443,"P","이춘보"],[454,457,"P","나호철"],[488,490,"P","정수정"]]},{"c":1,"sub":"","t":"이튿날 본부 총독이 길가의 화적을 하나하나 잡아 가두었다가 원수에게 보내 처결하게 하였는데, 그 가운데 나호철이라는 놈이 있었다. 원수가 마음에 의아하여 춘보를 불러 물으니 과연 그때 모부인을 구한 도적이었다. 원수가 곧 가까이 불러 보고 치하한 뒤 절강 총독부의 장교로 삼아 대대로 녹을 먹게 하고, 이춘보는 군중의 교위로 삼아 귀하게 되게 하였다.","sp":[[58,61,"P","나호철"],[86,88,"P","이춘보"],[169,172,"P","이춘보"]]},{"c":1,"sub":"","t":"이때 정 원수가 뜻밖에 모친을 만나니 슬픈 가운데서도 기쁜 마음이 어떠하였겠는가. 그곳에서 네댓새 머문 뒤, 표를 올려 부친의 백골을 운구하고 또 모친을 만나 함께 돌아가는 사유를 아뢰고 길을 떠났다. 본부 총독이 위의를 갖추어 대령하였는데, 국공의 영구는 온갖 꽃으로 꾸민 상여(彩轝)에 모셔 수백 군졸이 호위하고, 모부인은 칠보로 꾸민 가마에 모셔 수십 시녀가 옹위하였다. 또 이춘보와 나호철이 위의를 갖추어 좌우로 호위하며 따르고, 원수는 흰 전포에 은 갑옷을 입고 은 안장 얹은 준마를 타고 삼천 병마를 거느려 뒤를 호위하며 떠났다. 국공이 십 년 귀양살이하던 곳이라 산천초목이 다 흐느끼는 듯하고, 구름 낀 산은 첩첩하고 강물은 넘실거려 닿는 곳마다 슬픔과 기쁨(悲喜)이 엇갈렸다.","sp":[[3,7,"P","정수정"],[136,138,"P","정흠"],[213,216,"P","이춘보"],[218,221,"P","나호철"],[303,305,"P","정흠"]]},{"c":1,"sub":"","t":"이렇게 여러 날 만에 고향 선영 아래 이르러 국공의 백골을 안장하는데, 황상께서 벌써 들으시고 예관을 보내 위의를 갖추어 왕후의 예로 장사하게 하셨다. 이때 유모와 여러 시비가 부인을 붙들고 울며불며 반겼다. 부인도 눈물을 뿌리며 유모의 손을 잡고, 소저와 함께 고생하던 일을 끝없이 고마워하였다. 며칠 뒤 정 원수가 복명하러 가니, 황상이 문무 신하를 거느리고 성 밖에 나와 원수를 맞으며 손을 잡고 말씀하셨다. \"짐이 경을 만 리 전장에 보내고 걱정이 간절하였는데, 이제 경이 도적을 소멸하고 개가를 부르며 돌아오니 그 공을 어찌 다 갚겠는가. 또 경의 아비 백골을 받들어 모셔 오고 겸하여 경의 모친을 만났다 하니 듣기에 감사하도다.\"","sp":[[25,27,"P","정흠"],[40,42,"P","천자"],[88,90,"P","유모"],[129,131,"P","유모"],[172,176,"P","정수정"],[187,189,"P","천자"]]},{"c":1,"sub":"","t":"원수가 엎드려 아뢰었다. \"이는 다 폐하의 덕택입니다.\" 황상이 못내 칭찬하시고 환궁하시어, 이튿날 큰 잔치를 베풀고 출전한 장수들에게 작위를 내리셨다. 정수정을 이부상서 겸 도총독 청주후로 봉하시고, 장연을 태학사 겸 부도독 기주후로 봉하시고, 그 나머지 장수는 차례로 봉작하셨다. 정·장 두 사람이 굳이 사양하였으나 황상이 끝내 허락하지 않으시니, 두 사람은 마지못하여 은혜에 사례하고 절한 뒤 각각 본가로 돌아왔다. 황상은 또 양씨 부인을 국공 부인으로 봉하셨다. 청주후는 모친을 모시고 유모와 시비를 대하여 지난 일을 생각하며 새로이 서러워하였다. 그러고는 사당을 모시고 청주로 가고, 장후도 사당과 모부인을 모시고 기주로 갔다.","sp":[[32,34,"P","천자"],[86,89,"P","정수정"],[102,105,"P","정수정"],[113,115,"P","장연"],[127,130,"P","장연"],[179,181,"P","천자"],[236,238,"P","천자"],[242,247,"P","양씨 부인"],[249,254,"P","양씨 부인"],[263,266,"P","정수정"],[276,278,"P","유모"],[332,334,"P","장연"]]},{"c":1,"sub":"","t":"정후는 청주에 도임하여 두루 살펴본 뒤 수성장을 불러 말하였다. \"내가 이제 북쪽 도적을 깨뜨렸으나 북쪽 도적은 본디 간악하니 반드시 또 군사를 일으켜 중원을 침범할 것이다. 여러 고을에서 각별히 연습하여 뜻밖의 변에 대비하라.\" 또 표를 올려 아뢰었다. \"신이 청주를 살펴보니 영웅이 무용을 쓸 만한 땅입니다. 마땅히 지혜와 용맹이 있는 장수를 얻어 두어 북방 오랑캐의 기운을 꺾어야 할 것이니, 양주 자사 진시회와 강서 도독 한복과 호위장군 용봉과 함께 도적을 막기를 원합니다.\" 황상이 표를 보시고 크게 기뻐하시어 세 사람에게 명하여 청주로 보내셨다.","sp":[[0,2,"P","정수정"],[229,232,"P","진시회"],[234,239,"P","한복"],[240,242,"P","한복"],[249,251,"P","용봉"],[271,273,"P","천자"]]},{"c":1,"sub":"","t":"이때는 대법 이십구 년 봄 정월이었다. 천자께서 제후와 문무백관의 조회를 받으실 때 여러 신하를 돌아보며 말씀하셨다. \"청주후 정수정과 기주후 장연을 부마로 삼고자 하니 경들의 뜻은 어떠한가?\" 여러 신하가 일시에 성교가 마땅하다고 아뢰었다. 황상이 청주후를 불러 보시고 말씀하셨다. \"짐에게 공주 하나가 있으니 경을 부마로 삼겠노라.\" 수정이 하교를 듣자 혼비백산하여 엎드려 아뢰었다. \"신의 미천한 몸으로 어찌 금지옥엽과 짝이 되겠습니까. 결코 안 될 일이니 성상께서는 하교를 거두시어 신의 마음을 편하게 하소서.\" 황상이 웃으며 말씀하셨다. \"경이 굳이 사양하는 것은 짐의 후의를 저버리는 것이니 다시 고집하지 마라.\" 또 장연을 불러 말씀하셨다. \"짐에게 누이 하나가 있어 나이가 열여섯이다. 경이 비록 장가를 들었으나 벼슬이 두 아내를 둘 만하니 사양하지 마라.\" 장후는 황공해하며 은혜에 사례하고 물러났다.","sp":[[22,24,"P","천자"],[67,70,"P","정수정"],[71,74,"P","정수정"],[76,79,"P","장연"],[80,82,"P","장연"],[136,138,"P","천자"],[140,143,"P","정수정"],[164,166,"P","공주"],[189,191,"P","정수정"],[291,293,"P","천자"],[352,354,"P","장연"],[433,435,"P","장연"]]},{"c":1,"sub":"","t":"조회를 마친 뒤 정·장 두 제후가 돌아오다가 예부상서 맹동현의 집에 들러 이야기하다가 각각 흩어졌다. 이때 정후가 집으로 돌아오니 모부인이 수정의 안색이 불편한 것을 보고 물었다. \"너 무슨 근심이 있느냐?\" 수정이 꿇어앉아 앞뒤 사연을 아뢰고 눈물을 줄줄 흘리다가, 문득 생각하기를 마땅히 표를 올려 본래 신분을 아뢰어 죄를 면하리라 하고, 이에 표를 올렸다.","sp":[[30,33,"P","맹동현"],[60,62,"P","정수정"],[78,80,"P","정수정"],[117,119,"P","정수정"]]},{"c":1,"sub":"","t":"\"이부상서 겸 병마도총독 청주후 정수정은 머리를 조아려 백 번 절하고 표를 올립니다. 신첩은 운명이 기구하여 열 살 전에 아비가 절강 귀양지에서 죽고 어미는 환란 중에 잃으니, 외로운 여자가 의탁할 곳이 없었습니다. 외람된 뜻을 내어 하늘과 땅을 속이고 남녀를 바꾸어 입신양명하여, 원수 진량을 베어 아비의 원혼을 위로할까 하였습니다. 그런데 천만뜻밖에 공주의 배필로 뽑으시려 하시니 감히 숨기지 못하고 진정을 아룁니다. 신첩이 임금을 속인 죄를 밝혀 다스리소서. 아비 생시에 장연과 정혼하고 납폐까지 하였으나, 신첩이 본래 신분을 감추었기 때문에 장연이 이미 위씨 집에 장가들었습니다. 신첩은 이제부터 빈 규방에서 늙기를 원하오니, 엎드려 바라건대 성상께서는 살피소서.\" 하였다.","sp":[[14,17,"P","정수정"],[18,21,"P","정수정"],[161,163,"P","진량"],[198,200,"P","공주"],[267,269,"P","장연"],[307,309,"P","장연"],[314,316,"P","위씨"]]},{"c":1,"sub":"","t":"황상이 다 읽고 크게 놀라시니, 조정의 백관 가운데 누구 하나 놀라지 않는 이가 없었다. 황상이 곧 장연을 불러 수정의 표를 보이며 물으셨다. \"경이 전에 정수정과 언약이 있었느냐?\" 장연이 대답하였다. \"아비 생시에 정흠과 정혼하고 납폐하였는데, 뒤에 정수정에게 물으니 제 누이가 있다가 죽었다 하기에 신은 그런 줄로만 알고 수정이 남녀를 바꾼 것은 전혀 몰랐습니다.\" 황상이 들으시고 책상을 치며 말씀하셨다. \"참으로 이런 여자는 고금에 드물도다.\" 그리고 표에 비답을 내리셨다. \"경의 표를 보니 무어라 답할 말을 생각하지 못하겠도다. 규중 여자로 뜻을 내어 원수를 갚고자 만 리 전장에 나가 큰 공을 세우고 돌아오니, 짐이 그 재주를 사랑하여 부마로 삼고자 하였더니 오늘 본래 신분이 드러난 것이 도리어 국가의 큰 불행이로다. 경들의 혼사는 짐이 주관할 것이요, 모든 직임은 거두어들이나 청주후는 식읍으로 삼아 두니 그리 알라.\"","sp":[[0,2,"P","천자"],[50,52,"P","천자"],[56,58,"P","장연"],[63,65,"P","정수정"],[87,90,"P","정수정"],[103,105,"P","장연"],[122,124,"P","정흠"],[142,145,"P","정수정"],[183,185,"P","정수정"],[208,210,"P","천자"],[445,448,"P","정수정"]]},{"c":1,"sub":"","t":"정수정은 비답을 보고 다시 상소하여 굳이 사양하였으나 황상이 끝내 허락하지 않으셨다. 정후는 마지못하여 입궐해 은혜에 사례하고 청주로 돌아갔다. 황상이 예부에 하교하여 청주후의 혼사를 준비하라 하시고, 또 장후에게 이르셨다. \"빨리 기주로 돌아가 혼례를 이루라.\" 장후가 천은을 감격히 여겨 곧 기주로 가서 태부인을 뵙고 정수정의 앞뒤 사연과 황상께서 조회 중에 하신 말씀을 하나하나 아뢰고 혼례 준비를 하였다. 이때 황상은 태감을 청주로 보내시어 혼사를 살피게 하셨다. 이럭저럭 길일이 다가오자 정후는 남복을 벗고 여복으로 갈아입었는데, 거울을 대하여 이마를 다듬으니 전날의 원융대장이 변하여 요조숙녀가 되었다.","sp":[[0,3,"P","정수정"],[30,32,"P","천자"],[48,50,"P","정수정"],[81,83,"P","천자"],[94,97,"P","정수정"],[115,117,"P","장연"],[148,150,"P","장연"],[172,175,"P","양씨 부인"],[180,183,"P","정수정"],[192,194,"P","천자"],[234,236,"P","천자"],[278,280,"P","정수정"]]},{"c":1,"sub":"","t":"이날 장후도 위의를 차려 청주로 나아가니 그 위의가 비할 데 없었다. 태감이 주관하여 장후를 맞아 막차에 이르니, 허다한 절차는 사삿집에서는 보지 못하던 것이었다. 이윽고 태감이 조복을 갖추고 장후를 인도하여 절하는 자리에 나가 옥상 위에 기러기를 전하고 교배석으로 들어가니, 녹의홍상을 입은 시녀들이 신부를 옹위하여 나왔다. 용봉 화관을 쓴 아름다운 자색은 사람의 눈을 어지럽게 하였다. 두 사람이 맞절을 마친 뒤 장후가 바깥채로 나오니, 맹동현이 장후를 대하여 웃으며 말하였다. \"지난날 군후가 위 각로의 사위가 될 때 정후에게 놀림받던 것을 보았는데, 오늘 정후가 잡혀 들어와 군후의 아내가 될 줄 어찌 알았겠소.\" 하며 종일 즐겼다. 날이 저물자 손님들은 다 흩어져 가고 장후는 안채에 들어가 저녁상을 물렸다. 시녀들이 향촉을 잡고 신부를 인도하여 들어오니, 장후가 몸을 일으켜 맞이하고 자리를 정한 뒤 바라보니, 신부의 꽃 같은 얼굴과 달 같은 자태가 전날 남장으로 보던 것과는 판이하였다.","sp":[[3,5,"P","장연"],[48,50,"P","장연"],[108,110,"P","장연"],[183,185,"P","용봉"],[233,235,"P","장연"],[247,250,"P","맹동현"],[252,254,"P","장연"],[279,283,"P","위 각로"],[293,295,"P","정수정"],[315,317,"P","정수정"],[380,382,"P","장연"],[429,431,"P","장연"]]},{"c":1,"sub":"","t":"이윽고 촛불을 물린 뒤 신부의 고운 손을 잡고 비단 이불 속으로 드니 그 운우의 즐거움은 비할 데가 없었다. 사흘 뒤 정후가 시댁으로 가려고 기주로 떠날 때, 수성장을 불러 성지를 잘 지키라 하고 위의를 갖추어 기주에 이르러 시부모를 뵙는 예를 행하니 태부인이 못내 칭찬하였다. 이럭저럭 여러 날이 지나자 장후가 황명에 따라 황성에 이르러 대궐에 나아가 사은하니, 황상이 불러 보시고 말씀하셨다. \"경이 정수정을 능히 제어하여 도리어 중군으로 삼았느냐. 짐이 경들의 소원을 이루어 주었으니 경도 짐의 뜻을 따르라. 정수정은 여자이니 공주로 경의 배필을 정하는 것이 마땅하다.\" 하시고 곧 흠천관에게 날을 가리라 하시니 이달 십삼일이었다. [?]","sp":[[66,68,"P","정수정"],[141,144,"P","양씨 부인"],[171,173,"P","장연"],[204,206,"P","천자"],[226,229,"P","정수정"],[243,245,"P","장연"],[288,291,"P","정수정"],[298,300,"P","공주"]]},{"c":1,"sub":"","t":"황상이 장연에게 칙지를 내리시어 혼례를 차리라 하셨다. 오래지 않아 길일이 되니, 장후가 혼례복을 갖추고 궐내로 들어가 공주와 혼례를 치른 뒤 천자께 사은하고 신방으로 나아갔다. 공주의 고운 자태가 사람의 눈을 어지럽게 하니 장후가 속으로 은근히 기뻐하였다. 사흘을 지낸 뒤 장후가 공주를 데리고 기주로 내려가는데, 붉은 치마 입은 시녀들은 쌍쌍이 늘어서고 이원의 풍악은 성대하여 하늘에 사무쳤다. 기주에 이르러 태부인께 폐백을 드리는 예를 행하고 사당에 배알한 뒤 침소로 돌아갔다.","sp":[[0,2,"P","천자"],[4,6,"P","장연"],[46,48,"P","장연"],[67,69,"P","공주"],[80,82,"P","천자"],[100,102,"P","공주"],[126,128,"P","장연"],[154,156,"P","장연"],[158,160,"P","공주"],[231,234,"P","양씨 부인"]]},{"c":1,"sub":"","t":"이날 해가 진 뒤 장후가 정후의 침소로 가니 정후가 맞이하여 자리를 정한 뒤 웃음을 머금고 말하였다. \"군후께서 공주를 맞아 신방의 부귀를 누리시니 재미가 어떠하십니까?\" 서로 이처럼 담소할 즈음 원부인이 공주와 함께 오므로, 정후가 일어나 맞이하여 자리를 정한 뒤 웃으며 말하였다. \"옥주께서 궁궐의 존귀하신 몸으로 누추한 곳에 오시니 자못 송구합니다.\" 공주가 겸손하게 말하였다. \"첩은 변변치 못한 사람으로 황명에 따라 이곳에 왔으니, 한평생의 고락이 군자와 원비 부인께 달렸으니 어찌 편치 않겠습니까. 첩이 궁중에 있을 때 정후의 재덕을 사모하였는데, 오늘 함께 군자를 섬기게 될 줄 어찌 뜻하였겠습니까.\" 정후도 겸손하게 사양하였다. 이렇게 세 부인이 이야기하다가 밤이 깊은 뒤 각각 흩어져 처소로 갔다. [?]","sp":[[10,12,"P","장연"],[14,16,"P","정수정"],[25,27,"P","정수정"],[63,65,"P","공주"],[110,113,"P","위씨"],[115,117,"P","공주"],[127,129,"P","정수정"],[160,162,"P","공주"],[200,202,"P","공주"],[297,299,"P","정수정"],[344,346,"P","정수정"]]},{"c":1,"sub":"","t":"이때는 봄 석 달 좋은 때였다. 정후가 시비들을 데리고 후원에 올라 봄 경치를 구경하다가 부용각에 이르니, 장후의 총애하는 첩 영춘이 부용각 연못가에 걸터앉아 발을 물에 담그고 무릎 위에 거문고를 얹어 곡조를 타고 있었는데, 정후를 보고도 조금도 일어나는 기색이 없었다. 정후가 크게 노하여 꾸짖었다. \"공후장상이라도 나를 감히 업신여기지 못하거늘 너 같은 천한 계집이 어찌 나를 보고 꿈쩍도 하지 않느냐.\" 하고 곧 돌아와 화관을 벗고 융복을 갖춘 뒤, 진시회를 불러 영춘을 잡아 오게 하여 대청 아래 꿇리고 꾸짖었다. \"네가 군후의 총애를 믿고 방자하여 주모를 업신여기니 그 죄는 머리를 베어 다른 사람을 징계할 만하나, 군후의 낯을 보아 조금 꾸짖는 데 그치노라.\" 하고 곤장 이십 대를 쳐서 내치고 침실로 돌아왔다. 이때 태부인은 정후가 거만한 것을 언짢게 여기던 차에 이 말을 듣고 크게 노하여 장후를 불러 말하였다. \"영춘이 비록 죄가 있으나 내가 신임하는 계집종이거늘, 정후가 나에게 여쭙지도 않고 마음대로 잡아다 벌을 주니 어찌 네가 집안을 다스리는 법도라 하겠느냐.\" 장후가 머리를 조아려 사죄하고 바깥채로 나와, 정후의 시비를 잡아다 죄를 따지며 정후의 죄로 맞으라 하고 곤장을 쳐서 내치니 정후가 몹시 불쾌하게 여겼다.","sp":[[18,20,"P","정수정"],[60,62,"P","장연"],[71,73,"P","영춘"],[126,128,"P","정수정"],[152,154,"P","정수정"],[255,258,"P","진시회"],[263,265,"P","영춘"],[408,411,"P","양씨 부인"],[413,415,"P","정수정"],[450,452,"P","장연"],[464,466,"P","영춘"],[494,496,"P","정수정"],[551,553,"P","장연"],[577,579,"P","정수정"],[596,598,"P","정수정"],[621,623,"P","정수정"]]},{"c":1,"sub":"","t":"앞서 황상이 맹동현을 어매 공주의 부마로 뽑으셨는데, 이때 맹공이 어매 공주와 혼인하고 장후의 집에 이르렀다. 장후가 반가이 맞아 술과 안주를 내어 즐기며 이야기하다가 밤이 깊은 뒤 안채로 들어가니, 세 부인이 정후의 침소에 모여 술을 가져다 놓고 서로 권하며 담소하고 있었다. 장후는 들어가지 않고 도로 바깥채로 나왔다. 이때 정후가 술이 취하자 공주와 원부인을 이끌고 영춘각에 올라 술을 깨려 하였다. 그때 영춘이 누각에서 달빛을 구경하다가 세 부인이 올라오는 것을 보고도 태연히 난간에 기대어 조금도 움직이지 않았다. 정후가 이를 보고 분노를 이기지 못하여 도로 침실로 돌아와 융복으로 갈아입고 바깥 대청에 나와 진시회에게 영춘을 잡아 오라 명하였다. 진시회가 군사를 시켜 영춘을 잡아다 꿇리니 정후가 크게 꾸짖었다. \"지난번에 너를 죽여야 마땅하였으나 내가 십분 용서하였거늘, 네가 끝내 업신여기니 어찌 통한하지 않겠느냐. [?]","sp":[[3,5,"P","천자"],[7,10,"P","맹동현"],[15,17,"P","공주"],[33,35,"P","맹동현"],[40,42,"P","공주"],[49,51,"P","장연"],[62,64,"P","장연"],[118,120,"P","정수정"],[156,158,"P","장연"],[184,186,"P","정수정"],[195,197,"P","공주"],[199,202,"P","위씨"],[208,210,"P","영춘"],[230,232,"P","영춘"],[293,295,"P","정수정"],[346,349,"P","진시회"],[352,354,"P","영춘"],[368,371,"P","진시회"],[380,382,"P","영춘"],[392,394,"P","정수정"]]},{"c":1,"sub":"","t":"이제 네 머리를 베어 간악하고 교활한 계집종들을 징계하겠다.\" 하고 무사에게 호령하여 영춘을 끌어내 베라 하였다. 이윽고 무사가 영춘의 머리를 바치자, 정후는 좌우를 시켜 집안에 돌려 보이게 하였다. 집안의 위아래 사람들이 크게 놀라 태부인께 아뢰니, 부인이 크게 놀라 곧 장후를 불러 크게 꾸짖었다. \"네 벼슬이 공후에 있으면서 여자 하나를 제어하지 못하니 어찌 세상에 행세하며 백성을 다스리겠느냐. 자식 된 몸이 어미가 신임하는 시비를 곤장 치는 것도 옳지 않거늘 하물며 목을 베는 데까지 이르렀으니, 이는 남에게 들려줄 수도 없는 일이로다.\" 장후가 관을 벗고 머리를 조아린 뒤 물러나와, 곧 정후가 신임하는 시비를 잡아다 무수히 곤욕을 주고 죽이려 하였으나, 공주와 위부인이 힘써 말려 그만두었다.","sp":[[48,50,"P","영춘"],[72,74,"P","영춘"],[85,87,"P","정수정"],[131,134,"P","양씨 부인"],[153,155,"P","장연"],[307,309,"P","장연"],[335,337,"P","정수정"],[373,375,"P","공주"],[377,380,"P","위씨"]]},{"c":1,"sub":"","t":"이후로 장후는 정후를 언짢게 여겨 멀리 대하는 일이 많았으나 정후는 조금도 개의치 않았다. 하루는 정후가 진시회를 불러 분부하였다. \"내가 이제 청주로 가려 하니 군마를 대령하라.\" 그러고는 정당에 들어가 태부인께 하직을 고하니 태부인이 물었다. \"네 어찌 까닭 없이 가려 하느냐?\" 정후가 말하였다. \"봉읍이 중대하고 이제 급한 일이 있어 돌아가려 합니다.\" 또 공주와 위부인과 작별하고 바깥 대청에 나와 위의를 갖추어 청주로 돌아왔다. 여러 장수와 군졸에게 상을 내리고, 또 군중에 영을 내려 무예를 연습하여 뜻밖의 변에 대비하게 하였다.","sp":[[4,6,"P","장연"],[8,10,"P","정수정"],[34,36,"P","정수정"],[55,57,"P","정수정"],[59,62,"P","진시회"],[115,118,"P","양씨 부인"],[128,131,"P","양씨 부인"],[159,161,"P","정수정"],[204,206,"P","공주"],[208,211,"P","위씨"]]},{"c":1,"sub":"","t":"한편 오랑캐 장수 철통골이 겨우 목숨을 보전하여 오랑캐 왕을 보고 패한 사유를 말하니, 오랑캐 왕이 소리 높여 통곡하며 원수 갚기를 맹세하고 문무 신하를 모아 의논하였다. 문득 한 장수가 반열에서 나와 아뢰었다. \"마웅은 신의 형입니다. 원컨대 신이 나가서 형의 원수를 갚고 태종의 머리를 베어 대왕 휘하에 바치겠습니다.\" 모두 보니 이는 거기총독 마원으로 지혜와 용맹을 겸비한 자였다. 오랑캐 왕이 크게 기뻐하여 마원을 대원수로 삼고 철통골을 선봉으로 삼아 정병 오만을 뽑아 출병하니, 몇 달 안에 하북 수십여 성의 항복을 받고 양성에 이르렀다.","sp":[[10,13,"P","철통골"],[27,32,"P","오랑캐 왕"],[49,54,"P","오랑캐 왕"],[120,122,"P","마웅"],[154,156,"P","천자"],[195,197,"P","마원"],[217,222,"P","오랑캐 왕"],[232,234,"P","마원"],[244,247,"P","철통골"]]},{"c":1,"sub":"","t":"양성 태수 범수홍이 크게 놀라 장계를 올리니, 황상이 크게 놀라 문무 신하를 모아 도적 막을 의논을 하셨다. 여러 신하가 아뢰었다. \"정수정이 아니면 대적할 자가 없을까 합니다.\" 황상이 말씀하셨다. \"전에는 수정이 여자로서 남자가 된 줄 모르고 전장에 보냈거니와, 이제 여자인 줄 알고서야 어찌 출전을 시키겠는가.\" 여러 신하가 아뢰었다. \"이 사람은 비록 여자이나 하늘이 폐하를 위하여 내신 사람이니, 폐하께서는 염려 마시고 그 사람을 보내소서.\" 황상이 마지못하여 사관을 청주로 보내 정후를 불러 말씀하셨다. \"이제 국운이 불행하여 북쪽 도적이 다시 배반하여 이러이러하였다 하니 형세가 급하다.","sp":[[6,9,"P","범수홍"],[26,28,"P","천자"],[75,78,"P","정수정"],[101,103,"P","천자"],[117,119,"P","정수정"],[253,255,"P","천자"],[274,276,"P","정수정"]]},{"c":1,"sub":"","t":"경은 수고를 아끼지 말고 도적을 깨뜨려 짐의 근심을 덜라.\" 하시고 곧 정수정을 정북대원수로 삼으시고 상방검을 주시며 말씀하셨다. \"문지방 밖의 일은 경이 마음대로 처치하라.\" 그리고 어주를 내리시니, 원수가 마지못하여 은혜에 사례한 뒤 청주로 돌아왔다. 각 도에 영을 내려 병기와 군량을 하북으로 실어 나르게 하고, 한복을 선봉으로, 용봉을 좌익장으로 삼고, 관영에게는 청주성을 지키게 하고, 본부 정병 이십만을 거느리고 그날로 행군하였다. 십여 일 만에 하북에 이르니 양성 태수 범수홍이 대군을 거느리고 원수를 맞아 군사를 합치고 적세를 살폈다. 며칠이 되지 않아 여러 도의 병마가 모두 이르니 갑병이 육십만이요 정병이 사십만이었다. 원수가 격서를 보내고 군사를 내어 적과 마주하여 진을 쳤다.","sp":[[40,43,"P","정수정"],[178,180,"P","한복"],[188,190,"P","용봉"],[202,204,"P","관영"],[270,273,"P","범수홍"]]},{"c":1,"sub":"","t":"한편 적장 마원이 승승장구하여 서울로 향하다가 문득 정 원수의 대군을 만나 한 번 바라보니, 정신이 아찔하여 감히 나아가지 못하고 여러 장수를 모아 의논하였다. \"정수정은 천하의 영웅이라 싸워서는 잡지 못할 것이다. 반드시 오늘 밤 자객 엄백수를 보내 수정의 머리를 베리라.\" 하고 곧 엄백수를 불러 천금을 주며 말하였다. \"네가 오늘 밤 송나라 진에 들어가 정수정의 머리를 베어 오면 천금의 상에 만호후를 봉하겠다.\" 엄백수가 흔쾌히 응낙하고, 이날 밤 비수를 끼고 몸을 날려 바람과 구름을 타고 송나라 진으로 향하였다.","sp":[[6,8,"P","마원"],[29,33,"P","정수정"],[91,94,"P","정수정"],[133,136,"P","엄백수"],[141,143,"P","정수정"],[160,163,"P","엄백수"],[201,204,"P","정수정"],[235,238,"P","엄백수"]]},{"c":1,"sub":"","t":"한편 원수는 한 계교를 생각하고 기주후 장연에게 영을 내렸다. \"군무에 긴급한 일이 있으니 며칠 안에 군량을 싣고 대령하되, 만일 기한을 어기면 군법을 행하겠다.\" 이날 밤 군중에 일이 없는 것을 마음에 괴이히 여겨 소매 속으로 점을 쳐 한 괘를 얻으니 처음은 흉하고 뒤는 길하였다. 곧 군중에 영을 내려 오늘 밤 장졸이 잠을 자지 말고 도적에 대비하라 하고, 홀로 책상에 기대어 앉아 있었다. 이때 엄백수가 칼을 끼고 송나라 진의 장대에 이르니 등촉이 휘황하고 인적이 고요하였다. 장막 틈으로 엿보니 정 원수가 갑주를 갖추고 장검을 안고 앉아 있는데, 엄숙한 기상과 늠름한 위풍이 사람의 정신을 아찔하게 하였다.","sp":[[18,21,"P","장연"],[22,24,"P","장연"],[224,227,"P","엄백수"],[281,285,"P","정수정"]]},{"c":1,"sub":"","t":"백수가 생각하기를, '이 사람은 정말 천신이니 내가 만일 해치려 했다가는 도리어 화를 당하리라.' 하고 스스로 칼을 던지고 대 아래 엎드려 사죄하였다. 원수가 놀라 물었다. \"너는 어떤 사람이기에 이 깊은 밤에 진중에 들어왔으며 무슨 일로 죄를 청하느냐?\" 백수가 머리를 조아리며 말하였다. \"소인은 본디 북방 사람인데, 오랑캐 장수 마원의 꾐에 넘어가 천금을 받고 원수 노야의 머리를 베러 왔습니다. 그런데 노야의 기상을 뵈니 천신이 호위하고 있어 감히 범하지 못하고 죄를 청합니다.\"","sp":[[0,2,"P","엄백수"],[144,146,"P","엄백수"],[187,189,"P","마원"]]},{"c":1,"sub":"","t":"원수가 다 듣고 말하였다. \"네가 이미 많은 값을 받고 위험한 곳에 들어왔다가 그냥 돌아가면, 반드시 그 값을 도로 물어내야 할 뿐 아니라 네 목숨까지 위태로울 것이니, 너는 내 머리를 베어 가지고 돌아가 공을 세우라.\" 백수가 더욱 황공하여 사죄하였다. \"소인이 이미 본심이 드러났고 노야께서 이같이 용서하시니, 그 은덕은 백골이 되어도 잊지 못하겠습니다.\" 원수가 좌우에 명하여 술과 안주를 가져다 너그러이 대접하고, 상자 안에서 황금 한 봉을 내어 주며 말하였다. \"이것을 가지고 네 고향으로 가서 생업을 삼고, 의롭지 못한 재물을 취하여 옳지 않은 일을 하지 않는 것이 어떠하냐.\" 백수가 감격과 은혜를 이기지 못하여 곧 하직하고 돌아갔다.","sp":[[124,126,"P","엄백수"],[330,332,"P","엄백수"]]},{"c":1,"sub":"","t":"한편 원수의 영이 기주에 이르니, 기주후 장연이 받아 보고 속으로 통탄함을 이기지 못하여 분연히 안채로 들어가 이 사유를 태부인께 아뢰었다. 부인도 분통하게 여겼다. 장후가 다시 생각하니 군령은 나라의 일이라, 마지못하여 태부인께 하직하고 하북으로 가면서 운량관을 불러 분부하였다. \"군량을 강물 길로 실어 날라 기한에 대게 하라.\" 그러고는 밤낮으로 길을 재촉하여 갔다. 앞서 자객 엄백수는 오랑캐 진영으로 돌아가 마원을 보고 말하였다. \"송나라 진에 들어가 보니 좌우에 범 같은 장수가 옹위하고 있어 감히 손을 쓰지 못하였소.\" 마원이 말하였다. \"그렇다면 내일 다시 가서 틈을 보아 일을 이루라.\" 백수는 한 꾀를 생각하고 거짓으로 응낙한 뒤 장막 뒤에서 쉬었다. 이때 마원이 밤이 깊어 홀로 장막 안에서 깊이 잠들자, 백수가 가만히 들어가 마원의 머리를 베어 가지고 송나라 진으로 가서 원수에게 바쳤다. 원수가 놀라는 한편 기뻐하여 다시 천금을 주어 보냈다.","sp":[[19,22,"P","장연"],[23,25,"P","장연"],[68,71,"P","양씨 부인"],[93,95,"P","장연"],[124,127,"P","양씨 부인"],[215,218,"P","엄백수"],[233,235,"P","마원"],[298,300,"P","마원"],[338,340,"P","엄백수"],[378,380,"P","마원"],[406,408,"P","엄백수"],[418,420,"P","마원"]]},{"c":1,"sub":"","t":"이때 군사가 아뢰기를, 기주후 장연이 본부 군사를 거느리고 성 아래에 진을 쳤으나 군량은 아직 이르지 못하였다 하였다. 원수는 속으로 반가웠으나 짐짓 속이려고 군량이 이르지 못한 것을 꾸짖었다. \"군대(軍旅)가 움직일 때 양식을 먼저 챙기는 것이 장수 된 자의 직책이거늘 어찌하여 군량을 대지 못하였느냐.\" 그러고는 장연에게 죄를 기록하여 우선 죄를 지닌 채 직무를 행하라 하였다. 이튿날 적장 마원의 머리를 진문에 높이 달고 말하였다. \"우리 군졸이 털끝만 한 힘도 들이지 않고 적장의 머리를 취하여 왔으니 여러 장수와 군졸은 자세히 보라.\" 모두 크게 놀라 얼굴빛이 변하며 무슨 곡절인지 몰라 의아해하였다.","sp":[[13,16,"P","장연"],[17,19,"P","장연"],[177,179,"P","장연"],[221,223,"P","마원"]]},{"c":1,"sub":"","t":"한편 적장 철통골이 장막 안에 들어가 마원을 보고 일을 의논하려 하는데, 마원이 자리에 누워 꼼짝도 하지 않았다. 괴이히 여겨 자세히 보니 마원의 머리는 간데없고 피가 낭자하였다. 크게 놀라 사실을 캐어 보고 또 자객 엄백수를 찾았으나 간 곳이 없었다. 온 군중이 허둥지둥 어쩔 줄 몰라 정신을 잃었다. 철통골이 칼을 들고 외쳤다. \"만일 동요하는 자가 있으면 베겠다.\" 그러고는 마원의 시신을 거두어 염하여 빈소를 차리고, 군마를 나누어 진을 친 뒤 이 사연을 본국에 알려 구원병을 청하였다.","sp":[[6,9,"P","철통골"],[21,23,"P","마원"],[41,43,"P","마원"],[78,80,"P","마원"],[122,125,"P","엄백수"],[170,173,"P","철통골"],[213,215,"P","마원"]]},{"c":1,"sub":"","t":"이때 정 원수는 각 도의 병마를 통합하여 네 부대로 나누어 배치하고 여러 장수와 의논하였다. \"이제 적진에 주장이 없으니 오늘 밤 기습할 만하다.\" 여러 장수와 약속하고 황혼에 군사를 먹인 뒤, 이경에 북을 쳐 급히 군사를 지휘해 나가 적진을 에워쌌다. 적진 장졸이 뜻밖의 변을 당하여 손쓸 겨를도 없이 모두 사로잡히고, 남은 군사는 사방으로 흩어져 목숨을 건져 달아났다. 이때 철통골도 필마로 도주하여 본국으로 가서 오랑캐 왕을 보고 울며 아뢰었다. \"마원이 한 번 나가 싸워 보지도 못하고 요사한 자객에게 도리어 죽임을 당하여 뜻밖의 변을 만나 패하였습니다. 바라건대 대왕께서 다시 정병 오천만 주시면 소신이 나가 정수정을 베어 마원의 원수를 갚고 송나라 황제를 사로잡아 대왕께 바치겠습니다.\" 오랑캐 왕이 크게 놀라 말하였다. \"두 차례 출병에 애꿎은 장졸만 죽이고 아이 같은 정수정 하나를 잡지 못하니 어찌 통분하지 않겠는가.\" 하며","sp":[[3,7,"P","정수정"],[212,215,"P","철통골"],[234,239,"P","오랑캐 왕"],[254,256,"P","마원"],[346,349,"P","정수정"],[354,356,"P","마원"],[391,396,"P","오랑캐 왕"],[438,441,"P","정수정"]]},{"c":1,"sub":"","t":"좌우를 불러 말하였다. \"누가 능히 나를 위하여 이 한을 풀어 주겠는가.\" 말이 끝나기도 전에 계단 아래에서 한 사람이 반열에서 나와 아뢰었다. \"듣자니 정수정은 나이는 비록 어리나 지혜와 용맹이 천신 같아 갑자기 잡을 수는 없고, 두 번 싸움에 애꿎은 장졸만 죽였으니, 이로 보면 힘으로는 당해 내지 못할까 합니다. 신에게 한 계교가 있습니다. 남만의 가달왕은 대왕과 대대로 사귀어 온 의리가 있으니, 원컨대 대왕께서 국서를 보내 군사를 빌려 곧바로 남경을 치게 하시면 송나라 황제의 항복을 받기가 어렵지 않을 것입니다. 그렇게 되면 정수정이 아무리 하늘을 찌를 재주가 있은들 두 곳의 군마를 어찌 막아 내겠습니까.\"","sp":[[86,89,"P","정수정"],[198,201,"P","가달왕"],[300,303,"P","정수정"]]},{"c":1,"sub":"","t":"오랑캐 왕이 듣고 크게 기뻐하여, 철통골에게 정병 삼만을 거느리고 다시 나가 정수정과 대치하되 경솔히 싸우지 말고 날짜만 끌다가 남경 소식을 들은 뒤에 교전하라 하였다. 또 아문장 호철에게 국서를 지니고 밤낮으로 달려 가달국으로 가게 하였다. 이때 원수는 적진을 에워싸고 철통골마저 잡으려고 사방을 수탐하였으나 간 곳을 몰라 의아해하였다. 며칠 뒤 철통골이 정병 삼만과 맹장 수백을 거느리고 와서 진을 마주하였다. 원수가 한복에게 나가 싸우게 하니, 한 합도 되기 전에 철통골이 달아났다.","sp":[[0,5,"P","오랑캐 왕"],[19,22,"P","철통골"],[43,46,"P","정수정"],[101,103,"P","나호철"],[152,155,"P","철통골"],[195,198,"P","철통골"],[236,238,"P","한복"],[263,266,"P","철통골"]]},{"c":1,"sub":"","t":"한복이 쫓다가 잡지 못하고 본진으로 돌아왔는데, 이튿날 철통골이 또 와서 싸움을 돋우었다. 한복이 또 말을 채쳐 나가니 철통골이 또 달아났다. 원수가 이것을 보고 한복에게 일렀다. \"적장이 연일 싸우지도 않고 물러가는 것을 보니 그 가운데 필경 간사한 꾀가 있다. 이후로는 조심하라.\" 서로 대치한 지 한 달이 넘도록 승부를 가리지 못하여 근심하던 중, 하루는 원수가 친히 나가 싸우려 하였으나 철통골이 진문을 굳게 닫고 나오지 않았다.","sp":[[0,2,"P","한복"],[31,34,"P","철통골"],[51,53,"P","한복"],[67,70,"P","철통골"],[91,93,"P","한복"],[221,224,"P","철통골"]]},{"c":1,"sub":"","t":"원수는 더욱 의심이 나서 사면에 군사를 매복하고 틈만 기다렸다. 이처럼 서로 대치한 지 어느덧 몇 달이 되도록 승부를 가리지 못하여 원수는 밤낮으로 도적 깨뜨릴 계교를 생각하였다. 하루는 정탐병이 아뢰기를, 적장이 깊은 밤중에 진을 물려 달아났다 하였다. 원수가 듣고 이제야 적장이 겁먹은 줄 알고 삼군을 지휘하여 뒤를 쫓으려 하였다. 먼저 큰 잔치를 베풀고 소와 양을 잡아 장졸을 먹이고, 원수도 술을 연이어 내어 여러 장수와 함께 마셨다. 취흥이 한창 오르자 별안간 좌우에 호령하여 기주후 장연을 잡아들이라 하였다. 무사들이 쇠사슬로 장연의 목을 얽어 장대 아래 이르렀는데, 장연이 꿇지 않고 서 있었다. 원수가 크게 노하여 말하였다. \"이제 도적이 국경을 침노하여 황상께서 근심하시고 나에게 도적을 막으라 하셨다. 내가 황명을 받들어 밤낮 애를 쓰거늘, 그대는 나라의 녹을 먹는 신하로서 어찌하여 막중한 군무에 군량을 제때 대령하지 않아 군사들이 굶주림을 면치 못하게 하였느냐. 장수의 영을 어겼으니 군법에는 사정이 없다. 그대는 나를","sp":[[272,275,"P","장연"],[276,278,"P","장연"],[301,303,"P","장연"],[324,326,"P","장연"],[375,377,"P","천자"]]},{"c":1,"sub":"","t":"원망하지 마라.\" 하고 무사에게 명하여 끌어내 베라 하였다. 장후도 노하여 말하였다. \"내가 비록 용렬하나 그대의 지아비가 되거늘, 사소한 혐의로 군법을 핑계 삼아 지아비를 이같이 곤욕을 주니 어찌 여자의 도리라 하겠소.\" 하며 끝내 항거하였다. 원수는 장후의 거동을 보고 속으로는 웃음이 나왔으나 기어이 항복을 받으려고 겉모습을 더욱 엄숙히 하고 짐짓 꾸짖었다. \"그대가 사람을 모르는도다. 부부의 도는 집에 있을 때의 사사로운 일이요, 이 일은 국가의 대사라. 신하 된 자가 나랏일을 먼저 하고 집안일은 뒤에 하는 것이 떳떳하거늘 어찌 사정으로 국법을 그르치겠는가.","sp":[[34,36,"P","장연"],[142,144,"P","장연"]]},{"c":1,"sub":"","t":"내가 국가의 중임을 맡아 도성 밖의 일(梱以外)은 내 손안에 있을 뿐 아니라, 천자께서 주신 검과 인(劍印)이 여기 있다. 그대가 이미 법을 범하였으니 어찌 부부의 도를 지켜 국법을 어지럽히겠으며, 그대가 비록 나를 믿는다 한들 어찌 내 마음대로 용서하겠는가.\" 하고 무사를 재촉하여 속히 거행하라 하였다. 장후는 이에 이르러서는 대답할 말도 없이 고개만 숙이고 있다가 다시 말하였다. \"군량을 뭍길로 실어 나르지 못하고 강물 길로 나르다가 순풍을 만나지 못하여 이처럼 늦어졌으니 어찌 죄라 하겠소.\" 여러 장수도 사세가 그러했을 것이라며 극진히 간하자, 원수가 한참 뒤 마지못하여 말하였다. \"여럿의 낯을 보아 용서하나 그냥 둘 수는 없다.\" 하고 무사에게 명하여 곤장을 치라 하였다. 장후는 분한 마음이 하늘을 찌를 듯하였으나, 이 자리에서는 아무리 발악해도 쓸데없을 줄 알고 부드러운 말로 말하였다.","sp":[[44,46,"P","천자"],[172,174,"P","장연"],[385,387,"P","장연"]]},{"c":1,"sub":"","t":"\"이미 잘못된 일을 한 번만 용서하면 이후로는 착실히 거행하겠소.\" 원수가 짐짓 말하였다. \"그러나 한번 내린 영을 거둘 수는 없다.\" 하고 졸병을 시켜 냉수를 가져오게 하여 말하였다. \"곤장 대신에 냉수 벌주를 들이켜라.\" 장후는 할 수 없이 냉수를 동이째 들고 벌떡벌떡 들이켰다. 원수는 속으로 웃고 무사에게 명하여 군문 밖으로 내쳤다. 이때 장후는 분을 이기지 못하여 본부 군중으로 돌아와 병을 핑계 대고 다시는 장수의 영을 받으러 들어가지 않았다. 원수가 장차 철통골을 쫓아 오랑캐 나라로 향하려 하면서 장연을 전군대장으로 삼아 속히 길을 떠나라는 영이 엄하니, 장후는 마지못하여 군마를 수습하여 떠났다. 한편 호철은 오랑캐 왕의 국서를 가지고 밤낮으로 달려 남만 가달국에 이르러 국왕을 보고 울며 국서를 올리며 말하였다. \"송나라 황제가 정수정에게 정병 수십만을 거느리고 저희 나라를 침범하게 하니 그 기세를 당할 수 없고, 정수정은 또한 천하의 명장이라","sp":[[126,128,"P","장연"],[194,196,"P","장연"],[262,265,"P","철통골"],[286,288,"P","장연"],[319,321,"P","장연"],[346,348,"P","나호철"],[350,355,"P","오랑캐 왕"],[418,421,"P","정수정"],[467,470,"P","정수정"]]},{"c":1,"sub":"","t":"마웅과 마원이 다 그 손에 죽어 나라의 위태로움이 아침저녁에 있습니다. 바라건대 대왕께서는 옛 의리를 생각하시어 한 부대의 군사를 일으켜 남경을 치시면, 첫째는 그 기세를 나누니 저희 나라가 보전될 것이요, 둘째는 남경에 장졸이 없어 빈 때이니 단번에 송나라 황제를 사로잡을 것입니다. 그렇지 않으면 저희 나라가 망하여 입술이 없어지면 이가 시린 화를 면치 못할 것이니, 원컨대 대왕께서는 이 기회를 살피소서.\" 이때 가달왕이 국서를 보고 또 호철의 말을 들으니 그냥 물리치기 어려웠다. [?]","sp":[[0,2,"P","마웅"],[4,6,"P","마원"],[234,237,"P","가달왕"],[248,250,"P","나호철"]]},{"c":1,"sub":"","t":"곧 답서를 써서 호철을 돌려보내고, 정병 이십만을 뽑아 왕골대를 선봉으로 삼고 남만 왕이 스스로 대장이 되어 거침없이 쳐들어오니, 지나는 고을마다 소문만 듣고 항복하여 감히 막는 자가 없었다. 여러 날 만에 철남관에 이르러 웅거하니, 이때 백성들은 난리를 겪어 보지 못하다가 뜻밖에 난리를 당하여 울부짖는 소리가 천지를 뒤흔들고, 산과 들을 덮으며 피란하는 모습에 천지가 참담하였다. [?]","sp":[[9,11,"P","나호철"],[31,34,"P","왕골대"],[44,48,"P","가달왕"]]},{"c":1,"sub":"","t":"이때 천자는 정수정을 북쪽 땅에 보내시고 승부를 몰라 밤낮 잠을 이루지 못하고 근심하시던 중, 뜻밖에 철남관 수문장이 장계를 올렸다. 급히 뜯어보니, 남만의 가달왕이 배반하여 대병을 거느리고 물밀듯 남관 백 리 들에 가득히 들어오며, 지나는 곳마다 노략이 심하고 황성을 범하려 하니 바삐 군병을 뽑아 막으소서 하였다. 천자가 보시고 크게 놀라 얼굴빛이 변하시어, 곧 조정 신하를 모아 의논하셨다. \"북쪽 도적을 평정하지 못하였는데 또 남쪽 도적이 이렇게 강성하여 위급함이 시각에 달렸으니 어찌하면 좋겠는가.\" 여러 신하가 다 묵묵히 대답이 없으므로 천자가 탄식하셨다. \"정수정이 비록 여자이나 충성과 힘을 다하여 나라를 돕더니, 불행히 만 리 북쪽 변방에 출전하여 아직 돌아오지 않았는데 또 이런 변이 있으니, 이는 하늘이 나를 망하게 하는 것이로다.\" 하시며 병부상서 맹동현에게 군사를 뽑게 하시고 친히 군사를 거느려 친정하시니, 군사가 이십만이요 장수가 백여 명이었다.","sp":[[3,5,"P","천자"],[7,10,"P","정수정"],[88,91,"P","가달왕"],[178,180,"P","천자"],[307,309,"P","천자"],[319,322,"P","정수정"],[431,434,"P","맹동현"]]},{"c":1,"sub":"","t":"이때 거기장군 양성초가 진문 밖에 엎드려 아뢰었다. \"소신이 비록 재주가 없으나 이때를 당하여 신하 된 도리에 어찌 앉아서 큰일을 보기만 하겠습니까. 소신에게 선봉을 주시면 한번 나가서 도적을 막겠습니다.\" 황상이 크게 기뻐하시어 곧 양성초를 선봉으로, 맹동현을 대장으로 삼고 황상 스스로 후군이 되어 행군을 재촉하시니, 깃발과 창검은 해와 달을 가리고 북과 나팔과 함성에 산천이 움직였다. 여러 날 만에 양성 땅에 이르니 적진이 벌써 쳐들어오는데, 의기양양하고 호령이 엄숙하였다. 깃발과 창검은 팔봉산 초목이 움직이는 듯하고, 투구와 갑주의 눈부신 빛은 햇빛을 쏘는 듯하며, 고함 소리는 강산이 뒤끓는 듯하였다. 순식간에 평평한 모래벌판 백 리 들에 빈틈없이 늘어서서 음양진을 치고 싸움을 재촉하였다. 적진 가운데서 포 소리가 한 번 울리며 한 장수가 내달아 외쳤다. \"송나라 진중에 낙타를 당할 장수가 있거든 빨리 나와 대적하라.\"","sp":[[8,11,"P","양성초"],[116,118,"P","천자"],[131,134,"P","양성초"],[142,145,"P","맹동현"],[155,157,"P","천자"]]},{"c":1,"sub":"","t":"송나라 진중에서 포를 쏘아 응하고 좌익장 주성태가 내달아 크게 외쳤다. \"무지한 오랑캐가 하늘의 때를 모르고 국경을 범하는구나.\" 하며 창을 바로 들고 말을 몰아 나가 싸웠다. 십여 합에 이르러 낙타의 말이 엎어지며 낙타가 땅에 떨어졌다. 주성태가 창을 들어 찌르려 할 즈음 적진 가운데서 한 떼의 군마가 내달아 구해 갔다. 성태가 분함을 이기지 못하여 따라가다가 적진에서 화살과 돌이 비 오듯 하므로 말을 돌려 본진으로 돌아왔다. 이튿날 낙타가 진 앞에 나와 크게 외쳤다. \"어제 싸움에서 결판을 내지 못한 장수는 나와 내 칼을 받으라.\" 하며 진 앞에서 동서로 말을 달리며 방약무인하였다. 주성태가 분노하여 말을 채쳐 나오며 꾸짖었다. \"어제 싸움에 너를 벨 것이로되 네 목에 내 칼을 대기가 더러워 살려 보냈거늘, 하룻강아지 범 무서운 줄 모르고 또 감히 나와 어른과 겨루려 하느냐. 너는 내 적수가 아니니 빨리 돌아가고 너의 왕더러 나와 내 칼을 받으라 하여라.\"","sp":[]},{"c":1,"sub":"","t":"낙타가 웃으며 말하였다. \"어제는 내 말이 약하여 실수를 해서 너에게 웃음거리가 되었을 뿐이요 내 재주가 부족한 것이 아니다.\" 하고 칼을 춤추며 달려들었다. 주성태가 맞아 싸웠는데, 세 합이 못 되어 크게 한 번 소리치며 성태의 칼이 번뜩하자 낙타의 머리가 칼빛을 따라 떨어졌다. 성태가 낙타의 머리를 칼끝에 꿰어 들고 좌충우돌하였다. 이때 적장 왕골대가 낙타의 죽음을 보고 분을 참지 못하여 큰 칼을 들고 나는 듯이 말을 채쳐 나와 우레 같은 소리를 지르며 달려들었다.","sp":[[195,198,"P","왕골대"]]},{"c":1,"sub":"","t":"모두 보니 키가 구 척이요 얼굴빛은 먹물을 끼얹은 듯하고 눈빛은 불빛 같으며 위풍이 늠름하였다. 성태가 한 번 바라보자 정신이 어지러워 감히 싸울 마음이 없어 머뭇거릴 즈음, 크게 한 번 꾸짖는 소리와 함께 적장의 칼빛이 번뜩하며 성태의 목이 떨어졌다. 왕골대가 성태의 머리를 베어 들고 곧장 송나라 진으로 달려들며 크게 외쳤다. \"송나라 황제는 애꿎은 장졸만 죽이지 말고 빨리 항복하라.\" 그 소리에 천지가 진동하였다. 송나라 진의 장졸이 이 거동을 보고 간담이 떨어져 서로 쳐다보기만 하고 감히 나가 싸울 자가 없었다.","sp":[[142,145,"P","왕골대"]]},{"c":1,"sub":"","t":"천자가 하늘을 우러러 탄식하셨다. \"군사가 수십만이요 장수가 수백이로되 적장 하나를 나가 당할 자가 없으니 어찌 슬프지 않겠는가.\" 하시며 임금의 눈물이 흘러 용포 소매를 적셨다. 이때 선봉장 양성초가 장대 아래 모시고 있다가 황상이 눈물을 흘리시는 것을 보고 엎드려 아뢰었다. \"신이 한번 나가 적장의 머리를 베어 장대 아래 바치겠습니다.\" 황상이 말씀하셨다. \"경이 비록 용맹하나 왕골대는 범 같은 장수이니 가볍게 여기지 마라.\" 이때 진문 밖이 요란하며 군사가 아뢰기를, 적장 왕골대가 진문을 헤치고 들어온다 하였다. 선봉장 양성초가 분함을 이기지 못하여 창을 바로 들고 말을 몰아 나가 맞아 싸우다가, 한 합도 못 되어 적장에게 사로잡혀 갔다. 진중의 여러 장수가 이를 보고 더욱 겁에 질려 정신을 차리지 못하였다.","sp":[[0,2,"P","천자"],[108,111,"P","양성초"],[127,129,"P","천자"],[192,194,"P","천자"],[215,218,"P","왕골대"],[270,273,"P","왕골대"],[297,300,"P","양성초"]]},{"c":1,"sub":"","t":"황상이 더욱 놀라시어 맹동현을 돌아보며 말씀하셨다. \"짐이 덕이 없어 이런 뜻밖의 변을 만나 애꿎은 신민과 장졸만 죽이니 어찌 망극하지 않겠는가. 양성초는 정수정의 외종형인데 적국에 잡혀가 생사를 모르니, 이다음에 정수정이 돌아오면 무슨 면목으로 대하겠는가. 차라리 내가 먼저 죽어 온 나라 신민을 화에서 면하게 하는 것이 옳다.\" 하시고 칼을 들어 스스로 목을 찌르려 하셨다. 맹동현이 급히 임금의 손을 붙잡고 울며 간하였다. \"이제 적세가 매우 크고 또 적장을 당할 장수가 없사오니, 엎드려 바라건대 폐하께서는 우선 금산성으로 피하여 계시고, 한편으로 정수정을 불러 적국을 깨뜨리게 하는 것이 좋을까 합니다.\"","sp":[[0,2,"P","천자"],[12,15,"P","맹동현"],[82,85,"P","양성초"],[87,90,"P","정수정"],[120,123,"P","정수정"],[212,215,"P","맹동현"],[311,314,"P","정수정"]]},{"c":1,"sub":"","t":"황상이 그 말을 옳게 여기시어 가만히 금산성으로 가려 할 즈음, 군사가 아뢰기를 하남 절도사 조충국이 정병 십만을 거느리고 진문 밖에 대령하여 군례로 뵙겠다 하였다. 황상이 반기시어 급히 불러 보신 뒤 충국을 곧 선봉으로 삼아 도적을 막으라 하시고, 가만히 여러 신하를 데리고 금산성으로 들어가 성문을 굳게 닫고 정수정이 돌아오기만 기다리셨다.","sp":[[0,2,"P","천자"],[52,55,"P","조충국"],[93,95,"P","천자"],[175,178,"P","정수정"]]},{"c":1,"sub":"","t":"이때 남만 왕이 양성초를 사로잡았다는 말을 듣고 항복을 받으려고 잡아들여 꿇리니, 양성초가 꿇지 않고 눈을 부릅뜨고 크게 꾸짖었다. \"무도하고 개 같은 오랑캐에게 내가 어찌 무릎을 꿇겠느냐.\" 남만 왕이 말하였다. \"그러면 너는 어찌하여 잡혀 왔느냐?\" 성초가 소리를 높여 말하였다. \"너희 무리가 강성함을 믿고 천조를 범하기에 내가 황명을 받들어 너희를 무찌르려다가 너희 놈들의 흉계에 빠져 이런 욕은 볼망정 어찌 두려움이 있겠느냐. 죽어서라도 너희 놈들의 씨를 없애고야 말겠다.\" 남만 왕이 말하였다. \"내가 지금 너를 풀어 살려 줄 것이니 너는 내 말을 듣겠느냐?\" 성초가 더욱 소리를 크게 하여 말하였다. \"지금 묶인 것을 풀 지경이면 한 주먹에 네 목숨이 없어질 것이니 그런 생각은 하지도 말고 어서 죽여 주기만 바란다.\" 하고 땅에 몸을 부딪쳐 죽으려 하였다. 남만 왕이 그 충심을 장하게 여겨 죽이지 않고, 우선 가두었다가 송나라 황제를 잡은 뒤 함께 처치하리라 하고 토굴을 파서 가두어 두었다.","sp":[[3,7,"P","가달왕"],[9,12,"P","양성초"],[46,49,"P","양성초"],[108,112,"P","가달왕"],[271,275,"P","가달왕"],[432,436,"P","가달왕"]]},{"c":1,"sub":"","t":"이때 진량은 강서로 귀양 가 있다가 정수정이 평북대원수로 출정하였다는 말을 듣고 크게 놀라 스스로 생각하였다. '수정이 공을 이루고 돌아오는 날이면 필경 그 손에 죽기를 면치 못할 것이다. 남자가 세상에 나서 이름을 백세에 꽃답게 남기지 못할 바에는 차라리 더러운 이름을 만년에 남기라 하였다. 지금 들으니 남만의 가달왕이 배반하여 남경을 침범하는데 그 형세를 당할 자가 없다 하니, 내가 반드시 그리로 가서 붙좇아 함께 일을 이룬 뒤 정수정을 먼저 죽여 한을 풀리라.' 하고 곧 깊은 밤중에 도망하여 남관에 이르러, 글 한 장을 써서 남만 군졸을 시켜 남만 왕께 올렸다. 그 글은 이러하였다. \"남경의 전 예부상서 진량은 백 번 절하고 머리를 조아려 한 장의 서간을 가달국 대왕 전하께 올립니다.","sp":[[3,5,"P","진량"],[20,23,"P","정수정"],[63,65,"P","정수정"],[176,179,"P","가달왕"],[244,247,"P","정수정"],[310,314,"P","가달왕"],[340,347,"P","진량"]]},{"c":1,"sub":"","t":"진량은 본디 송나라 대대로 녹을 먹던 신하로서 벼슬이 예부상서에 있으며, 임금을 충성을 다해 섬기고 백성을 은혜로 다스려 나라의 은혜를 한마음으로 갚고자 하였습니다. 그런데 천만뜻밖에 어리석은 임금이 정수정의 간사한 모함을 곧이듣고 진량을 먼 땅으로 내치니 어찌 통분하지 않겠습니까. 정수정은 나이 어린 아이일 뿐 아니라 남자도 아니요, 한낱 여자의 몸으로 남녀를 바꾸고 어두운 임금을 속여 벼슬이 일품에 올라 나라의 권세를 희롱하니, 그 나라 정치는 알 만합니다. 또 생각하면 대장부로서 한낱 여자의 손에 귀양을 당하였으니 어찌 통분하지 않겠습니까. 원컨대 대왕께서 진량의 소원을 받아들여 종군하게 해 주시면, 한 팔의 힘을 보태어 남경을 깨뜨려 위로는 대왕의 은혜를 갚고 아래로는 정수정에게 원수를 갚고자 합니다.\" 남만 왕이 그 글을 보고 크게 기뻐하여 곧 진량을 불렀다. 진량이 진중으로 들어가 장대 아래에서 절하고 엎드리니, 남만 왕이 일으켜 앉히고 송나라 진의 허실을 자세히 물은 뒤 군중 종사로 삼았다.","sp":[[0,2,"P","진량"],[112,115,"P","정수정"],[130,132,"P","진량"],[159,162,"P","정수정"],[318,320,"P","진량"],[383,386,"P","정수정"],[403,407,"P","가달왕"],[427,429,"P","진량"],[436,438,"P","진량"],[467,471,"P","가달왕"]]},{"c":1,"sub":"","t":"이때 왕골대는 양성초를 사로잡아 토굴에 가두고 의기양양하여 송나라 황제까지 잡으려고 군사를 지휘하여 송나라 진을 에워싸고 크게 외쳤다. \"송나라 황제는 애꿎은 장졸을 죽이지 말고 빨리 나와 항서를 바치라.\" 하며 진 앞에서 좌충우돌하였다. 하남 절도사 조충국이 이를 보고 분함을 참지 못하여 진문을 크게 열고 창을 바로 들고 말을 몰아 나가 왕골대와 싸웠는데, 세 합이 못 되어 적장의 칼빛이 번뜩하며 충국의 머리가 말 아래로 떨어졌다. 왕골대가 그 머리를 칼끝에 꿰어 들고 송나라 진을 헤치며 달려들어 들이치니, 온몸이 칼빛이 되어 닿는 곳마다 장졸의 머리가 가을바람에 지는 낙엽 같았다.","sp":[[3,6,"P","왕골대"],[8,11,"P","양성초"],[141,144,"P","조충국"],[191,194,"P","왕골대"],[245,248,"P","왕골대"]]},{"c":1,"sub":"","t":"순식간에 온 진의 장졸을 짓쳐 버리고 송나라 황제를 찾았으나 간 곳이 없었다. 군사 하나를 잡아 따져 물으니, 황상은 백관을 데리고 금산성으로 가셨다 하였다. 왕골대가 다시 군사를 몰아 금산성에 이르러 사면을 철통같이 에워싸고 크게 외쳤다. \"송나라 황제는 빨리 항복하라.\" 그 소리에 금산성이 무너지고 강산이 끓는 듯하여, 성안에 있는 사람들은 혼백이 떨어질 듯하였다. 이때 천자가 여러 신하와 도적 막을 의논을 하시다가 도적이 성을 에워싼 것을 보고 크게 놀라 얼굴빛이 변하시어 맹동현을 돌아보며 통곡하셨다. \"안에는 어진 장수가 없고 밖으로는 구원병이 없으니, 선황제께서 여러 해 이어 오신 종사가 오늘 나에게 와서 끝날 줄 어찌 알았겠는가.\" 하시며 눈물이 비 오듯 하셨다. 맹동현이 아뢰었다. \"폐하께서는 너무 근심하지 마소서. 이 성곽이 튼튼하고 장졸이 아직도 많으니 굳게 지키며 정수정이 올 때만 기다리십시다.\"","sp":[[62,64,"P","천자"],[89,92,"P","왕골대"],[211,213,"P","천자"],[270,273,"P","맹동현"],[382,385,"P","맹동현"],[443,446,"P","정수정"]]},{"c":1,"sub":"","t":"그 말이 끝나기도 전에 반열 가운데서 한 장수가 내달아 말하였다. \"장군의 말이 그르오. 도적이 성에 이르렀는데 어찌 싸우지 않고 바깥 군사만 기다리겠소. 소장이 비록 용렬하나 한번 나가 적장의 목을 베어다 장대 아래 바치겠소.\" 모두 보니 아문장 황흠이었다. 맹동현이 말하였다. \"그대의 재주가 비록 용맹하나 적장은 범 같은 장수라, 만일 당하지 못하면 대국에 수치만 될까 두렵소.\" 황흠이 더욱 성을 내어 말하였다. \"장군께서 병권을 쥐고 이같이 약한 모습을 보이시니 어찌 진에 나가 적국을 대하겠소.\" 하며 분연히 필마단창으로 나가려 하였다. 맹동현이 말리지 못하여 철기 삼천을 주어 성문을 열고 보내며 말하였다. \"그대의 충성과 용맹은 알 만하거니와 부디 남을 쉽게 여기지 말고 신중히 행하라.\" 황흠이 대답하고 삼천 군을 거느리고 성 밖에 나가 진을 치고 적장을 기다렸다.","sp":[[139,141,"P","황흠"],[146,149,"P","맹동현"],[216,218,"P","황흠"],[307,310,"P","맹동현"],[394,396,"P","황흠"]]},{"c":1,"sub":"","t":"이때 왕골대는 금산성을 곧 무찌르고 송나라 황제를 잡고 싶었으나, 그곳 성곽이 견고하고 군사가 굳게 지키며 나오지 않을 뿐 아니라 성 위에서 화살과 돌이 비 오듯 하여 가까이 갈 수 없었다. 아직 깨뜨릴 계교가 없어 군사를 조금 물려 진을 치고 틈만 보고 있었는데, 하루는 정탐병이 아뢰기를, 송나라 진에서 한 장수가 나와 성 아래 진을 치고 싸움을 돋운다 하였다. 왕골대가 크게 기뻐하여 사람을 놓아 알아보니 송나라 진의 아문장 황흠이라 하였다. 왕골대가 웃으며 말하였다. \"황흠은 송나라 진의 이름 없는 하급 장수인데 내가 어찌 몸소 대적하겠는가.\" 하고 종사 진량을 불러 말하였다. \"그대는 송나라 사람이니","sp":[[3,6,"P","왕골대"],[205,208,"P","왕골대"],[241,243,"P","황흠"],[251,254,"P","왕골대"],[267,269,"P","황흠"],[316,318,"P","진량"]]},{"c":1,"sub":"","t":"황흠을 응당 알 것이다. 나를 위하여 진 앞에 나가 황흠을 보고 이러이러하게 일러라. 공연히 군사만 죽이지 말고 송나라 황제가 속히 항복하여 목숨을 보전하게 하되, 만일 머뭇거리면 내가 반드시 성을 무찔러 씨도 남기지 않을 것이니 후회가 없게 하라고 일러라.\" 진량이 마지못하여 말을 타고 진문 밖에 나가 외쳤다. \"황흠은 나를 아느냐. 나는 본디 두 마음을 두지 않고 임금을 섬기려 하였는데, 송나라 황제가 어리석어 요사한 계집 정수정의 말을 듣고 죄 없는 나를 먼 땅으로 내치니 어찌 통분하지 않겠느냐.","sp":[[0,2,"P","황흠"],[29,31,"P","황흠"],[146,148,"P","진량"],[177,179,"P","황흠"],[241,244,"P","정수정"]]},{"c":1,"sub":"","t":"지금 가달왕은 천하의 성군이요 나라가 부유하고 군사가 강하여 갑병이 백만이요 장수가 천여 명이니 천하에 누가 감히 당하겠느냐. 송나라 황제가 하늘의 때를 모르고 어리석은 장졸을 몰아 대적하려 하니, 비하자면 하룻강아지가 범과 겨루는 것과 같다. 공연히 백성만 도탄에 빠뜨리니 어찌 가련하지 않겠느냐. 내가 진실로 죄 없는 신민의 남은 목숨을 불쌍히 여겨 이르는 것이니, 그대는 빨리 돌아가 송나라 황제에게 속히 항복하게 하고 정수정의 목을 베어 보내라. 그러면 우리가 군사를 물려 한편으로는 너희 나라 죄 없는 생령을 보전하게 하고, 한편으로는 너의 공명을 빛나게 할 것이다. 만일 순종하지 않으면 성을 무찔러 씨도 남기지 않을 것이니, 내 말을 허투루 듣지 말아 후회가 없게 하라.\" 이때 황흠이 진문 밖에서 말을 멈추고 그 사람을 바라보니 용모와 옷차림이 달랐다.","sp":[[3,6,"P","가달왕"],[238,241,"P","정수정"],[387,389,"P","황흠"]]},{"c":1,"sub":"","t":"괴이히 여겨 자세히 보니 지난날 강서로 귀양 간 진량이었다. 분한 마음이 더욱 북받쳐 칼을 들고 크게 외쳤다. \"네가 충신을 모해하고 귀양 간 진량이 아니냐. 임금을 배반하고 조상을 버리고 만고에 무도한 오랑캐를 섬기면서 무슨 낯을 들고 나서서 천조의 대신을 대하여 아비도 임금도 없는 말을 하느냐. 너 같은 역적은 천 번 베고 만 번 찢어 뒷사람을 징계하겠다.\" 하고 칼을 들고 말을 채쳐 달려드니, 진량이 머리를 숙이고 도망하여 적진 속으로 들어갔다. 이때 왕골대가 장대에 앉아 있다가 진량이 쫓겨 오는 것을 보고 급히 몸을 일으켜 필마단창으로 진문 밖에 나와 황흠을 맞아 한 합에 베어 들었다. 곧바로 금산성을 무찔러 송나라 황제를 잡으려고 군사를 재촉하여 사면을 철통같이 에워싸 물샐틈없게 하니, 가련하다, 송나라 진 장졸의 목숨이 어찌 되겠는가.","sp":[[27,29,"P","진량"],[80,82,"P","진량"],[225,227,"P","진량"],[258,261,"P","왕골대"],[274,276,"P","진량"],[316,318,"P","황흠"]]},{"c":1,"sub":"","t":"이때 송나라 진의 여러 장수와 관료가 성루 위에서 황흠의 승패를 보다가, 황흠이 적장에게 죽고 또 진량이 적국에 가서 항복해 있는 것을 알고 더욱 분함을 이기지 못하였다. 이 사유를 황상께 아뢰고 도적 깨뜨릴 방책을 의논하던 차에, 갑자기 적병이 사면으로 에워싸 물샐틈이 없으니, 성안의 수만 명 군졸이 양식이 떨어지고 또 도적이 물길을 끊었으므로 목이 말라 말 오줌을 받아 마시며 울부짖는 소리에 산천이 흐느꼈다. 황상이 이 모습을 보시고 차마 견디지 못하여 옥새를 꺼내 손에 쥐고 자결하려 하시니, 여러 장수와 군졸이 또 울며 천자를 위로하고 죽기로써 도적을 막으며 구원병이 오기를 기다렸다.","sp":[[28,30,"P","황흠"],[41,43,"P","황흠"],[55,57,"P","진량"],[102,104,"P","천자"],[233,235,"P","천자"],[297,299,"P","천자"]]},{"c":1,"sub":"","t":"한편 정 원수는 철통골을 쫓아 오랑캐 나라로 향하였다. 여러 날 만에 호산대에 이르니 산천이 험악하고 길이 좁아 사람과 말이 다니기 어려웠다. 도중에 진을 치고 길잡이를 불러 물었다. \"여기서 오랑캐 도성이 얼마나 되느냐?\" \"일백오십 리가 됩니다.\" 원수가 높은 산에 올라 두루 살펴보더니 한복을 불러 말하였다. \"병법에 뜻밖에 나가면 귀신도 헤아리지 못한다 하였으니, 너는 삼천 철기를 거느리고 샛길로 오랑캐 도성에 이르러 이리이리하라.\" 진시회를 불러 말하였다. \"너는 삼천 군을 거느리고 오늘 밤 큰길로 가면 내일 오전에 적장을 만날 것이니, 급히 잡을 생각 말고 다만 꾀어 오라.\" 또 용봉을 불러 말하였다. \"너는 이천 군을 거느리고 샛길로 호산대 어귀에 매복하였다가 내일 오후 적장이 지나간 뒤 뒷길을 끊어라.\" 그러고는 스스로 군사 오천을 거느리고 호산대 뒤에 매복하였다.","sp":[[3,7,"P","정수정"],[9,12,"P","철통골"],[163,165,"P","한복"],[248,251,"P","진시회"],[333,335,"P","용봉"]]},{"c":1,"sub":"","t":"이때 오랑캐 장수 철통골은 남만국 소식만 기다리며 정수정을 붙잡아 두려는 계교로 싸울 생각은 하지 않고 쫓기기만 하다가, 거의 오랑캐 도성 가까이 왔다. 문득 깨닫고 말하였다. \"남쪽 나라 소식은 아직 감감하고 공연히 정수정을 국경 안으로 들어오게 하였으니, 잘못하면 범을 길러 화를 남기고 문을 열어 도적을 들이는 꼴이 되겠다.\" 두려워 국왕에게 알려 많은 군사로 도성을 지키게 하고, 스스로 대군을 거느리고 정수정을 막았다. 이때 진시회가 삼천 군을 거느리고 거침없이 나아가다가 철통골을 만나 서로 싸웠는데, 몇 합이 못 되어 진시회가 거짓 패하여 달아났다. 철통골이 따라가다가 미치지 못하고 잠깐 쉬는데, 진시회가 다시 군사를 돌려 들이쳤다. 철통골이 더욱 분노하여 큰 칼을 들고 말을 채쳐 달려들어 몇 합을 어우르다가 진시회가 또 패하여 달아났다.","sp":[[10,13,"P","철통골"],[28,31,"P","정수정"],[122,125,"P","정수정"],[230,233,"P","정수정"],[243,246,"P","진시회"],[270,273,"P","철통골"],[297,300,"P","진시회"],[315,318,"P","철통골"],[342,345,"P","진시회"],[363,366,"P","철통골"],[406,409,"P","진시회"]]},{"c":1,"sub":"","t":"철통골이 놓치지 않고 쫓아가다가 한 산모퉁이를 지나니, 진시회는 간 곳이 없고 별안간 포 소리 한 번에 대장 한 사람이 황금 투구에 초록 전포와 은 갑옷을 입고 큰 칼을 들고 용총마를 몰아 내달으며 크게 외쳤다. \"적장은 달아나지 마라. 대송국 도원수 정수정이 여기서 기다린 지 오래다.\" 그 소리가 천지를 뒤흔들고 강산이 무너지는 듯하였다. 철통골이 크게 놀라 돌아볼 즈음 벌써 원수의 칼빛이 머리 위에 어른어른하였다. 철통골이 몸을 움츠리며 다시 돌아서서 싸우다가 당해 내지 못하여 말을 놓아 샛길로 화살같이 달아났다. 얼마 못 가서 또 포 소리가 나며 한 장수가 장창을 비껴들고 말을 채쳐 내달아 벼락 같은 소리로 외쳤다. \"적장은 달아나지 마라. 내가 장수의 영을 받아 너를 잡으려고 이곳에서 기다린 지 오래다.\" 하며 한 손으로는 타고 있는 말을 찔러 엎어뜨리고 한 손으로는 적장을 사로잡으니, 이는 용봉이 원수의 계책을 받들어 호산대 어귀에 매복하였다가 뜻밖에 내달아 적장을 사로잡은 것이었다.","sp":[[0,3,"P","철통골"],[31,34,"P","진시회"],[141,144,"P","정수정"],[192,195,"P","철통골"],[236,239,"P","철통골"],[453,455,"P","용봉"]]},{"c":1,"sub":"","t":"이때 원수가 대병을 지휘하여 적병을 짓쳐 버린 뒤 여러 장수와 힘을 합쳐 오랑캐 도성으로 향하였다. 한편 오랑캐 왕은 호철을 남쪽 나라에 보낸 뒤 다시 소식이 감감하여 궁금하던 중, 철통골이 연이어 패하고 송나라 군사가 승승장구하여 국경 가까이 이르렀다는 말을 듣고 크게 놀랐다. 나라 안에 남아 있는 군사를 모두 거느리고 친히 나가 철통골을 구원하고 적병을 막으려고, 승상 좌백에게 약간의 군사를 주어 도성을 지키게 하였다. 오랑캐 왕이 스스로 대군을 거느리고 며칠 만에 호산 경계에 이르니, 송나라 군사가 벌써 물밀듯 들어와 흰 모래 십 리 들에 가득하였다. 또 패잔병이 돌아와 아뢰기를 철통골이 사로잡히고 남은 군사는 다 항복하였다 하였다. 오랑캐 왕이 듣고 크게 놀라 넋을 잃었다가 다시 정신을 차려 진을 쳤는데, 얼마 지나지 않아 송나라 진의 선봉 장연이 이르러 싸움을 돋우었다. 오랑캐 왕이 좌우에 나가 싸우라 명하였으나, 오랑캐 장졸이 철통골이 사로잡혔다는 말을 듣고 겁을 내어 서로 돌아보기만 하고 감히 나가지 못하였다. 오랑캐 왕이 크게 노하여 여러 장수를 꾸짖어 물리치고 스스로 말에 올라 나가 싸우다가 크게 패하여, 패잔군을 거느리고","sp":[[59,64,"P","오랑캐 왕"],[66,68,"P","나호철"],[102,105,"P","철통골"],[187,190,"P","철통골"],[239,244,"P","오랑캐 왕"],[331,334,"P","철통골"],[362,367,"P","오랑캐 왕"],[424,426,"P","장연"],[442,447,"P","오랑캐 왕"],[475,478,"P","철통골"],[524,529,"P","오랑캐 왕"]]},{"c":1,"sub":"","t":"본국으로 도망하여 오니 성문이 닫혀 있었다. 군사를 시켜 문을 열라 재촉하니, 성문 위에서 대장 한 사람이 말하였다. \"내가 벌써 너희 도성을 얻었거늘 누가 감히 문을 열라 하느냐.\" 하며 성문 위에서 좌백의 머리를 내던지니, 이는 한복이었다. 한복은 원래 원수의 영을 받들어 길을 따라 가만히 와서 매복하였다가, 오랑캐 왕이 도성을 비우고 나가는 것을 보고 들어가 수성장 좌백을 죽이고 웅거한 것이었다. 이때 오랑캐 왕은 좌백이 죽고 도성을 빼앗긴 것을 보고 땅을 두드리며 소리 높여 통곡하였는데, 그 즈음 원수의 대군이 벌써 성 아래에 이르렀다. [?]","sp":[[130,132,"P","한복"],[137,139,"P","한복"],[176,181,"P","오랑캐 왕"],[230,235,"P","오랑캐 왕"]]},{"c":1,"sub":"","t":"오랑캐 왕이 할 수 없이 인끈을 목에 걸고 나가 항서를 올렸다. 원수가 성문 누각 위에 앉아 오랑캐 왕과 철통골을 잡아들여 장대 아래 꿇리고 크게 꾸짖었다. \"너희가 군사를 일으켜 천조를 범하였으니 그 죄는 만 번 죽어도 남음이 있다. 따로 처치하겠다.\" 오랑캐 왕 등이 머리를 조아려 사죄하자, 원수가 친히 묶인 것을 풀고 장대 위로 불러올려 자리를 주고 술과 안주를 가져다 너그러이 대접하니, 오랑캐 왕 등이 그 은덕을 못내 칭송하였다. 이날 원수가 장졸을 먹이고 위로하고, 또 여러 장수를 불러 술을 두고 각기 공을 치하하는데, 홀연 문지기 군졸이 아뢰기를 본국 사신이 왕명을 받들고 왔다 하였다. 원수가 급히 맞아들여 물으니 사신이 사유를 자세히 아뢰고 또 봉한 글을 내어 올렸다. 원수가 향탁을 차리고 조칙을 받들어 보니 이러하였다.","sp":[[0,5,"P","오랑캐 왕"],[52,57,"P","오랑캐 왕"],[59,62,"P","철통골"],[143,148,"P","오랑캐 왕"],[222,227,"P","오랑캐 왕"]]},{"c":1,"sub":"","t":"\"짐이 경을 만 리 북쪽 나라에 보내고 밤낮 마음을 졸였는데, 국운이 불행하여 천만뜻밖에 남만의 가달이 또 배반하여 국경을 범하였다. 짐이 맹동현 등을 데리고 친정하였으나 적장 왕골대는 천하의 용장이라 당할 자가 없어, 짐이 금산성에서 포위를 당한 지 여러 날이 되도록 아무 계책이 없다. 부디 경은 빨리 돌아와 짐의 곤경을 구해 주기를 바라노라.\" 하셨다.","sp":[[78,81,"P","맹동현"],[99,102,"P","왕골대"]]},{"c":1,"sub":"","t":"원수가 다 보고 분한 마음이 하늘을 찌르는 가운데 눈물을 흘리며 오랑캐 왕을 불러 말하였다. \"그대는 다시 외람된 뜻을 두지 말고 본토를 잘 지키며 해마다 조공을 거르지 마라.\" 곧 장후를 불러 일렀다. \"황상께서 몹시 위급한 가운데 계시니 시각을 지체할 수 없소. 나는 한복을 데리고 먼저 갈 것이니 장군은 여러 장수와 군졸을 데리고 뒤따라 속히 오시오.\" 하고 곧 떠났다. 장검을 들고 말에 올라 말에게 타일렀다. \"너는 비록 짐승이나 송나라 산천의 정기를 타고났고 또 송나라 곡식을 먹었다.","sp":[[36,41,"P","오랑캐 왕"],[102,104,"P","장연"],[115,117,"P","천자"],[152,154,"P","한복"]]},{"c":1,"sub":"","t":"이제 천자의 곤경이 시각에 달렸으니, 너는 평생의 힘을 다하여 천자를 구하고 억만 생명을 건지게 하라.\" 말이 귀를 기울이고 한참 듣더니 몸을 솟구치며 주홍 같은 입을 벌리고 벼락같이 소리를 지르고는, 푸른 하늘을 바라고 흰 구름을 헤칠 듯 나는 듯이 달려갔다. 사람은 천신 같고 말은 날아가는 용 같아 남경 수만 리를 순식간에 다다르니, 이때 금산 아래에는 살기가 하늘에 뻗쳐 성안에는 곡성이 진동하고 성 밖에는 적병이 겹겹이 둘러싸고 있었다.","sp":[[3,5,"P","천자"],[35,37,"P","천자"]]},{"c":1,"sub":"","t":"원수가 분을 참지 못하여 장창을 비껴들고 벼락같이 소리를 지르며 곧바로 적진을 헤치고 들어가니, 동쪽으로 번쩍 서쪽 장수를 베고 서쪽으로 번쩍 북쪽 장수를 죽였다. 수백만 적병이 뜻밖의 변을 당하여 정신을 차리지 못하고 사방으로 흩어져 달아났다. 이때 원수가 적진을 물리치고 그제야 성문 밖에 가서 수문장을 불러 문을 열라 재촉하였다.","sp":[]},{"c":1,"sub":"","t":"이때 천자는 금산성에서 적진에 싸인 지 여러 날이 되니 양식이 다하고 성안에 물이 없어, 수만 명의 장수와 군졸이 굶주림과 목마름을 면치 못하여 목숨이 시각에 달려 있었다. 탄식하는 모습과 울부짖는 소리에 해와 달이 빛을 잃고 천지가 참담하였다. 임금과 신하, 위아래가 서로 붙잡고 통곡할 뿐이요, 오직 기다리는 정 원수는 소식이 감감하였다. 황상이 맹동현을 붙잡고 울며 말씀하셨다. \"나의 박복한 죄로 수천만 신민에게 이런 참화를 당하게 하니 이것은 다 짐의 밝지 못한 죄라. 어찌 짐의 한 목숨을 아껴 온 나라 생령이 도탄에 빠지는 것을 보겠는가.\" 하고 옥새를 끌러 신하들에게 주며 말씀하셨다. \"경들은 이것을 맡았다가 이다음에 덕 있는 사람을 가려 전하라.\" 그러고는 마침내 칼을 빼어 자결하려 하시니, 임금과 신하 위아래가 일시에 달려들어 용포 소매를 붙잡고 통곡하며 위로하였다. 그런데 별안간 성 밖에서 함성이 일어나며 호통 소리에 천지가 무너지는 듯하고 천병만마가 물 끓듯 하였다.","sp":[[3,5,"P","천자"],[175,179,"P","정수정"],[192,194,"P","천자"],[196,199,"P","맹동현"]]},{"c":1,"sub":"","t":"천자와 신하들이 그 소리를 듣고 더욱 놀라 허둥지둥할 즈음, 남문 수문장이 급히 아뢰었다. \"정 원수가 와서 문을 열라 합니다.\" 황상이 들으시고 황망한 가운데 반가운 마음에 버선발로 걸어 내달아 남문께로 가시니, 난데없는 대장 한 사람이 적장의 머리를 무수히 베어 말에 달고 들어오다가 천자를 뵙고 급히 말에서 내려 땅에 엎드려 통곡하였다. 모두 보니 정수정이 분명하였다. 황상이 달려들어 수정의 손을 잡고 통곡하며 말씀하셨다. \"짐이 하마터면 다시는 경의 얼굴을 보지 못하고 죽을 뻔하였는데, 하늘과 신령이 도와 경을 다시 보니 이제는 지금 죽어도 한이 없노라.\"","sp":[[0,2,"P","천자"],[52,56,"P","정수정"],[73,75,"P","천자"],[161,163,"P","천자"],[198,201,"P","정수정"],[210,212,"P","천자"],[219,221,"P","정수정"]]},{"c":1,"sub":"","t":"수정이 엎드려 아뢰었다. \"폐하께서 이런 곤란을 당하시게 한 것은 다 신의 죄입니다.\" 하며 모시고 막차로 들어가 자리에 앉으시게 한 뒤, 북쪽 오랑캐를 쳐 마웅을 죽이고 오랑캐 왕의 항복을 받은 일과, 천사가 가져온 조칙을 보고 필마로 밤을 새워 달려온 일을 하나하나 아뢰었다. 그러고는 장대로 나와 여러 장수를 불러 세우고 적진의 허실을 물으니, 맹동현과 여러 장수가 다 말하기를 적장 왕골대의 용맹은 천하에 짝이 없다 하고, 양성초가 사로잡힌 일과 역적 진량이 적진으로 가서 남만 왕을 도와 진 앞에 나와 불경한 말을 하던 일을 하나하나 아뢰었다. 원수가 듣다가 분한 마음을 이기지 못하여 칼로 책상을 치며 말하였다. \"진량 역적놈의 머리부터 베어 나라의 원수와 나의 한을 풀겠다.\" 하고 한복을 불러 군졸을 조련하게 하였다.","sp":[[0,2,"P","정수정"],[88,90,"P","마웅"],[96,101,"P","오랑캐 왕"],[196,199,"P","맹동현"],[218,221,"P","왕골대"],[241,244,"P","양성초"],[257,259,"P","진량"],[269,273,"P","가달왕"],[350,352,"P","진량"],[389,391,"P","한복"]]},{"c":1,"sub":"","t":"이때 적장 왕골대는 승승장구하여 송나라 진중에 당할 장수가 없는 줄 알고 의기양양하여 무인지경같이 군사를 몰아 금산성을 철통같이 둘러싸고 송나라 황제의 항복을 받으려 하였다. 그런데 별안간 난데없는 호통 소리에 산천이 진동하며, 소년 대장 한 사람이 필마단창으로 무인지경같이 달려들어 좌충우돌하니 장졸의 머리가 가을바람에 지는 낙엽 같았다. 겹겹이 에웠던 군사가 물결 갈라지듯 사방으로 흩어져 달아났다. 왕골대가 이 거동을 보고 크게 놀라 진량을 불러 물었다. \"군중에서 휘젓고 다니는 저 장수는 누구며 어디서 왔느냐?\" 진량이 한참 바라보다가 크게 놀라 말하였다. \"그 장수는 북쪽 땅에 출전하였던 정수정이 분명한가 합니다.\"","sp":[[6,9,"P","왕골대"],[226,229,"P","왕골대"],[246,248,"P","진량"],[292,294,"P","진량"],[336,339,"P","정수정"]]},{"c":1,"sub":"","t":"왕골대가 말하였다. \"조그마한 아이가 재주만 믿고 함부로 진 위에 나와 휘젓고 다니니 가소롭도다. 내일은 내가 마땅히 잡아다 혼을 내어 보내리라.\" 하고 조금도 근심하는 빛이 없었다. 이튿날 정 원수가 여러 장수를 거느리고 성문을 크게 열고 나가 진을 친 뒤 한복에게 나가 싸우라 하였다. 한복이 명을 받고 곧 말에 올라 진 앞에 나가 외쳤다. \"적장 가운데 나를 당할 자가 있거든 빨리 나와 내 칼을 받으라.\" 적진에서 왕골대의 아우 왕철이 팔십 근 도끼를 들고 나왔다. 한복이 맞아 싸워 한 합에 왕철의 머리를 베어 들고 좌충우돌하니, 적진의 중군장 손광이 이를 보고 창을 바로 들고 말을 몰아 곧바로 한복에게 덤볐다. 한복이 맞아 싸워 십여 합이 되도록 승부가 나지 않았는데, 홀연 타고 있던 말이 무릎을 꿇고 엎어졌다. 한복이 몸을 솟구쳐 땅에 내려서는 사이에 손광이 창을 높이 들고 달려들어 찌르려 하였다. 원수가 장대에서 한복이 위급한 것을 보고 몸을 날려 말에 오르며 장창을 비껴들고 화살같이 달려들어 벼락같이 외쳤다. \"적장은 나의 부장을 해치지 마라.\" 한마디 소리에 손광을 베어 들고 곧바로 적진으로 달려들어 무인지경같이","sp":[[0,3,"P","왕골대"],[107,111,"P","정수정"],[145,147,"P","한복"],[162,164,"P","한복"],[236,239,"P","왕골대"],[265,267,"P","한복"],[306,308,"P","장연"],[339,341,"P","한복"],[349,351,"P","한복"],[407,409,"P","한복"],[466,468,"P","한복"]]},{"c":1,"sub":"","t":"짓쳐 버리고 한복을 구하여 본진으로 돌아올 즈음, 적진에서 대장 한 사람이 화살같이 내달으며 크게 외쳤다. \"적장은 가지 말고 내 칼을 받으라.\" 그 소리에 산천이 울렸다. 이때 원수는 손광의 머리를 베어 들고 본진으로 돌아오다가 적장이 또 쫓아오는 것을 보고 분노하여 손광의 머리를 땅에 던지고 다시 말머리를 돌려 세우고 오는 장수를 바라보았다. 키가 구 척이요 얼굴빛은 먹물을 끼얹은 듯하고 눈은 화경 덩이 같아 바로 보기 어려웠다. 머리에는 황금 투구를 젖혀 쓰고 몸에는 용비늘 갑옷을 입고 불빛 같은 적토마를 몰아 진 앞에 나오는 위풍이 늠름하니, 이는 남만 대장 왕골대였다. 이날 장대 위에서 두 진의 승패를 보다가 손광과 아우 왕철이 죽는 것을 보고 분을 이기지 못하여 내달으며 외쳤다. \"내 아우 왕철과 부장 손광을 벤 장수는 성명을 대고 나와 내 칼을 받으라.\" 원수가 그 말을 듣고 말을 채쳐 진 앞에 나서며 외쳤다. \"나는 대송국 대원수 정수정이거니와, 너는 어떤 무리이기에","sp":[[7,9,"P","한복"],[320,323,"P","왕골대"],[479,482,"P","정수정"]]},{"c":1,"sub":"","t":"한갓 강포함만 믿고 천조를 범하느냐. 내가 너의 머리를 베어 우리 황상의 근심을 덜고자 한다.\" 왕골대가 웃으며 말하였다. \"너 같은 것은 입에서 젖내 나는 아이일 뿐 아니라, 내 들으니 너는 한낱 계집으로 임금을 속이고 당돌하게 진 위에 나와 대장부와 겨루려 하니 하룻강아지 범 모르는 격이로다. 내가 한 나라의 대장으로 어찌 너 같은 계집아이와 재주를 겨루어 칼을 들겠느냐. 너는 빨리 돌아가 군중에서 밥이나 지어 주고 군사 옷이나 기워 주어라.\" 정 원수가 크게 노하여 말하였다. \"무지한 오랑캐가 다만 강함만 믿고 감히 천조의 대신을 능욕하느냐. 너 같은 놈은 잠시도 용서하지 못하겠으니 빨리 목을 늘여 내 칼을 받으라.\" 그 소리가 깊은 산 절벽에서 사나운 범이 부르짖는 듯하였다.","sp":[[37,39,"P","천자"],[54,57,"P","왕골대"],[253,257,"P","정수정"]]},{"c":1,"sub":"","t":"왕골대가 이를 보고 분기가 크게 일어나 칼을 들고 말에 오르려 하는데, 옆에서 한 장수가 내달아 말하였다. \"부친은 노여움을 그치소서. 조그마한 아이 하나 잡는 데 어찌 부친의 손을 쓰시겠습니까. 소자가 나가 정수정을 베고 송나라 황제를 사로잡아 숙부의 원수를 갚겠습니다.\" 이는 왕골대의 아들 왕필이었다. 키가 여덟 자 다섯 치요 힘은 능히 천 근을 드는 장사였다. 팔십 근 철퇴를 들고 말을 몰아 나오니, 원수가 바라보다가 말 한마디 붙일 새도 없이 화살같이 달려들어, 한 손으로는 창을 들어 타고 있는 말을 찔러 엎어뜨리고 한 손으로는 왕필을 사로잡아 본진으로 돌아왔다. 이때 왕골대가 아들이 사로잡히는 것을 보고 분기가 크게 일어나 큰 칼을 들고 내달아 화살같이 달려들었다. 원수는 한복을 급히 불러 왕필을 맡겨 본진으로 보내고, 말머리를 돌려 왕골대를 맞아 싸우니, 북소리와 고함 소리는 천지를 뒤흔들고 두 장수의 칼빛은 번개같이 번쩍였다.","sp":[[0,3,"P","왕골대"],[117,120,"P","정수정"],[157,160,"P","왕골대"],[165,167,"P","왕필"],[303,305,"P","왕필"],[326,329,"P","왕골대"],[386,388,"P","한복"],[396,398,"P","왕필"],[421,424,"P","왕골대"]]},{"c":1,"sub":"","t":"이같이 수십여 합을 싸웠으나 승부가 나지 않았다. 왕골대는 끝내 원수가 나이 어린 것을 업신여겨 철퇴를 들어 원수를 치려 하였는데, 그 즈음 원수의 칼이 번뜩하며 적장의 손을 치니 철퇴 든 손이 잘려 철퇴가 땅에 떨어졌다. 별안간 말이 놀라 달아나니, 원수가 벼락같이 호통쳤다. \"적장은 달아나지 말고 내 칼을 받으라.\" 하며 곧바로 적진을 헤치고 들어갔다. 이때 천자가 장대에서 보시다가 행여 실수가 있을까 하여 징을 쳐 군사를 거두시니, 원수가 징 소리를 듣고 본진으로 돌아왔다. 천자가 진문 밖에 나와 맞으시며 손을 잡고 못내 칭찬하시고 다시 당부하셨다. \"왕골대는 손광과 왕필 같은 무리가 아니니 각별히 조심하여 부디 가볍게 여기지 마라.\" 원수가 명을 받고 물러났다.","sp":[[28,31,"P","왕골대"],[204,206,"P","천자"],[271,273,"P","천자"],[315,318,"P","왕골대"],[324,326,"P","왕필"]]},{"c":1,"sub":"","t":"이때 왕골대는 패하여 돌아와 탄식하였다. \"내가 정수정이 나이 어린 것을 업신여기다가 도리어 낭패를 당하니 참으로 부끄러운 일이다. 또 아우 왕철이 죽고 아들 왕필이 사로잡혀 갔으니 이 한을 어찌 갚을꼬.\" 하다가 한 계교를 생각하고 사람을 송나라 진에 보내 말하였다. \"전에 잡아 온 양성초를 보낼 것이니 내 아들 왕필을 돌려보내라.\" 원수가 대답하였다. \"내일 진 앞에서 서로 바꾸어 보내자.\" 이튿날 서로 진문을 열고 마주하는데, 적진에서는 왕골대가 양성초를 데리고 나오고 송나라 진에서는 정 원수가 왕필을 끼고 나와, 두 사람을 각기 진문 깃발 아래 세우고 두 진의 대장이 서로 이야기를 나누었다. 포 소리 한 번에 양성초는 송나라 진으로 달려오고 왕필은 적진으로 달려가는데, 미처 진문에 들어가기 전에 원수가 화살 한 대로 왕필의 뒤통수를 쏘아 엎어뜨렸다. 왕골대가 이를 보고 크게 노하여 창을 들고 말을 채쳐 송나라 진으로 달려들며 크게 외쳤다. \"신의 없는 아이가 내 아들을 쏘았으니 내가 너를 베어 그 원수를 갚겠다. 빨리 나와 칼을 받으라.\"","sp":[[3,6,"P","왕골대"],[27,30,"P","정수정"],[89,91,"P","왕필"],[160,163,"P","양성초"],[177,179,"P","왕필"],[250,253,"P","왕골대"],[255,258,"P","양성초"],[277,281,"P","정수정"],[283,285,"P","왕필"],[349,352,"P","양성초"],[367,369,"P","왕필"],[410,412,"P","왕필"],[429,432,"P","왕골대"]]},{"c":1,"sub":"","t":"원수가 응하여 창을 들고 말을 몰아 나와 말하였다. \"내가 너도 벨 것이로되 한 칼로 남의 부자를 함께 베지 않는다 하기에 우선 용서하거니와, 너는 빨리 돌아가 너의 국왕을 나와 항복하게 하여 여러 목숨을 보전하여 가거라.\" 왕골대가 더욱 분을 이기지 못하여 칼을 휘두르며 달려들었다. 원수가 맞아 싸워 삼십여 합에 이르니 두 장수의 기운과 정신이 점점 씩씩하여, 왕골대의 고함과 원수의 호통 소리에 하늘이 무너지고 땅이 꺼지는 듯하였다. 두 진의 장졸은 정신을 잃고 멍하니 서서 볼 따름이었다. 날이 저물자 두 진에서 징을 쳐 군사를 거두니 두 장수가 각각 본진으로 돌아갔다.","sp":[[126,129,"P","왕골대"],[204,207,"P","왕골대"]]},{"c":1,"sub":"","t":"이때 왕골대는 분해하며 진으로 돌아와 남만 왕을 보고, 손광과 아우 왕철과 아들 왕필이 죽은 일을 하나하나 아뢰며, 정수정의 지략과 용맹이 남보다 뛰어나 갑자기 잡기 어렵다고 한탄하였다. 남만 왕도 근심하자, 이때 진량이 곁에 있다가 말하였다. \"정수정은 절강으로 귀양 가서 죽은 정흠의 자식입니다. 그 모친이 지금 청주에 홀로 있고, 그곳 군사는 수정이 다 거느리고 왔으니 성안이 비었을 것입니다. 대왕께서 급히 군사를 보내 그 어미를 잡아다 진중에 가두고 죽인다 하면, 제 아무리 충심이 있은들 어찌 임금만 생각하고 어미는 모른 체하겠습니까. 필경 어미를 보러 올 것이니 그때 잡아 죽이는 것이 좋을까 합니다.\"","sp":[[3,6,"P","왕골대"],[21,25,"P","가달왕"],[45,47,"P","왕필"],[65,68,"P","정수정"],[105,109,"P","가달왕"],[120,122,"P","진량"],[138,141,"P","정수정"],[157,159,"P","정흠"],[195,197,"P","정수정"]]},{"c":1,"sub":"","t":"남만 왕과 왕골대가 크게 기뻐하며 그 계책이 묘하다 하고, 곧 수하의 친근한 군사 수백을 지휘하여 청주로 보냈다. 이때 국공 부인은 청주에 있으면서 수정을 북쪽 땅에 보내고 밤낮으로 어서 승전하고 돌아오기만 빌며 근심 속에 지냈다. 하루는 별안간 한 떼의 군마가 성문을 깨뜨리고 달려들어 국공 부인을 잡아내어 수레에 싣고 바람같이 몰아가니, 부인이 혼비백산하여 아무 영문도 모르고 끌려갔다. 얼마 만에 정신을 차려 생각하니, '이제는 수정이 죽은 것이 분명하구나.","sp":[[0,4,"P","가달왕"],[6,9,"P","왕골대"],[67,72,"P","양씨 부인"],[83,85,"P","정수정"],[161,166,"P","양씨 부인"],[243,245,"P","정수정"]]},{"c":1,"sub":"","t":"만일 살아 있어 공을 이루었다면 나를 이처럼 잡아갈 리가 있겠는가.' 하며 통곡하고 정신없이 끌려가 보니 듣도 보도 못하던 오랑캐 무리였다. 마음에 더욱 놀라 몸 둘 곳이 없음을 생각하고 오직 죽을 마음뿐이었다. 이윽고 남만 왕이 불러들여 대청 위에 자리를 주고 위로하며 달래었다. \"그대의 아들 수정이 하늘의 때를 모르고 무도한 송나라 황제를 섬겨 백성을 도탄에 빠뜨리니, 그 죄상을 따지자면 잡아 벨 것이로되 그대의 낯을 보아 용서할 것이다. 그대가 수정에게 편지를 하여 불러오면 모자가 서로 만나 볼 것이요, 또 과인을 섬기면 부귀영화를 마음대로 할 것이니 그대는 사양하지 말고 지금 편지를 하라.\" 하며 문방사우를 가져다 주었다. 부인이 그 말을 듣자 분한 마음이 가슴에 가득하여 소리 높여 크게 꾸짖었다. \"이놈 개 같은 도적놈아, 천지도 무섭지 않고 해와 달도 두렵지 않으냐. 까닭 없이 천자를 배반하고 군사를 일으켜 천조를 범하니","sp":[[123,127,"P","가달왕"],[166,168,"P","정수정"],[254,256,"P","정수정"],[447,449,"P","천자"]]},{"c":1,"sub":"","t":"네 죄상을 생각하면 천고에 없는 역적이거늘, 어찌 내 자식을 불러다 너 같은 무도한 오랑캐를 섬기게 하겠느냐.\" 하며 벼룻돌을 집어 남만 왕의 얼굴을 쳤다. 남만 왕이 크게 노하여 좌우에 명하여 잡아내어 베라 하니, 여러 장수가 간하였다. \"그 부인이 지금 대왕께 이같이 죄를 범하는 것은 정말로 죽기를 청하는 것입니다. 대왕께서 만일 그 소원대로 죽이시면 군중에 이롭지 못한 일이 여러 가지 있을까 합니다. 첫째는 자식의 죄로 어미를 잡아다 죽이는 것은 의가 아니요, 둘째는 수정이 그 어미가 죽은 것을 알면 이를 갈고 원수를 갚으려 할 것입니다. 대왕께서는 분을 참으시고 우선 용서하여 가두어 두었다가, 이다음 수정을 잡은 뒤에 함께 죄를 다스리소서.\" 남만 왕이 옳게 여겨 죽이지 않고 찬 옥에 가두어 두었다. 그러고는 거짓으로 부인의 편지를 만들어 화살에 매어 송나라 진으로 쏘아 원수가 보게 하였다. 이때 원수가 장대에서 여러 장수와 군무를 의논하는데, 졸병이 난데없는 서간 하나를 올렸다. 원수가 의아해하며 뜯어보니 이러하였다.","sp":[[74,78,"P","가달왕"],[88,92,"P","가달왕"],[267,269,"P","정수정"],[344,346,"P","정수정"],[368,372,"P","가달왕"]]},{"c":1,"sub":"","t":"\"국공 부인 양씨는 아들 수정에게 부치노라. 아아, 국운이 불행하여 변방이 어지러우므로 너를 만 리 변경에 보내고 밤낮으로 마음을 졸였더니, 뜻밖에 가달국 왕이 사자를 보내 나를 잡아다가 위협하므로 목숨을 보전하지 못할까 하였다. 그런데 다시 왕의 바다 같은 은덕을 입어 높은 누각에서 몸이 편안하고 의식이 넉넉하여, 전날 천조에 있을 때보다 오히려 영화롭게 지내나, 다만 밤낮으로 외로운 마음에 너 하나만 생각하노라. 부디 너는 천명에 순종하여 쇠한 송나라를 멀리하고 남국으로 향하면, 몸이 영화로울 뿐 아니라 모자가 한곳에서 만나 부귀를 함께할 것이니 그것이 자식 된 도리에 옳지 않으냐. 충신은 효자의 집안에서 구한다 하였으니, 너는 부모가 길러 준 수고로운 은혜를 생각하여 어미가 밤낮 기다리는 마음을 저버리지 말기를 고대하노라. 할 말은 끝이 없으나 눈물이 앞을 가려 이만 그친다.\" 하였다.","sp":[[1,6,"P","양씨 부인"],[14,16,"P","정수정"]]},{"c":1,"sub":"","t":"원수가 다 보고 나자 머리털이 곤두서고 천지가 아득하여 눈물이 솟구치며 어찌할 줄 모르다가, 다시 정신을 차려 편지를 거듭 살펴보니 글씨가 모친의 친필이 아니어서 의아해하였다. 곧 이 사유를 천자께 아뢰니, 황상도 크게 놀라 말씀하셨다. \"이 글씨가 비록 경의 모친 필적은 아니나 반드시 무슨 연고가 있는 일이니, 사람을 속히 청주로 보내 알아보라.\" 그 말씀이 끝나기도 전에 문지기 군졸이 아뢰기를, 청주 수성졸이 긴급한 일이 있어 왔다 하였다. 급히 불러들여 물으니 군사가 아뢰었다. \"모일 밤에 난데없는 적병 수백이 달려들어 태부인을 모셔 갔습니다.\" 원수가 듣고 크게 놀라 통곡하며 한참 생각하다가 눈물을 거두고 다시 황상께 아뢰었다. \"신은 본디 무남독녀의 외로운 몸으로, 일찍 아비가 만 리 먼 땅에서 원통하게 죽고 다만 어미 하나를 의지하고 있었는데, 천만뜻밖에 적국에 잡혀간 것이 분명합니다.","sp":[[107,109,"P","천자"],[116,118,"P","천자"],[297,300,"P","양씨 부인"],[350,352,"P","천자"]]},{"c":1,"sub":"","t":"어미가 오라 한 서찰이 비록 친필은 아니오나, 자식 된 자가 어찌 태연히 있으면서 어미를 도적의 손에 죽으라 하겠습니까. 신이 본디 폐하를 위하여 화살과 돌을 무릅쓰고 적국에 간 것은 한마음을 한결같이 먹었기 때문이었는데, 이제는 마음이 어지러우니 어찌 정신을 온전히 하여 군사를 의논하겠습니까. 원컨대 폐하께서는 조정의 여러 신하 가운데 지략 있는 사람이 많으니 그중에서 골라 군무를 맡기시어 도적을 소멸하고 나라를 태평하게, 백성을 편안하게 하소서.\" 또 여러 장수를 돌아보며 말하였다. \"그대들은 충성과 힘을 다하여 입신양명한 뒤 이름을 역사에 남기고, 행여나 수정이 끝을 맺지 못하고 불충한 것을 본받지 마라.\" 하고 엎드려 소리 높여 통곡하였다. 황상도 눈물을 흘리시며 수정의 손을 붙잡고 말씀하셨다. \"경이 모친을 위하여 가는 것은 효도가 지극한 것이다.","sp":[[317,319,"P","정수정"],[367,369,"P","천자"],[380,382,"P","정수정"]]},{"c":1,"sub":"","t":"짐이 붙잡아 경을 불효에 빠지게 하는 것은 의가 아니요, 경을 보내자니 나라의 기둥이 부러지고 짐의 손발이 끊어지는 것이라. 짐이 어찌 살기를 바라겠는가. 경이 가는 날이면 짐도 머리를 풀고 산에 들어가 세상을 잊고자 하노라.\" 하시며 소리 높여 통곡하시니, 여러 장수와 신하가 다 눈물만 흘릴 따름이요 아무 말도 하지 못하였다. 그때 반열 가운데서 한복이 내달아 원수에게 말하였다. \"장군은 어찌하여 사체와 사리를 생각하지 못하십니까. 사람이 세상에 나서 몸을 국가에 바치면 사사로운 일을 돌아보지 못하는 법이요, 또 위를 섬기는 데 임금과 아버지가 한 몸이나 임금의 급한 일을 먼저 하고 부모의 일을 뒤에 하는 것은 떳떳한 이치입니다. 장군은 나라의 은혜를 입어 몸을 임금께 바쳤습니다.","sp":[[196,198,"P","한복"]]},{"c":1,"sub":"","t":"임금의 위태로우심이 아침저녁에 달려 있는데 어느 겨를에 사사로운 일을 돌아보겠습니까. 또 그 편지를 보니 사연과 필적이 태부인의 친필이 아닌 것은 분명합니다. 장군은 어찌 옛날 한나라 서원직의 일을 생각하지 못하십니까. 원직이 조조에게로 가지 않았다면 그 모부인이 죽지 않았을 것을, 원직이 위조한 편지를 살피지 못하고 경솔히 갔기 때문에 그 모부인이 죽었습니다. 이로 보면 국공 부인의 엄정한 절개는 아는 바인데, 어찌 도적의 위협을 이기지 못하여 장군께 오라는 편지를 쓰셨겠습니까.","sp":[[67,70,"P","양씨 부인"],[210,215,"P","양씨 부인"]]},{"c":1,"sub":"","t":"소장의 생각으로는 적장이 태부인을 모셔 간 것은 한 계교이니, 어찌 그 간사한 꾀에 빠져 남의 웃음을 사려 하십니까. 지금 적진을 급히 깨뜨리고 태부인을 모셔 오는 것이 옳을까 합니다.\" 원수가 한복의 말을 다 듣더니 환하게 깨달아 눈물을 거두고 여러 장수를 불러 세우고 말하였다. \"내가 하늘에 오르고 땅에 들어가더라도 적장을 베고 남만 왕을 사로잡기 전에는 돌아오지 않을 것이니, 그대들은 군사를 수습하여 뒤를 따르라.\" 하고 장창과 큰 칼을 들고 말에 올랐다. 보통 사람이라도 급한 일을 당하면 힘이 나서 없던 기운이 배나 나는 법인데, 하물며 정 원수가 당한 일이니 눈에 무엇이 보였겠는가.","sp":[[14,17,"P","양씨 부인"],[81,84,"P","양씨 부인"],[109,111,"P","한복"],[187,191,"P","가달왕"],[308,312,"P","정수정"]]},{"c":1,"sub":"","t":"이처럼 분한 마음에 이를 갈며 말을 채쳐 적진을 헤치고 번개같이 달려드니, 사람은 천신 같고 말은 날아가는 용 같았다. 곧바로 중군의 장막을 헤치고 들어가니 적진 장졸이 뜻밖의 변을 당하여 어찌 된 곡절인지 모르고 물결 갈라지듯 흩어졌다. 왕골대는 이때 장막 안에 있다가 미처 손을 놀릴 새도 없이, 원수의 칼빛이 번쩍하며 크게 한 번 소리치자 왕골대의 머리가 떨어졌다. 원수가 그 머리를 칼끝에 꿰어 들고 좌충우돌하니 적진 장졸의 머리가 가을바람에 지는 낙엽 같았다. 순식간에 수십만 적병을 무찌르고 또 남만 왕을 잡으려고 있는 곳을 물을 즈음, 한복이 남만 왕을 사로잡아 왔다.","sp":[[71,73,"P","장연"],[134,137,"P","왕골대"],[193,196,"P","왕골대"],[283,287,"P","가달왕"],[307,309,"P","한복"],[311,315,"P","가달왕"]]},{"c":1,"sub":"","t":"원수는 남만 왕을 본진으로 보내고 남은 군사마저 무찌르려 할 즈음, 군사들이 저희끼리 진량을 또 잡아 왔다. 원수가 진량을 보고 더욱 분한 마음이 가슴에 가득하여 곧 베려 하다가, 서울로 잡아가 죄를 물은 뒤에 죽이려고 우선 본진으로 보내 가두라 하였다. 남은 적병의 항복을 다 받은 뒤 태부인이 계신 곳을 찾으니, 적졸이 가르쳐 주어 급히 그곳으로 갔다. 이때 국공 부인은 적진에 잡혀 와서 항복하지 않았으므로 찬 옥에 갇혀 밤낮으로 수정 생각만 하였으나, 수만 리 북쪽 변방에 출정한 수정을 어찌 만나 보고 죽겠는가.","sp":[[4,8,"P","가달왕"],[48,50,"P","진량"],[65,67,"P","진량"],[161,164,"P","양씨 부인"],[203,208,"P","양씨 부인"],[244,246,"P","정수정"],[273,275,"P","정수정"]]},{"c":1,"sub":"","t":"그런 생각에 더욱 슬픈 눈물을 흘리며 컴컴한 찬 옥 속에서 굶어 죽기로 결심하고, 도적이 하루 한 끼씩 갖다 주는 음식에는 입도 대지 않았다. 여러 날을 굶어 정신이 혼미하게 누워 있었는데, 별안간 문밖이 요란하며 잠근 문을 여는 소리가 났다. 깜짝 놀라 속으로 생각하기를, '이놈들이 또 무슨 욕을 보이려고 이러는가. 그놈들에게 곤욕을 또 당하고 죽느니 내 손으로 먼저 죽어 잊으리라.' 하고 옷끈을 떼어 목을 매니 목숨이 경각에 달렸다. 이때 원수가 적졸을 데리고 부인이 갇힌 곳을 찾아가니, 몇 칸짜리 찬 옥을 짓고 바깥으로 가시 울타리를 쌓아 문을 잠가 두었다.","sp":[]},{"c":1,"sub":"","t":"원수가 급한 마음에 자물쇠를 깨뜨리고 들어가 보니, 모부인이 옷끈으로 목을 매고 기절해 있었다. 원수가 소리 높여 통곡하며 황급히 달려들어 얼싸안고 맨 것을 풀어 눕힌 뒤, 환약을 개어 먹이고 팔다리를 주물러 구호하였다. 이윽고 부인이 정신이 돌아와 눈을 떠 보니 웬 남자가 갑주를 입고 앉아 팔다리를 주무르고 있었다. 마음에 크게 놀라 꾸짖었다. \"무도한 도적이 체면도 모르고 감히 내 몸에 손을 대느냐.\" 하였으나 숨이 가물가물하였다. 원수가 울며 아뢰었다. \"어머니께서 수정을 몰라보십니까?","sp":[[266,268,"P","정수정"]]},{"c":1,"sub":"","t":"북쪽 땅에 갔던 수정이 여기 왔습니다.\" 부인이 그 말을 듣고 정신을 다시 차려 자세히 보니 틀림없는 수정이었다. 그만 달려들어 얼싸안고 소리 높여 통곡하며 말하였다. \"네가 하늘에서 떨어졌느냐, 땅에서 솟았느냐. 어찌하여 여기를 왔느냐?\" 수정이 그제야 북쪽 오랑캐를 쳐 항복을 받고 회군하려 할 즈음 천자께서 남만에게 곤경을 당하시어 위급함이 시각에 달려 사자를 보내셨기에, 밤을 새워 달려와 적장을 베고 남만 왕을 사로잡은 일을 하나하나 아뢰었다. 부인이 수정의 등을 어루만지며 말하였다. \"너는 여자로 태어났으나 황상의 위태로우심을 구하여 국가에 큰 공을 세웠으니 여중호걸이라 할 만하다. 그런데 내가 도적에게 잡혀 와서 이렇게 갇힌 줄은 어찌 알았느냐?\" 수정이 눈물을 뿌리며 말하였다. \"어머니께서 도적에게 이런 욕을 당하시게 한 것은 다 자식의 죄입니다.\" 하며 적진을 깨뜨리기 전 모친의 편지 사건의 전말을 하나하나 아뢰었다. 부인이 크게 놀라 말하였다. \"편지라니, 내가 죽으면 죽었지 개 같은 도적을 위하여 편지할 리가 있겠느냐. 그것은 다 그놈들이 간계로 위조한 것이 분명하다. 그 글씨가 필경 내 필적과는","sp":[[9,11,"P","정수정"],[57,59,"P","정수정"],[135,137,"P","정수정"],[170,172,"P","천자"],[229,233,"P","가달왕"],[258,260,"P","정수정"],[291,293,"P","천자"],[372,374,"P","정수정"]]},{"c":1,"sub":"","t":"다를 터인데 그것을 살피지 못하였더냐?\" 수정이 한복의 말을 듣고 깨달아 오지 않은 일을 자세히 아뢰니, 부인이 한복의 식견을 못내 칭찬하며 말하였다. \"네가 만일 한 장군의 말을 듣지 않고 왔더라면 우리 두 목숨이 어찌 살아 오늘 이렇게 만났겠느냐.\" 하며 더욱 슬픔을 금치 못하고 눈물을 흘렸다. 수정이 위로하며 모시고 본진으로 돌아와 숙소를 치우고 태부인을 편히 모셔 조리하시게 한 뒤, 곧 천자께 뵈러 갔다. 천자가 친히 진문 밖에 나와 수정의 손을 잡고 들어와 칭찬하며 말씀하셨다. \"경이 두 번 출정에 북쪽 오랑캐를 평정하여 큰 공을 세우고, 이번에 또 적을 사로잡아 짐의 목숨을 살려 내니, 이 공은 천하를 반으로 나누어 주어도 다 갚지 못하겠도다.\" 원수가 황공하여 대답하였다. \"이는 다 폐하의 큰 복이오니 어찌 신의 재주이겠습니까.\" 또 모친을 찾은 일을 하나하나 아뢰며, 만일 한복의 말을 듣지 않고 경솔히 갔다면 도적의 꾀에 빠져 모자의 목숨을 부지하지 못하였을 일을 또 아뢰니, 천자가 새로이 놀라시며 한복을 불러 칭찬해 마지않으셨다.","sp":[[23,25,"P","정수정"],[27,29,"P","한복"],[63,65,"P","한복"],[168,170,"P","정수정"],[198,201,"P","양씨 부인"],[222,224,"P","천자"],[233,235,"P","천자"],[249,251,"P","정수정"],[446,448,"P","한복"],[505,507,"P","천자"],[518,520,"P","한복"]]},{"c":1,"sub":"","t":"이윽고 황상이 장대에 나와 앉으시고 남만 왕을 잡아들여 계단 아래 꿇리고 죄를 따지셨다. \"네가 까닭 없이 군사를 일으켜 천조를 침범하였으니 네 죄는 천 번 베고 만 번 찢어도 남음이 있도다.\" 남만 왕이 머리를 조아려 사죄하였다. \"소적이 하늘의 때를 모르고 북쪽 오랑캐의 꾐을 듣다가 폐하께 큰 죄를 지은 일은 장대 아래에서 만 번 죽어도 남음이 있거니와, 엎드려 바라건대 폐하께서 한 번만 살려 주시면 억천만년 자자손손이 조공을 끊지 않겠습니다.\" 천자가 수정을 돌아보시며 물으셨다. \"어찌하면 좋겠는가?\" 수정이 아뢰었다. \"저자가 이미 항복하였으니 용서하여 보내시면, 아무리 무도한 무리라도 천은에 감격할 줄 모르고 다시 배반할 마음을 두겠습니까.\" 천자가 알아들으시고 군사를 시켜 묶은 것을 풀게 하시고, 원수에게 남만 왕을 불러올려 자리를 주게 하시고 술과 안주를 내어 너그러이 대접하신 뒤 타일러 본토로 보내셨다. 남만 왕 등이 머리를 두드리며 거듭 엎드려 은혜에 사례하고 본국으로 돌아갔다.","sp":[[4,6,"P","천자"],[20,24,"P","가달왕"],[109,113,"P","가달왕"],[254,256,"P","천자"],[258,260,"P","정수정"],[287,289,"P","정수정"],[369,371,"P","천자"],[406,410,"P","가달왕"],[464,468,"P","가달왕"]]},{"c":1,"sub":"","t":"원수가 천자께 아뢰어 환궁하시게 하니, 천자는 백관을 거느리고 앞서시고 원수는 대군을 통솔하여 뒤를 따랐다. 양성초에게는 본부 군사를 거느리고 태부인을 모시고 청주로 가게 하였는데, 부인이 백옥 가마를 높이 타고 수천 군졸이 전후좌우로 옹위하여 깃발과 창검이 해와 달을 가리니, 그 엄숙한 위의는 출전하는 여장군이라 할 만하였다. 이때 천자가 여러 날 만에 서울에 이르러 환궁하신 뒤 백관의 조회를 받으시는데, 마침 장연이 북쪽 땅에 출전하였던 여러 장수와 군졸을 거느리고 이르렀다. 황상이 반기시어 불러 위로하시고, 또 원수를 불러 진량의 죄를 다스리라 하셨다. 원수가 명을 받고 나와 장대에 앉아 진량을 바람같이 잡아들여 계단 아래 꿇리고, 칼로 책상을 치며 소리 높여 크게 꾸짖었다. \"이놈, 네가 진량이냐. 너는 무엇으로 생긴 놈이기에 하늘 같은 나라 은혜를 입고서 보답할 생각은 하지 않고","sp":[[4,6,"P","천자"],[22,24,"P","천자"],[61,64,"P","양성초"],[80,83,"P","양씨 부인"],[188,190,"P","천자"],[233,235,"P","장연"],[271,273,"P","천자"],[299,301,"P","진량"],[336,338,"P","진량"],[394,396,"P","진량"]]},{"c":1,"sub":"","t":"간흉한 계교로 임금의 총명을 가려 충신을 해치고, 또 임금을 배반하고 도적에게 항복하였느냐. 너같이 아비도 임금도 없는 놈은 하늘이 반드시 미워할 것이다. 또 네가 나와 무슨 원수가 있기에 우리 부친을 만 리 먼 땅에서 원혼이 되게 하고, 그것도 모자라 도적에게 일러바쳐 우리 모친이 적진에서 욕을 보게 하였느냐. 너 같은 놈의 목을 베고 삼족을 멸하여 국법을 밝힌 뒤 간을 내어 사사로운 원수를 갚겠다.\" 하고 법리에게 명하여 장안 저잣거리에 효수한 뒤, 원수가 친히 칼을 잡아 진량의 배를 갈라 간을 내어 제상을 차리고 제문을 지어 부친의 영혼께 고하였다. 그런 뒤 진량의 머리를 온 나라에 돌려 보여 백성을 징계하였다.","sp":[[269,271,"P","진량"],[319,321,"P","진량"]]},{"c":1,"sub":"","t":"이튿날 황상이 충신각에 나와 앉으시어 출전한 여러 장수와 군졸에게 작위를 내리셨다. 정수정을 좌각로 평남후로 봉하시고, 한복을 특별히 장군으로 봉하시고, 남은 장졸은 차례로 작위와 상을 주시고 소와 양을 잡아 먹이고 위로하셨다. 이때 정수정이 더욱 황공하여 곧 표를 올려 벼슬을 사양하였다.","sp":[[4,6,"P","천자"],[47,50,"P","정수정"],[53,55,"P","정수정"],[56,59,"P","정수정"],[67,69,"P","한복"],[131,134,"P","정수정"]]},{"c":1,"sub":"","t":"\"좌각로 겸 평북후 정수정은 황공하여 백 번 절하고 머리를 조아려 표를 올리니, 황상께서는 굽어살피소서. 신은 본디 미천할 뿐 아니라 남자도 아니요, 여자의 몸으로 외람되이 하늘을 속여 벼슬이 일품에 이르렀으니 임금을 속인 죄와 불충이 막심합니다. 그 가운데 식읍으로 청주후를 주신 것도 신첩에게는 외람된 일이라 늘 두려운 마음에 몸 둘 바를 모르거늘, 하물며 재상의 직위는 신첩에게 더욱 천만부당하오니, 엎드려 바라건대 폐하께서는 살피시어 각로의 직임은 거두시어 조정의 체례도 중히 하시고 신첩의 마음을 편하게 해 주시기를 천만 바라옵니다.\" 하였다.","sp":[[2,4,"P","정수정"],[7,10,"P","정수정"],[11,14,"P","정수정"],[45,47,"P","천자"],[150,153,"P","정수정"],[247,249,"P","정수정"]]},{"c":1,"sub":"","t":"황상이 다 보시고 비답을 내리셨다. \"경이 비록 여자이나 재주와 용맹은 옛날 관중과 악의에 견줄 만하여 국가의 주춧돌이니, 어찌 남녀가 다르다고 동량의 재목을 잃겠는가. 경은 사양하지 마라.\" 각로가 부득이 은혜에 사례하고 절한 뒤 물러나와, 본부 군사를 거느리고 청주로 가서 모부인을 뵈었다. 천은을 축하한 뒤, 진량을 서울에서 효수하고 또 간을 내어 부친의 영혼 앞에 제사한 일을 하나하나 아뢰니, 국공 부인도 눈물을 흘리며 옛일을 생각하고 서러워하였다. 각로는 또 한복과 진시회의 공로를 특별히 나라에 아뢰어, 한복을 어림장군 겸 상부 좌익장으로 삼아 천자를 가까이 모시게 하고, 진시회를 아문장군 겸 청주 별부사마로 삼아 청주에 있게 하니, 황상이 곧 윤허하셨다.","sp":[[0,2,"P","천자"],[108,110,"P","정수정"],[176,178,"P","진량"],[225,230,"P","양씨 부인"],[257,259,"P","정수정"],[263,265,"P","한복"],[267,270,"P","진시회"],[289,291,"P","한복"],[312,314,"P","천자"],[328,331,"P","진시회"],[363,365,"P","천자"]]},{"c":1,"sub":"","t":"하루는 각로가 모부인을 모시고 지난 일을 이야기하다가, 북쪽 도적을 깨뜨릴 때 장후를 곤욕스럽게 한 일을 하나하나 아뢰었다. 모부인이 듣고 웃으며 말하였다. \"남의 아내가 되어 지아비를 너무 놀렸구나. 이다음에 집에 돌아가 아내의 자리에 있을 때 대하기가 어찌 무안하지 않으며, 도리어 제재를 받지 않을 수 없을 것이니 그때 후회가 없겠느냐.\" 각로가 웃으며 대답하였다. \"조정에 있어서는 벼슬의 체통으로 하고, 집에 있어서는 부부의 도리를 잃지 않고 각각 그 도리를 다하면 어찌 허물을 잡겠습니까.\" 이때 양성초가 옆에 모시고 있다가 웃으며 말하였다. \"누님이 아무리 큰소리를 하셔도 장후의 밑에 들 날이 많을 것이니, 나는 누님을 위하여 근심하지 않을 수 없습니다.\"","sp":[[4,6,"P","정수정"],[44,46,"P","장연"],[193,195,"P","정수정"],[284,287,"P","양성초"],[328,330,"P","장연"]]},{"c":1,"sub":"","t":"각로가 말하였다. \"양형 같은 졸장부야 어찌 내로라하고 말하겠소. 적진에 잡혀갔다가 도망해 올 때 누가 웃지 않았으며, 장후도 여러 번 적진에 싸였을 때 누가 웃지 않았겠소. 대장부로 태어나서 남에게 웃음을 받고서야 집에선들 어찌 큰소리를 하겠소.\" 양성초가 무안한 빛을 띠고 아무 말도 못 하였다.","sp":[[0,2,"P","정수정"],[11,13,"P","양성초"],[67,69,"P","장연"],[140,143,"P","양성초"]]},{"c":1,"sub":"","t":"이때 장후는 기주로 가서 모부인께 뵙고 인사를 마친 뒤, 북쪽 변방에 가서 정후에게 곤란을 당하던 앞뒤 사연을 자세히 아뢰었다. 태부인이 다 듣고 통분히 여겨 그 수치를 씻으려 하자, 원부인과 공주가 곁에 모시고 있다가 아뢰었다. \"정후의 벼슬이 각로에 이르렀으니 마음대로 제어하지 못할 것이요, 그도 대의를 알아 세 집안이 화목할 것이니 공연히 노여워하지 마소서.\" 태부인이 그렇게 여겨, 곧 사자와 시녀 수십 명에게 서간을 주어 청주로 보내, 먼 길에 다녀온 노고를 위로하였다. [?]","sp":[[3,5,"P","장연"],[42,44,"P","정수정"],[72,75,"P","양씨 부인"],[103,106,"P","위씨"],[108,110,"P","공주"],[130,132,"P","정수정"],[138,140,"P","정수정"],[206,209,"P","양씨 부인"]]},{"c":1,"sub":"","t":"이때 각로는 앞뒤의 일을 생각하고 태부인이 노여워하셨을까 염려하여 마음이 답답하던 차에, 시비가 기주에서 시녀가 왔다고 아뢰었다. 곧 불러들여 보니 시비가 문안한 뒤 태부인의 서간을 올렸다. 속으로 기뻐하며 곧 답장을 써 보내고, 이튿날 행장을 차려 기주로 가는데, 남복은 벗고 붉은 치마와 푸른 저고리를 입었으며, 투구를 벗고 눈썹을 다듬어 봉관을 썼으며, 장창과 큰 칼을 떼어 놓고 명월패를 찼으며, 좌우의 장교를 물리치고 수십 명의 시녀를 거느렸으니, 전날 남쪽을 치고 북쪽을 토벌하던 원융대장이 별안간 변하여 절세미인이 되었다.","sp":[[3,5,"P","정수정"],[19,22,"P","양씨 부인"],[93,96,"P","양씨 부인"]]},{"c":1,"sub":"","t":"이 모양으로 황금 가마를 타고 성 밖에 나오니, 별부사마 진시회가 본부 군사를 거느리고 정후의 가마를 옹위하여 기주에 이르렀다. 진시회는 성 밖에 진을 치고, 정후는 궁중으로 들어가 태부인께 뵙고 또 두 부인과 예를 마치고 자리를 정하였다. 태부인이 지난 일을 조금도 꺼려하지 않으니 정후도 다행히 여겨 정성으로 태부인을 섬기고 화목으로 두 부인과 사귀어 온 집안에 화기가 가득하였다. 그러나 장후만은 지난 일을 꺼려 정후를 마땅치 않게 여겨, 한결같이 대면하지 않고 신방의 친함이 날로 멀어졌다. 정후의 일이라면 사사건건 반대할 뿐 아니라, 궁중의 위아래 하인을 정후의 처소에는 하나도 드나들지 못하게 하였다. 이 때문에 정후는 화려한 궁중에서 무료하게 세월을 보내며 근심하는 마음이 날로 더하였으나, 그럴수록 태부인을 섬기는 효성과 두 부인과 화목하는 정성이 조금도 게을러지지 않았다. 그런데 장후는 지난날 북쪽 땅에 갔을 때 군량을 늦춘 죄로 정후가 군법을 핑계 삼아","sp":[[32,35,"P","진시회"],[49,51,"P","정수정"],[72,75,"P","진시회"],[89,91,"P","정수정"],[102,105,"P","양씨 부인"],[135,138,"P","양씨 부인"],[159,161,"P","정수정"],[175,178,"P","양씨 부인"],[220,222,"P","장연"],[234,236,"P","정수정"],[279,281,"P","정수정"],[316,318,"P","정수정"],[349,351,"P","정수정"],[399,402,"P","양씨 부인"],[446,448,"P","장연"],[475,477,"P","정수정"]]},{"c":1,"sub":"","t":"온 군중 앞에서 비할 데 없는 수치를 당하게 한 혐의가 늘 속에 맺혀 있어, 한번 그 곤란당한 앙갚음을 하고자 하였다. 그러나 원래 정후가 반듯하고 바른 터라 조그마한 허물이라도 잡을 수가 없었다. 다만 규방 안에서 제재나 주려 하였으나 그 역시 태연하고 부부의 도리에 조금도 어긋남이 없으니 어찌할 수가 없었다. 하루는 계책 하나를 생각하고, 밤이 이슥한 뒤 시녀를 불러 비단 한 필을 내어 주며 말하였다. \"네가 이것을 갖다 정후께 드리고, 내가 내일 입고 천자께 조회하러 갈 것이니 밤 안으로 조복을 지으라 하여라. 만일 시각을 지체하면 나랏일에 큰 낭패가 될 것이다.\" 시녀가 그대로 정후께 아뢰니, 정후는 벌써 나랏일을 핑계 삼아 이것으로 부부간의 허물을 잡으려는 줄 짐작하고 속으로 웃었다. 곧 등촉을 밝히고 바느질 도구를 가져다 놓고 순식간에 조복을 지어 놓고 날 밝기를 기다렸다. 이튿날 새벽에 장후가 일어나 시비를 불러 조복을 가져오라 하니,","sp":[[74,76,"P","정수정"],[240,242,"P","정수정"],[258,260,"P","천자"],[331,333,"P","정수정"],[340,342,"P","정수정"],[453,455,"P","장연"]]},{"c":1,"sub":"","t":"시비가 곧 가져왔다. 장후가 속으로 크게 놀라며 몸에 입어 보니 솜씨와 제도가 털끝만큼도 나무랄 곳이 없었다. 장후가 아무리 정후의 허물을 잡아 수치를 씻으려 하였으나 백 가지 계책에 한 가지 방책도 없었다. 다만 서로 대면하지 않고 규방을 적막하게 하여 정후의 마음이나 상하게 할 따름이었다.","sp":[[12,14,"P","장연"],[62,64,"P","장연"],[70,72,"P","정수정"],[143,145,"P","정수정"]]},{"c":1,"sub":"","t":"하루는 천자가 장연을 불러 이르셨다. \"유주 자사가 표를 올렸는데, 서번이 조공을 폐하고 배반할 뜻이 있다 하니 어찌하면 좋겠는가. 경은 방책을 생각하라.\" 장연이 몸을 굽히고 아무 말씀도 드리지 못하자 황상이 이르셨다. \"경의 아내 정후는 만고의 영웅이라 가슴속에 모략이 가득하니, 정후가 아니면 미리 방책을 세울 계책이 없다. 경은 빨리 돌아가 의논하여 짐의 마음을 편하게 하라.\" 장후가 하교를 듣고 집으로 돌아와 생각하니, 정후에게 묻지 않을 수는 없고, 물으려니 먼저 가서 대면하기가 마땅치 않았으나 다른 방책은 없었다. 또 국가의 대사라 할 수 없이, 하루는 정후의 처소로 들어가니 정후가 몸을 일으켜 맞으며 말하였다. \"상공께서 오늘은 어찌하여 누추한 곳에 오십니까?\" [?]","sp":[[4,6,"P","천자"],[8,10,"P","장연"],[88,90,"P","장연"],[114,116,"P","천자"],[131,133,"P","정수정"],[159,161,"P","정수정"],[216,218,"P","장연"],[241,243,"P","정수정"],[319,321,"P","정수정"],[332,334,"P","정수정"]]},{"c":1,"sub":"","t":"장후가 웃으며 말하였다. \"이 몸이 부인의 처소에 못 올 사람입니까?\" 하며 황상께서 하문하시던 말씀을 물으니 정후가 말하였다. \"상공께서 국가의 중임을 맡고 벼슬이 일품에 있으면서 이만한 계책을 생각하지 못하시니 어찌 동량의 재목이라 하겠습니까.\" 하며 웃음을 띠고 이야기하였다. 어느덧 밤이 깊자 두 사람이 비단 이불 속에 들어 옛 인연을 다시 이루니, 운우의 즐거움이 새로이 비할 데 없었다. 즐기다가 장후가 말하였다. \"지금도 군법을 잘 쓰시오?\" 정후가 웃으며 말하였다. \"지금이라도 쓰게 되면 쓸 뿐이지요.\"","sp":[[0,2,"P","장연"],[43,45,"P","천자"],[62,64,"P","정수정"],[228,230,"P","장연"],[255,257,"P","정수정"]]},{"c":1,"sub":"","t":"장후가 웃으며 말하였다. \"부인의 남편 된 팔자는 서러워 못 살겠구려.\" 이후로는 부부의 정의가 비할 데 없었다. 이튿날 장후가 궐내에 나가 천자를 뵙고 아뢰었다. \"서번은 미리 대비하는 것만 같지 못하오니, 어림장군 한복을 유주목으로 삼아 군사를 거느리고 대비하게 하고, 남만과 북쪽 오랑캐에 조칙을 내리시어 서번을 타이르게 하면 자연히 무사할까 합니다.\" 이것은 정후가 가르쳐 준 계책이었다. 천자가 크게 기뻐하시어 곧 한복을 유주목으로 삼아 군사를 거느리고 대비하게 하시고, 남만과 북쪽 오랑캐에 조칙을 내려 서번을 타이르게 하셨다. 과연 서번이 배반할 마음을 두지 못하고 해마다 조공을 거르지 않으니, 이후로는 나라가 태평하고 백성이 편안하여 곳곳에서 격양가를 부르고 사방에 아무 일이 없었다.","sp":[[0,2,"P","장연"],[68,70,"P","장연"],[79,81,"P","천자"],[122,124,"P","한복"],[205,207,"P","정수정"],[222,224,"P","천자"],[237,239,"P","한복"]]},{"c":1,"sub":"","t":"이때 장후는 세 부인과 함께 영화와 부귀를 누리며 슬하에 자손이 번성하였다. 정후는 아들 둘과 딸 하나를 두었는데, 큰아들로는 후사를 이어 기주를 대대로 이어받게 하고, 둘째 아들은 정국공의 제사를 받들어 청주를 대대로 이어받게 하였다. 원부인은 아들 넷과 딸 하나를 두고, 공주는 아들 셋과 딸 하나를 두었는데, 모두 아버지와 어머니의 풍모를 닮아 저마다 비범하였다. 모두 과거에 급제하여 벼슬이 문무 반열에 늘어서 일품에 이르니, 조정 전체가 다 장씨의 권세였다. 국공 부인 양씨가 여든여덟 살에 세상을 떠나니 정후 부부가 애통해 마지않았다. 황상이 들으시고 국공 부인에게 정렬부인을 추증하시고 왕후의 예로 국공과 합장하게 하셨다.","sp":[[3,5,"P","장연"],[43,45,"P","정수정"],[102,105,"P","정흠"],[133,136,"P","위씨"],[154,156,"P","공주"],[262,267,"P","양씨 부인"],[288,290,"P","정수정"],[306,308,"P","천자"],[315,320,"P","양씨 부인"],[323,327,"P","양씨 부인"],[342,344,"P","정흠"]]},{"c":1,"sub":"","t":"왕태부인도 아흔 살을 누리고 세상을 떠나니, 장후와 세 부인이 지나칠 만큼 애통해하며 예로써 선산에 안장한 뒤 삼년상을 지내고도 더욱 슬퍼하기를 그치지 않았다. 이때 태황제도 여든 살을 누리고 붕어하시니, 공주와 정·장 두 사람의 서러워함이 비할 데 없었다. 이후로 장후 부부는 태평하게 지내다가 나이 여든다섯 살에 이르렀는데, 하루는 정후가 장후와 함께 양양 물가에 가서 풍경을 구경하였다. 이때는 마침 봄 삼월 보름께였다. 채색한 배를 타고 강 한가운데 떠서 노니는데 어디로 가는지 알 수 없더니, 난데없는 한 떼의 채색 구름이 일어나며 공중에서 풍악 소리가 나고, 선관과 선녀가 내려와 정·장 두 사람을 데리고 구름에 싸여 대낮에 하늘로 올라갔다.","sp":[[0,4,"P","왕부인"],[25,27,"P","장연"],[93,96,"P","천자"],[115,117,"P","공주"],[149,151,"P","장연"],[188,190,"P","정수정"],[192,194,"P","장연"]]},{"c":1,"sub":"","t":"그 뒤 위부인과 공주도 다 여든 살을 누리고 해를 이어 세상을 떠났다. 자손이 번성하고 부귀가 넘쳐 대대로 벼슬이 끊이지 않았으며, 충효와 열절이 대대로 끊이지 않았다. 대저 여자로 태어나 하늘과 땅이 생긴 이래 충효와 열절이 고금에 짝이 없으므로, 그 기이한 사적을 기록하여 후세 여자들로 하여금 한번 읽어 보게 하노라. [?]","sp":[[4,7,"P","위씨"],[9,11,"P","공주"]]}]});
